INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('love-of-the-prophet', 'Sessions', 'Love Of The Prophet', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, author, author_short, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('love-of-the-prophet', 'Asif Hussain', 'Asif Hussain', 'حب النبي', 'ar', 'history', '<p>This book is a series of talks, delivered aloud to an audience and then set down in prose. It is not a treatise composed at a desk, but a spoken teaching, transcribed from the sessions as they were given. The one who speaks in these pages is their author: he addressed listeners directly, and his voice, rather than a scholar''s pen, is what carries the argument from first page to last.</p>', NULL, NULL, NULL, '2026-09-01T23:52:07Z', '9dcd3c856fc68c1ebd2ae397f48bd2f04fc08e61');
