INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('love-of-the-prophet', 1, 'Love Based Religion', 'Loving Rasul Allah (SWS) is the cornerstone of faith, as true love for Allah is demonstrated by following His beloved Prophet. This love is a seed nurtured by knowledge, which grows into a passionate devotion that transforms one''s character. By recognizing the universe as signs pointing to the Creator, we find ultimate felicity not in worldly pursuits but in willing submission to Allah, a submission born from this profound love.', 'lecture', 'love-of-the-prophet/audio/ep01.mp3', 'love-of-the-prophet/transcript/ep01.vtt', 2727, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('love-of-the-prophet', 2, 'Need For Messengers', 'we look at the purpose of sending messengers, and their role in our spiritual awakening.', 'lecture', 'love-of-the-prophet/audio/ep02.mp3', 'love-of-the-prophet/transcript/ep02.vtt', 3004, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('love-of-the-prophet', 3, 'Islam As An Experience', 'We look at the experience of Islam by connecting with the prophet''s experience. We study his experience of revelation and ascension.', 'lecture', 'love-of-the-prophet/audio/ep03.mp3', 'love-of-the-prophet/transcript/ep03.vtt', 3232, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('love-of-the-prophet', 4, 'Character Of The Prophet', 'we understand how the exemplary character of our prophet (Salallahu alayhi wa aalihee wa sallam) was a miracle for non-Arabs.', 'lecture', 'love-of-the-prophet/audio/ep04.mp3', 'love-of-the-prophet/transcript/ep04.vtt', 3746, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('love-of-the-prophet', 5, 'A Model For Success', 'This sermon redefines success and failure through an Islamic lens, contrasting worldly metrics with spiritual purification. It outlines ten key qualities for achieving true success, supported by Quranic principles and the lives of exemplary figures from Islamic history. The sermon also warns against the spiritual danger of heedlessness, urging a conscious return to a life of purpose. It concludes by embracing the ''strangeness'' of adhering to faith in a secular world,', 'lecture', 'love-of-the-prophet/audio/ep05.mp3', 'love-of-the-prophet/transcript/ep05.vtt', 3654, NULL);
INSERT INTO episode_chapter (slug, number, anchor_key) VALUES ('love-of-the-prophet', 1, 'love based religion');
INSERT INTO episode_chapter (slug, number, anchor_key) VALUES ('love-of-the-prophet', 2, 'need for messengers');
INSERT INTO episode_chapter (slug, number, anchor_key) VALUES ('love-of-the-prophet', 3, 'islam as an experience');
INSERT INTO episode_chapter (slug, number, anchor_key) VALUES ('love-of-the-prophet', 4, 'character of the prophet');
