INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'blurb', NULL, 'Love Of The Prophet', 0, NULL, 'This book is a series of talks, delivered aloud to an audience and then set down in prose. It is not a treatise composed at a desk, but a spoken teaching, transcribed from the sessions as they were given. The one who speaks in these pages is their author: he addressed listeners directly, and his voice, rather than a scholar''s pen, is what carries the argument from first page to last.', '', NULL, NULL, NULL, NULL, 'love of the prophet', 'this book is a series of talks delivered aloud to an audience and then set down in prose it is not a treatise composed at a desk but a spoken teaching transcribed from the sessions as they were given the one who speaks in these pages is their author he addressed listeners directly and his voice rather than a scholars pen is what carries the argument from first page to last', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'This book is a series of talks, delivered aloud to an audience and then set down in prose. It is not a treatise composed at a desk, but a spoken teaching, transcribed from the sessions as they were given. The one who speaks in these pages is their author: he addressed listeners directly, and his voice, rather than a scholar''s pen, is what carries the argument from first page to last.', '', NULL, NULL, NULL, NULL, 'love of the prophet introduction to the book', 'this book is a series of talks delivered aloud to an audience and then set down in prose it is not a treatise composed at a desk but a spoken teaching transcribed from the sessions as they were given the one who speaks in these pages is their author he addressed listeners directly and his voice rather than a scholars pen is what carries the argument from first page to last', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'introduction to the book', 'Introduction to the Book', 1, NULL, 'Across five sessions the book makes a single journey. It begins by proposing that religion, at its root, is founded upon love rather than fear or mere obligation. From there it asks why messengers are needed at all, and what work they do that could be done no other way. It then turns to Islam not as a set of propositions to be argued, but as something to be lived and experienced. The fourth session dwells on the character of the Prophet himself, and the fifth draws the whole together, holding up his life as a model for a successful human life.', '', NULL, NULL, NULL, NULL, 'love of the prophet introduction to the book', 'across five sessions the book makes a single journey it begins by proposing that religion at its root is founded upon love rather than fear or mere obligation from there it asks why messengers are needed at all and what work they do that could be done no other way it then turns to islam not as a set of propositions to be argued but as something to be lived and experienced the fourth session dwells on the character of the prophet himself and the fifth draws the whole together holding up his life as a model for a successful human life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The reader who knows nothing of this subject will find here an accessible entry, one that moves from a first principle about the nature of faith toward a concrete example to follow. The tone throughout is that of a speaker among listeners: unhurried, direct, and concerned less with the machinery of scholarship than with what a person might take to heart and carry into his own days.', '', NULL, NULL, NULL, NULL, 'love of the prophet introduction to the book', 'the reader who knows nothing of this subject will find here an accessible entry one that moves from a first principle about the nature of faith toward a concrete example to follow the tone throughout is that of a speaker among listeners unhurried direct and concerned less with the machinery of scholarship than with what a person might take to heart and carry into his own days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 0, NULL, 'So, let''s begin. أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ خَالِقِ الْوُجُودِ مِنَ الْعَدَمِ وَجَاعِلِ النُّورِ مِنَ الظُّلَامِ وَمُخْرِجِ الصَّبْرِ مِنَ الْأَلَمِ وَمُلْكِ التَّوْبَةِ إِلَى النَّدَمِ فَنَشْكُرُهُ عَلَى الْمَصَائِبِ كَمَا نَشْكُرُهُ عَلَى النِّعَمِ وَنُصَلِّي عَلَى رَسُولِهِ الْأَكْرَمِ ذِي الشَّرَفِ الْأَشَمِّ وَالنُّورِ الْأَتَمِّ وَالْكِتَابِ الْمُحْكَمِ وَكَمَالِ النَّبِيِّينَ وَالْخَاتَمِ سَيِّدِ وَلَدِ آدَمَ الَّذِي بَشَّرَ بِهِ عِيسَى ابْنُ مَرْيَمَ وَدَعَا لَهُ بِأَسَاطِيرِهِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ حِينَ كَانَ يَرْفَعُ الْقَوَاعِدَ مِنْ بَيْتِ اللَّهِ الْمُحَرَّمِ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ وَعَلَى أَتْبَاعِهِ خَيْرِ الْأُمَمِ الَّذِي بَارَكَ اللَّهُ بِهِمْ كَافَّةَ النَّاسِ الْعَرَبِ مِنْهُمْ وَالْعَجَمِ وَصَلَّى اللَّهُ عَلَى أَمِيرِ الْمُؤْمِنِينَ إِمَامِ الْأَنْزَعِ الْبَاقِينَ وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ غَالِبٍ عَلَى كُلِّ غَالِبٍ مَطْلُوبِ كُلِّ طَالِبٍ الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ نَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ وَنَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ أَرْسَلَهُ اللَّهُ تَعَالَى بِالْهُدَىٰ وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَىٰ بِاللَّهِ شَهِيدًا رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَٰهَ إِلَّا اللَّهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ خَالِقِ الْوُجُودِ مِنَ الْعَدَمِ وَجَاعِلِ النُّورِ مِنَ الظُّلَامِ وَمُخْرِجِ الصَّبْرِ مِنَ الْأَلَمِ وَمُلْكِ التَّوْبَةِ إِلَى النَّدَمِ فَنَشْكُرُهُ عَلَى الْمَصَائِبِ كَمَا نَشْكُرُهُ عَلَى النِّعَمِ وَنُصَلِّي عَلَى رَسُولِهِ الْأَكْرَمِ ذِي الشَّرَفِ الْأَشَمِّ وَالنُّورِ الْأَتَمِّ وَالْكِتَابِ الْمُحْكَمِ وَكَمَالِ النَّبِيِّينَ وَالْخَاتَمِ سَيِّدِ وَلَدِ آدَمَ الَّذِي بَشَّرَ بِهِ عِيسَى ابْنُ مَرْيَمَ وَدَعَا لَهُ بِأَسَاطِيرِهِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ حِينَ كَانَ يَرْفَعُ الْقَوَاعِدَ مِنْ بَيْتِ اللَّهِ الْمُحَرَّمِ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ وَعَلَى أَتْبَاعِهِ خَيْرِ الْأُمَمِ الَّذِي بَارَكَ اللَّهُ بِهِمْ كَافَّةَ النَّاسِ الْعَرَبِ مِنْهُمْ وَالْعَجَمِ وَصَلَّى اللَّهُ عَلَى أَمِيرِ الْمُؤْمِنِينَ إِمَامِ الْأَنْزَعِ الْبَاقِينَ وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ غَالِبٍ عَلَى كُلِّ غَالِبٍ مَطْلُوبِ كُلِّ طَالِبٍ الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ نَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ وَنَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ أَرْسَلَهُ اللَّهُ تَعَالَى بِالْهُدَىٰ وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَىٰ بِاللَّهِ شَهِيدًا رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَٰهَ إِلَّا اللَّهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', NULL, NULL, NULL, 'love of the prophet love based religion', 'so lets begin اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله خالق الوجود من العدم وجاعل النور من الظلام ومخرج الصبر من الالم وملك التوبه الي الندم فنشكره علي المصايب كما نشكره علي النعم ونصلي علي رسوله الاكرم ذي الشرف الاشم والنور الاتم والكتاب المحكم وكمال النبيين والخاتم سيد ولد ادم الذي بشر به عيسي ابن مريم ودعا له باساطيره ابراهيم عليه السلام حين كان يرفع القواعد من بيت الله المحرم صلي الله عليه وعلي اله وسلم وعلي اتباعه خير الامم الذي بارك الله بهم كافه الناس العرب منهم والعجم وصلي الله علي امير المومنين امام الانزع الباقين وقايد الغر المحجلين غالب علي كل غالب مطلوب كل طالب الحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه نعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله خالق الوجود من العدم وجاعل النور من الظلام ومخرج الصبر من الالم وملك التوبه الي الندم فنشكره علي المصايب كما نشكره علي النعم ونصلي علي رسوله الاكرم ذي الشرف الاشم والنور الاتم والكتاب المحكم وكمال النبيين والخاتم سيد ولد ادم الذي بشر به عيسي ابن مريم ودعا له باساطيره ابراهيم عليه السلام حين كان يرفع القواعد من بيت الله المحرم صلي الله عليه وعلي اله وسلم وعلي اتباعه خير الامم الذي بارك الله بهم كافه الناس العرب منهم والعجم وصلي الله علي امير المومنين امام الانزع الباقين وقايد الغر المحجلين غالب علي كل غالب مطلوب كل طالب الحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه نعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 1, NULL, 'Once again, سَلَامٌ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ. So, as Muslims, learning about our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, and learning about the respect and the deference that is due to him is extremely important, because the Prophet has rights over us. And so I want to begin by exploring a verse from the Quran and a hadith that complements the verse. So اللَّه says in the Quran, قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'once again سلام عليكم ورحمه الله وبركاته so as muslims learning about our prophet صلي الله عليه وسلم and learning about the respect and the deference that is due to him is extremely important because the prophet has rights over us and so i want to begin by exploring a verse from the quran and a hadith that complements the verse so الله says in the quran قل ان كنتم تحبون الله فاتبعوني يحببكم الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 2, NULL, 'اللَّه is commanding the Prophet to say, that tell these people, say, if you love اللَّه, then follow me, meaning the Prophet, and اللَّه will love you. Similarly, in a hadith, our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he said, لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ. None of you truly believe until I am more beloved to him than his wealth, his parents, his children, and even his own soul.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'الله is commanding the prophet to say that tell these people say if you love الله then follow me meaning the prophet and الله will love you similarly in a hadith our prophet صلي الله عليه وسلم he said لا يومن احدكم حتي اكون احب اليه من والده وولده والناس اجمعين none of you truly believe until i am more beloved to him than his wealth his parents his children and even his own soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 3, NULL, 'Now the question is, how is my belief in اللَّه, my إِيمَان, dependent on whether I love the Prophet or not? What does it even mean to love the Prophet? Because this is a very profound statement. The Prophet said that a man''s faith, his إِيمَان, is not complete until we actually love him more than we love anything in the world, anything that''s precious to us. And he named those things, right? Parents, children, all people, including the self, because we all love ourselves. Jesus said, love your neighbor as yourself. And the assumption there in that statement is that we love ourselves. So love them like we love ourselves. And that''s part of human nature, that اللهُ سُبْحَانَهُ وَتَعَالَى, he made us love ourselves. It''s a means for our survival. But what''s really interesting to me is that according to this verse and this narration, the key to a successful إِيمَان is love.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'now the question is how is my belief in الله my ايمان dependent on whether i love the prophet or not what does it even mean to love the prophet because this is a very profound statement the prophet said that a mans faith his ايمان is not complete until we actually love him more than we love anything in the world anything thats precious to us and he named those things right parents children all people including the self because we all love ourselves jesus said love your neighbor as yourself and the assumption there in that statement is that we love ourselves so love them like we love ourselves and thats part of human nature that الله سبحانه وتعالي he made us love ourselves its a means for our survival but whats really interesting to me is that according to this verse and this narration the key to a successful ايمان is love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 4, NULL, 'Because that''s what he said. No one of you is a believer until you love me. So he connected love with إِيمَان. Now, what is love? Love is actually an amazing word in Arabic. There are many words for love in the Arabic language, but the essential word is حُبٌّ. In Arabic, that''s the essential word. Our Prophet is حَبِيبُ اللهِ. He is the beloved of اللَّه. All messengers have titles, right? كَلِيمُ ٱللَّهِ, that''s مُوسَى, because he spoke with اللَّه. خَلِيلُ اللهِ is إِبْرَاهِيم, because he was the friend of اللَّه.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'because thats what he said no one of you is a believer until you love me so he connected love with ايمان now what is love love is actually an amazing word in arabic there are many words for love in the arabic language but the essential word is حب in arabic thats the essential word our prophet is حبيب الله he is the beloved of الله all messengers have titles right كليم الله thats موسي because he spoke with الله خليل الله is ابراهيم because he was the friend of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 5, NULL, 'عِشْق is رُوحُ اللهِ because he brought the dead to life. So all of these prophets, they received a title, but our Prophet is given the title حَبِيبُ اللهِ, the beloved of اللَّه. And this title is obviously superior to all the other titles, because the one you love transcends speech. Because the nature of love is that it''s inexpressible, right? The English word love is an old English word that goes back to a Saxon word. And it relates to being pleased with something. Now, interesting enough, the word إِيمَان is also related to love. How? Because you believe in what you''re pleased with, right? You believe what you love. The things that your heart accepts are the things that you believe.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'عشق is روح الله because he brought the dead to life so all of these prophets they received a title but our prophet is given the title حبيب الله the beloved of الله and this title is obviously superior to all the other titles because the one you love transcends speech because the nature of love is that its inexpressible right the english word love is an old english word that goes back to a saxon word and it relates to being pleased with something now interesting enough the word ايمان is also related to love how because you believe in what youre pleased with right you believe what you love the things that your heart accepts are the things that you believe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 6, NULL, 'So in Arabic, the word حُبٌّ, which is the word our Prophet used, no one is a true believer until I am beloved to him. If you look at the root meaning of the word حُبٌّ, it actually means seed. حُبًّا is a seed in Arabic. Now, what do you have to do to make a seed grow? You have to nurture it. So love is a seed that''s nurtured with the knowledge of the beloved. The more you nurture the seed with water, the more it grows. The more you learn about the beloved, the more you will love the beloved. So as we get to know the Prophet and as we get to know him intimately, the deeper we will fall in love. And the deeper we fall in love with him, the more it will transform us. Because love by its nature engenders within us a desire to become what the beloved loves, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'so in arabic the word حب which is the word our prophet used no one is a true believer until i am beloved to him if you look at the root meaning of the word حب it actually means seed حبا is a seed in arabic now what do you have to do to make a seed grow you have to nurture it so love is a seed thats nurtured with the knowledge of the beloved the more you nurture the seed with water the more it grows the more you learn about the beloved the more you will love the beloved so as we get to know the prophet and as we get to know him intimately the deeper we will fall in love and the deeper we fall in love with him the more it will transform us because love by its nature engenders within us a desire to become what the beloved loves right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 7, NULL, 'And then another beautiful aspect of a seed, a حُبًّا, is that it produces an endless harvest. You begin by nurturing the seeds, which ends in a harvest, right? You gather the yield of one season, but then what happens the next season? It grows again. You harvest it, it grows again. Again, you harvest it, again it grows. So love or حُبُّ النَّبِيِّ is the same, where it just keeps on growing indefinitely, there''s no end to it. It keeps increasing in intensity with time. One of the descriptions of love they say is it is friendship on fire. That''s how they describe love. That it is something that begins to consume you, right? It turns into .', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'and then another beautiful aspect of a seed a حبا is that it produces an endless harvest you begin by nurturing the seeds which ends in a harvest right you gather the yield of one season but then what happens the next season it grows again you harvest it it grows again again you harvest it again it grows so love or حب النبي is the same where it just keeps on growing indefinitely theres no end to it it keeps increasing in intensity with time one of the descriptions of love they say is it is friendship on fire thats how they describe love that it is something that begins to consume you right it turns into', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 8, NULL, 'And people have accomplished this at remarkable levels in our tradition. You know, we have people from our tradition who literally died in the love of the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. That''s how much they loved him. They literally died. We have stories of people that bled tears of blood. And tears of blood, which is an old blues motif for people who know anything about American music. You know, there''s that song, I''m crying tears of blood for you. Tears of blood are actually real, because when somebody gets into this very intense state, those little blood vessels in the eyes, they burst. And so tears of blood is a real thing. I think in medical terms, I think it''s called hemolacria or something.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'and people have accomplished this at remarkable levels in our tradition you know we have people from our tradition who literally died in the love of the prophet صلي الله عليه وسلم thats how much they loved him they literally died we have stories of people that bled tears of blood and tears of blood which is an old blues motif for people who know anything about american music you know theres that song im crying tears of blood for you tears of blood are actually real because when somebody gets into this very intense state those little blood vessels in the eyes they burst and so tears of blood is a real thing i think in medical terms i think its called hemolacria or something', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 9, NULL, 'But there is something, I mean, poets use this all the time in their poetry, this concept of tears of blood. That just by remembering the places the beloved used to go, caused people to weep these tears of blood. So there are people in our tradition who have literally died from عِشْق. Now this word عِشْق is another amazing word in the Arabic language. It comes from the root word أَشَاقَكَ, which is a type of vine that begins to grow around a tree and strangles it, eventually killing the tree. So the metaphor is that, you know, this tree, it falls in love with this vine and it offers up all of its nourishment to feed its beloved, right? And starves to death in the process. So it''s such a beautiful metaphor. And this is something, you know, only someone who has ever experienced this type of true love can really appreciate these things. If you''ve never tasted love, I mean, this is going to seem ridiculous to you. But if you ask the عِشْق, right, if you ask the one in love, that starvation in the service of the beloved, to please the beloved, is like the most beautiful experience of his life.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'but there is something i mean poets use this all the time in their poetry this concept of tears of blood that just by remembering the places the beloved used to go caused people to weep these tears of blood so there are people in our tradition who have literally died from عشق now this word عشق is another amazing word in the arabic language it comes from the root word اشاقك which is a type of vine that begins to grow around a tree and strangles it eventually killing the tree so the metaphor is that you know this tree it falls in love with this vine and it offers up all of its nourishment to feed its beloved right and starves to death in the process so its such a beautiful metaphor and this is something you know only someone who has ever experienced this type of true love can really appreciate these things if youve never tasted love i mean this is going to seem ridiculous to you but if you ask the عشق right if you ask the one in love that starvation in the service of the beloved to please the beloved is like the most beautiful experience of his life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 10, NULL, 'The Arabs say, , that this type of crazy mad love is a deadly disease that can only be cured by a connection, by being connected with the beloved. It can only be cured by a union with the beloved, right? So the love of the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ can really take hold of the heart as you get to know who he was and what he did for us. Now, when you love somebody, you constantly remember them, right? That''s one of the qualities of love. You constantly think about them. That''s what happens when you fall in love. You call them up, you know, oh, I''m just thinking about you. I can''t stop thinking about you, right? That''s real, isn''t it? It''s real.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'the arabs say that this type of crazy mad love is a deadly disease that can only be cured by a connection by being connected with the beloved it can only be cured by a union with the beloved right so the love of the prophet صلي الله عليه وسلم can really take hold of the heart as you get to know who he was and what he did for us now when you love somebody you constantly remember them right thats one of the qualities of love you constantly think about them thats what happens when you fall in love you call them up you know oh im just thinking about you i cant stop thinking about you right thats real isnt it its real', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 11, NULL, 'I just can''t stop thinking about you. I mean, why is that pressing on the heart? Because you''re in love. And that''s what love is. You know, I just can''t stop thinking about you. You write poems. What is that? It''s a fusion that''s coming out of your heart to write these poems. Really? And people write the worst poems when they''re in love. But it doesn''t matter, because they would never do it if they weren''t in love. Because they would know how ridiculous it is.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'i just cant stop thinking about you i mean why is that pressing on the heart because youre in love and thats what love is you know i just cant stop thinking about you you write poems what is that its a fusion thats coming out of your heart to write these poems really and people write the worst poems when theyre in love but it doesnt matter because they would never do it if they werent in love because they would know how ridiculous it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 12, NULL, 'But it doesn''t matter because, you know, there has to be some kind of تَآبِير when you have this kind of love, you know, some kind of expression. in Arabic is what you express, right? The word , which is also used in Urdu, right? The word means a discerning lesson, like a moral lesson that you gain from an experience. And the word for a bridge in Arabic, it''s because it helps you cross over. So you get from one side of the mountain to another through that bridge. From one side of the river to another. So a discerning lesson is the same way. You cross over from the state of ignorance to the state of knowledge. And then that experience of that profound realization that you got out of that discernment, what does that do? It brings out the tears, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'but it doesnt matter because you know there has to be some kind of تابير when you have this kind of love you know some kind of expression in arabic is what you express right the word which is also used in urdu right the word means a discerning lesson like a moral lesson that you gain from an experience and the word for a bridge in arabic its because it helps you cross over so you get from one side of the mountain to another through that bridge from one side of the river to another so a discerning lesson is the same way you cross over from the state of ignorance to the state of knowledge and then that experience of that profound realization that you got out of that discernment what does that do it brings out the tears right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 13, NULL, 'That''s why a tear in Arabic is called أَبَرَّ. أَبَرَّ actually means a tear, because it crosses over from inside your eyes onto your cheeks. So you can see how all these different meanings, they connect with the same root. I mean, this is why I find Arabic such a beautiful language, سُبْحَانَ اللَّهِ. Also, you have that word, right? Even in Urdu, which means trust, comes from the same root, أَبَرَّ. Because trust is like a bridge between two people that keeps them connected. The path is open both ways. You break that trust, that bridge collapses, right? So this is Arabic linguistics, where everything is, you know, all the different variations that stem out of a root are always connected in meaning. Anyway, so what I was saying is that these emotions of love, right, they need a تَبِير, they need an expression, they have to come out. They need to cross over from inside the heart and manifest into actions.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'thats why a tear in arabic is called ابر ابر actually means a tear because it crosses over from inside your eyes onto your cheeks so you can see how all these different meanings they connect with the same root i mean this is why i find arabic such a beautiful language سبحان الله also you have that word right even in urdu which means trust comes from the same root ابر because trust is like a bridge between two people that keeps them connected the path is open both ways you break that trust that bridge collapses right so this is arabic linguistics where everything is you know all the different variations that stem out of a root are always connected in meaning anyway so what i was saying is that these emotions of love right they need a تبير they need an expression they have to come out they need to cross over from inside the heart and manifest into actions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 14, NULL, 'Because love has significance. And when something has significance, it begins to affect the heart. And this is why even the remnants of the beloved become valuable to the lover. Even the remnants. This is جَاهِلِيّ poetry, this is ancient Arabic, you know, this is poetry of Imru al-Qais, where he says, let''s stop my friends, let''s stop and look here at where the beloved used to be. And let''s weep over the traces of the beloved, you know, just to look at these traces. I think these were people that really knew what love was. Seriously, they had a deep and profound understanding of love. They really understood love. And they were extremely intense in their love. Not like this modern day ridiculous love that is portrayed by Hollywood and Bollywood, in which this guy is chasing a girl around a tree and singing songs, or this kind of superficial love that begins in a cafe and ends in a bedroom. No.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'because love has significance and when something has significance it begins to affect the heart and this is why even the remnants of the beloved become valuable to the lover even the remnants this is جاهلي poetry this is ancient arabic you know this is poetry of imru al qais where he says lets stop my friends lets stop and look here at where the beloved used to be and lets weep over the traces of the beloved you know just to look at these traces i think these were people that really knew what love was seriously they had a deep and profound understanding of love they really understood love and they were extremely intense in their love not like this modern day ridiculous love that is portrayed by hollywood and bollywood in which this guy is chasing a girl around a tree and singing songs or this kind of superficial love that begins in a cafe and ends in a bedroom no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 15, NULL, 'That''s not love. That''s just lust. It has nothing to do with love. But these ancient Arabs, they really knew what true love was. That real experience of intense love. So, that''s one of the motifs of just بُكَاءٌ عَلَى الْأَطْلَالِ, you know, just weeping over the places where the beloved used to be. أَمُرُّ عَلَى الدِّيَارِ دِيَارِ لَيْلَى. أُقَبِّلُ ذَا الْجِدَارَ وَذَا الْجِدَارَا. You know, I passed by the house of Laila, and I kissed the walls of the house. This is just so beautiful, right? I kissed the walls of the house, but it''s not the walls. It''s not the walls that have enraptured my heart, but the love of the one that used to live between these walls.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'thats not love thats just lust it has nothing to do with love but these ancient arabs they really knew what true love was that real experience of intense love so thats one of the motifs of just بكاء علي الاطلال you know just weeping over the places where the beloved used to be امر علي الديار ديار ليلي اقبل ذا الجدار وذا الجدارا you know i passed by the house of laila and i kissed the walls of the house this is just so beautiful right i kissed the walls of the house but its not the walls its not the walls that have enraptured my heart but the love of the one that used to live between these walls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 16, NULL, 'I mean, this is why we travel to Makkah and Medina, right? This is why we go for زِيَارَة, to Najaf, to Karbala. It''s not the places. It''s not these stones. It''s the beloved who used to live there. It''s because the feet of the beloved walked that ground. And at the end of the day, this is what it''s all about, right? That''s all this is. I mean, these places, these walls, they''re just hiding the eternal love of God. That''s what this world is, according to our الْإِسْلَامic theology. When you begin to recognize this underlying emotion of love, you realize that that is essentially what you love about this world, not the دُنْيَا, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'i mean this is why we travel to makkah and medina right this is why we go for زياره to najaf to karbala its not the places its not these stones its the beloved who used to live there its because the feet of the beloved walked that ground and at the end of the day this is what its all about right thats all this is i mean these places these walls theyre just hiding the eternal love of god thats what this world is according to our الاسلامic theology when you begin to recognize this underlying emotion of love you realize that that is essentially what you love about this world not the دنيا right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 17, NULL, 'اللَّه praised himself by calling him رَبُّ الْعَالَمِينَ. ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, not رَبُّ الدُّنْيَا. Right? He said, praise and gratitude be to اللَّه who is the رَبٌّ of الْأَمِين. The الَمْ is what the Arabs call الِاسْمُ الْأَعْلَى, right? They call it a noun of instrument. This الَمْ is an instrument of عِلْمٌ. It''s an instrument by which you gain knowledge, you come to know of something. And what you come to know using this instrument of this world is the الْأَمِين, which is اللهُ سُبْحَانَهُ وَتَعَالَى. This world, this universe is God''s vehicle for giving us knowledge. And this is why things are so important to us, right? This is why أَشِيَّة, possessions, are important. This is why property is one of the essential reasons why we were given the ﻿شَرِيعَة. It is to protect property because possessions are important. Why? Because they give us meaning, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'الله praised himself by calling him رب العالمين الحمد لله رب العلمين not رب الدنيا right he said praise and gratitude be to الله who is the رب of الامين the الم is what the arabs call الاسم الاعلي right they call it a noun of instrument this الم is an instrument of علم its an instrument by which you gain knowledge you come to know of something and what you come to know using this instrument of this world is the الامين which is الله سبحانه وتعالي this world this universe is gods vehicle for giving us knowledge and this is why things are so important to us right this is why اشيه possessions are important this is why property is one of the essential reasons why we were given the شريعه it is to protect property because possessions are important why because they give us meaning right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 18, NULL, 'Your possessions are your instruments through which you create meanings in your life. And the Prophet, this is why the Prophet used to name all of his things. I mean, he didn''t have many things, but the things that he did have, he always named them because they had meaning. And that is what this world is to a believer. It''s all meaning. The whole thing is مَعْنَى. The poet says, ... that this whole cosmos is just meaning set up in images. This entire universe is just meaning set up in images, and whoever understands that is from the people of discernment, the people of عِبَر. اللَّه says in the Quran, think deeply, reflect, look at this world with a discerning eye. That''s where you get عِبْرَة. And then the عِبْرَة leads to أَبْرَهَ, you know, that''s when the tears come. Because tears, they always come from the perception of meaning. You know, somebody gives you a really meaningful gift. Why do you start crying?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'your possessions are your instruments through which you create meanings in your life and the prophet this is why the prophet used to name all of his things i mean he didnt have many things but the things that he did have he always named them because they had meaning and that is what this world is to a believer its all meaning the whole thing is معني the poet says that this whole cosmos is just meaning set up in images this entire universe is just meaning set up in images and whoever understands that is from the people of discernment the people of عبر الله says in the quran think deeply reflect look at this world with a discerning eye thats where you get عبره and then the عبره leads to ابره you know thats when the tears come because tears they always come from the perception of meaning you know somebody gives you a really meaningful gift why do you start crying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 19, NULL, 'Why does that happen? Because your heart gets moved by that. It''s not the gift. It''s the emotion with which that gift was given. That brings the tears out, right? So meaning is a great gift that اللَّه has given us. And this is why the Quran, it calls its verses آيَات, which actually means signs literally, you know, and آيَاتٌ in Arabic is a sign. Now considering the fact that the Quran is a book, right, it''s a كِتَابٌ, you would think that اللَّه would have called this message, this text, sentences within paragraphs, within chapters, right? Because that''s what a book contains. But no, اللَّه calls them آيَاتٌ, which are signs. Why?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'why does that happen because your heart gets moved by that its not the gift its the emotion with which that gift was given that brings the tears out right so meaning is a great gift that الله has given us and this is why the quran it calls its verses ايات which actually means signs literally you know and ايات in arabic is a sign now considering the fact that the quran is a book right its a كتاب you would think that الله would have called this message this text sentences within paragraphs within chapters right because thats what a book contains but no الله calls them ايات which are signs why', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 20, NULL, 'Because by definition, a sign or a symbol is something that points to something else. A sign is always a means to an end. It is never the end itself. If I see a sign that says hospital 10 miles ahead, right, my goal and my final destination is the hospital, not the sign that reads hospital 10 miles ahead. So the verses of the Quran are called آيَاتٌ because they are markers, they are signs pointing to something else. What are they pointing to? They''re pointing to the signs within the universe, signs within creations. So you have آيَاتُ الْقُرْآنِ, the signs of the Quran, pointing to آيَاتُ الْكَوْنَيْنِ, the signs within cosmos, within creation, within universe, within the soul itself. Now for a believer, what are the signs of the cosmos pointing to? They''re pointing him back to آيَاتُ الْقُرْآنِ, the signs of the Quran. So a believer is constantly in this loop. He''s moving between these two signs. The signs of the Quran direct him to the signs within the creation, and then the signs of creation point him back to the signs of the Quran, and together they both point to the creator of both, which is اللَّهُ سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'because by definition a sign or a symbol is something that points to something else a sign is always a means to an end it is never the end itself if i see a sign that says hospital 10 miles ahead right my goal and my final destination is the hospital not the sign that reads hospital 10 miles ahead so the verses of the quran are called ايات because they are markers they are signs pointing to something else what are they pointing to theyre pointing to the signs within the universe signs within creations so you have ايات القران the signs of the quran pointing to ايات الكونين the signs within cosmos within creation within universe within the soul itself now for a believer what are the signs of the cosmos pointing to theyre pointing him back to ايات القران the signs of the quran so a believer is constantly in this loop hes moving between these two signs the signs of the quran direct him to the signs within the creation and then the signs of creation point him back to the signs of the quran and together they both point to the creator of both which is الله سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 21, NULL, 'You see? That''s why it calls its verses آيَات. Now, how do we interpret signs? The human being, unlike any other creation, has been given this gift of an intellect, which is essentially the tool to recognize signs. That''s what the intellect is, right? You see dark clouds? You recognize it as a sign that it''s going to rain. Right? You see smoke, you recognize it as a sign that there is going to be, there''s some fire or some heat somewhere. That''s what the intellect is designed to do. It''s the same thing with language. It is made up of signs and symbols, alphabets.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'you see thats why it calls its verses ايات now how do we interpret signs the human being unlike any other creation has been given this gift of an intellect which is essentially the tool to recognize signs thats what the intellect is right you see dark clouds you recognize it as a sign that its going to rain right you see smoke you recognize it as a sign that there is going to be theres some fire or some heat somewhere thats what the intellect is designed to do its the same thing with language it is made up of signs and symbols alphabets', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 22, NULL, 'Right? Symbols put together. If I read a sentence, this is a book. I don''t just stop at seeing those individual letters and symbols. I put them together, right? The T, the H, the I, the S, right? Because on their own, they mean nothing. The letters mean nothing. The alphabets mean nothing. If I wasn''t illiterate or if I was unlettered, then all I would see is some symbols put together that mean nothing to me. But because I''m literate, الْحَمْدُ لِلَّهِ, I can interpret the letters.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'right symbols put together if i read a sentence this is a book i dont just stop at seeing those individual letters and symbols i put them together right the t the h the i the s right because on their own they mean nothing the letters mean nothing the alphabets mean nothing if i wasnt illiterate or if i was unlettered then all i would see is some symbols put together that mean nothing to me but because im literate الحمد لله i can interpret the letters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 23, NULL, 'I can put them together and I can read that what this is saying is this is a book, and I can understand what it means. So these symbols, they translate into meaning for me, right? Same way this universe and everything within it are signs that signify اللَّه''s oneness. The آيَاتٌ of the cosmos and the self, they mean something. They read something. What do they read? سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ. We will keep showing them our signs in the horizons and within their souls until it becomes absolutely clear to them that all of this is from الْحَقُّ. All of this is a sign of اللَّه. That''s what the signs of the universe means. All of this is from God. And just as a literate person can read language, a literate intellectual, a believer, he can read this world. Believers can read their own souls.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'i can put them together and i can read that what this is saying is this is a book and i can understand what it means so these symbols they translate into meaning for me right same way this universe and everything within it are signs that signify اللهs oneness the ايات of the cosmos and the self they mean something they read something what do they read سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق we will keep showing them our signs in the horizons and within their souls until it becomes absolutely clear to them that all of this is from الحق all of this is a sign of الله thats what the signs of the universe means all of this is from god and just as a literate person can read language a literate intellectual a believer he can read this world believers can read their own souls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 24, NULL, 'So a believer is someone whose consciousness is literate. He can see what the signs of the world are pointing to. They''re pointing to اللَّه''s existence, to اللَّه''s oneness, اللَّه''s reality, اللَّه''s awesome majesty, اللَّه''s immeasurable beauty, His infinite mercy, also His wrath. It points to اللَّه''s kingship, سُلْطَان, right? سُبْحَانَهُ وَتَعَالَى. So from that perspective, we all have access to the existence of God. I mean, you don''t even need the Quran to read this cosmos and come to the conclusion that it has a creator. If you are utilizing and fulfilling the power of your intellect. If you can read the signs. And once you reach that conclusion on your own that this cosmos has to have a creator, all the Quran does, it just clarifies things for you about the creator.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'so a believer is someone whose consciousness is literate he can see what the signs of the world are pointing to theyre pointing to اللهs existence to اللهs oneness اللهs reality اللهs awesome majesty اللهs immeasurable beauty his infinite mercy also his wrath it points to اللهs kingship سلطان right سبحانه وتعالي so from that perspective we all have access to the existence of god i mean you dont even need the quran to read this cosmos and come to the conclusion that it has a creator if you are utilizing and fulfilling the power of your intellect if you can read the signs and once you reach that conclusion on your own that this cosmos has to have a creator all the quran does it just clarifies things for you about the creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 25, NULL, 'Who is he? What does he want? Why does he want it? That sort of stuff. Now, according to our الْإِسْلَامic theology, what is the purpose of human beings? Why did اللَّه create human beings? The ultimate purpose of creating human beings is to know God. To recognize the oneness of اللَّه. And to know God is to love God. So تَوْحِيد then becomes the ultimate purpose of creation according to the Quran. That''s what God wants. He wants us to make him unique in his life.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'who is he what does he want why does he want it that sort of stuff now according to our الاسلامic theology what is the purpose of human beings why did الله create human beings the ultimate purpose of creating human beings is to know god to recognize the oneness of الله and to know god is to love god so توحيد then becomes the ultimate purpose of creation according to the quran thats what god wants he wants us to make him unique in his life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 26, NULL, '‏قُلْ هُوَ ٱللَّهُ أَحَدٌ ‎, say that اللَّه is unique. That''s what اللَّه wants. What about us? What do we as human beings ultimately want? Not Muslims, just as human beings, irrespective of race, creed, religion, you know, what do we ultimately want? We all ultimately, what we''re searching for, what we''re looking for is سَعَادَة, felicity. We want to be happy. But in the الْإِسْلَامic tradition, happiness is not a state. Happiness is not a state you can be in. Like you can''t be happy. You can feel happy.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'قل هو الله احد say that الله is unique thats what الله wants what about us what do we as human beings ultimately want not muslims just as human beings irrespective of race creed religion you know what do we ultimately want we all ultimately what were searching for what were looking for is سعاده felicity we want to be happy but in the الاسلامic tradition happiness is not a state happiness is not a state you can be in like you cant be happy you can feel happy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 27, NULL, 'But you can''t be happy at any point in your life. Happiness is actually the sum total of your life. It''s the end result of your life, whether you lived a happy life or whether you lived a miserable life. I mean, that''s the sum total. And that is calculated based on what you did in your life or how you lived your life, right? According to the Greeks, it was all about virtuous living, what they called أَرَتِهْ, you know, which was a life of excellence. This word أَرَتِهْ in our tradition, it translates to the same thing as إِحْسَان. You know, you have الْإِسْلَام, إِيمَان and إِحْسَان. So the whole purpose of life is happiness. There''s no other purpose. Our purpose is سَعَادَة.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'but you cant be happy at any point in your life happiness is actually the sum total of your life its the end result of your life whether you lived a happy life or whether you lived a miserable life i mean thats the sum total and that is calculated based on what you did in your life or how you lived your life right according to the greeks it was all about virtuous living what they called ارته you know which was a life of excellence this word ارته in our tradition it translates to the same thing as احسان you know you have الاسلام ايمان and احسان so the whole purpose of life is happiness theres no other purpose our purpose is سعاده', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 28, NULL, 'And سَعَادَة, or this happiness, this felicity, unlike anything else in life is an end. Not a means. Everything else is a means. If you ask people what they want, you know, average people that haven''t really thought deeply about things, if you just say, you know, what do you want out of life? Well, you know, I want to have a family. I want to be successful. I want this degree. I want to make lots of money. Or, you know, I want to look sexy or have six pack abs or want to be fashionable, dress a certain way, be looked a certain way, whatever. I mean, they''ll give you a lot of different reasons. But then if you start probing those reasons, why do you want money?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'and سعاده or this happiness this felicity unlike anything else in life is an end not a means everything else is a means if you ask people what they want you know average people that havent really thought deeply about things if you just say you know what do you want out of life well you know i want to have a family i want to be successful i want this degree i want to make lots of money or you know i want to look sexy or have six pack abs or want to be fashionable dress a certain way be looked a certain way whatever i mean theyll give you a lot of different reasons but then if you start probing those reasons why do you want money', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 29, NULL, 'Why do you want power? Well, it enables me to be free. You know, I can do things that I can''t do without money. Why do you want to be free? Why do you want to do those things? And if you keep probing that way, right, the end result is always, always happiness. Because in the end we want to be happy. We want to be in a state of contentment. So felicity, happiness, is the essence of what we as human beings are out for. But most people don''t realize that, and they don''t understand the difference between, you know, what''s really good and what''s apparently good. You know, like people think that fame is good in itself.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'why do you want power well it enables me to be free you know i can do things that i cant do without money why do you want to be free why do you want to do those things and if you keep probing that way right the end result is always always happiness because in the end we want to be happy we want to be in a state of contentment so felicity happiness is the essence of what we as human beings are out for but most people dont realize that and they dont understand the difference between you know whats really good and whats apparently good you know like people think that fame is good in itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 30, NULL, 'So there are all these people who just want to be famous. They want to be known. Or they think that stature is a thing that''s good to have. Or, you know, they think money will make them happy. So they''ll sacrifice the real good in their life. Like family, like health, like peace of mind, relationships, like character, like modesty, like courage, like generosity. These are the real goods, but they''ll sacrifice them for what they deem to be the ultimate good in life, what is apparently good.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'so there are all these people who just want to be famous they want to be known or they think that stature is a thing thats good to have or you know they think money will make them happy so theyll sacrifice the real good in their life like family like health like peace of mind relationships like character like modesty like courage like generosity these are the real goods but theyll sacrifice them for what they deem to be the ultimate good in life what is apparently good', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 31, NULL, 'Right now, what Revelation does is that it turns this idea on its head, that there is no سَعَادَة in the دُنْيَا. You can''t get it, because no matter what you have, you can lose it. That if you''re in good health right now, you can drop dead. If you''re rich, you can become poor. If you''re beautiful today, you''ll wrinkle and shrivel up in time. If you''re strong, you''ll become weak with age, right? History is filled with examples.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'right now what revelation does is that it turns this idea on its head that there is no سعاده in the دنيا you cant get it because no matter what you have you can lose it that if youre in good health right now you can drop dead if youre rich you can become poor if youre beautiful today youll wrinkle and shrivel up in time if youre strong youll become weak with age right history is filled with examples', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 32, NULL, 'Even the things you have and you do enjoy right now, the means, you only enjoy them for a short amount of time before you just want something new. Something else, something more, right? I have the iPhone 11, can''t wait for the new iPhone 12. Why? Cause I think that''s what''s gonna make me happy. So we''re completely enslaved to these means, the wealth, power, fame, body, stature, how many likes we get on Facebook. And we don''t even realize how enslaved we are. Put your phone away for one hour, I challenge you. Turn your phone off for one hour, kids, right? My daughter starts having convulsions when her phone, the internet is not working. I mean, that''s addiction, that''s slavery. So these illusory means to the ultimate end goal of happiness.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'even the things you have and you do enjoy right now the means you only enjoy them for a short amount of time before you just want something new something else something more right i have the iphone 11 cant wait for the new iphone 12 why cause i think thats whats gonna make me happy so were completely enslaved to these means the wealth power fame body stature how many likes we get on facebook and we dont even realize how enslaved we are put your phone away for one hour i challenge you turn your phone off for one hour kids right my daughter starts having convulsions when her phone the internet is not working i mean thats addiction thats slavery so these illusory means to the ultimate end goal of happiness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 33, NULL, 'In reality, these are chains, these are shackles that keep us trapped in the دُنْيَا. So the Quran puts forth a proposition. It invites us to freedom from everything. You see? It calls us towards freedom from everything. How? By becoming the willing slaves of اللَّه. It creates this paradigm shift. It switches our focus from these millions of means that we think are going to take us to the end of happiness. It switches our focus on one central entity, which is اللَّه, the ultimate end goal of happiness. It doesn''t stop us from acquiring things, but it changes the perspective and the meaning of those things, that I can enjoy everything this الَمْ has to offer, because it brings me closer to the knowledge of the العَلِيم.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'in reality these are chains these are shackles that keep us trapped in the دنيا so the quran puts forth a proposition it invites us to freedom from everything you see it calls us towards freedom from everything how by becoming the willing slaves of الله it creates this paradigm shift it switches our focus from these millions of means that we think are going to take us to the end of happiness it switches our focus on one central entity which is الله the ultimate end goal of happiness it doesnt stop us from acquiring things but it changes the perspective and the meaning of those things that i can enjoy everything this الم has to offer because it brings me closer to the knowledge of the العليم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 34, NULL, 'And so once we submit to him, once we channel all our distracted energies and focus it on this one central entity, we become free. By submitting to the one اللَّهُ سُبْحَانَهُ وَتَعَالَى, we become free of all other submissions, all other slaveries, resulting in a life and an afterlife that is filled with سَعَادَة, with never-ending felicity. This is why the Quran says we did not create جِنٌّ or man except for willing servitude. We did not create جِنٌّ or man except for سَعَادَة, except for happiness, which can only be achieved through a willing submission to the Creator.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'and so once we submit to him once we channel all our distracted energies and focus it on this one central entity we become free by submitting to the one الله سبحانه وتعالي we become free of all other submissions all other slaveries resulting in a life and an afterlife that is filled with سعاده with never ending felicity this is why the quran says we did not create جن or man except for willing servitude we did not create جن or man except for سعاده except for happiness which can only be achieved through a willing submission to the creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 35, NULL, 'The word عَبْد is a very powerful and comprehensive word in Arabic. The word عَبْد refers to everything that is ontologically dependent on God, whether they believe in him or not. An عَبْد is that which cannot exist on its own, which is everything, right? So everything besides اللَّه is an عَبْد of اللَّه from that vantage point, because of its dependence on him. But then the other meaning of عَبْد is those that embrace that dependence, those that accept that dependence by directing themselves to اللَّه, by worshiping and serving اللَّه. So there are these two levels of servitude in the meaning of عَبْد. One is ontological dependence, which all creation share. And then a willing dependence by those selected for devotion, which only the people of اللَّه share.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'the word عبد is a very powerful and comprehensive word in arabic the word عبد refers to everything that is ontologically dependent on god whether they believe in him or not an عبد is that which cannot exist on its own which is everything right so everything besides الله is an عبد of الله from that vantage point because of its dependence on him but then the other meaning of عبد is those that embrace that dependence those that accept that dependence by directing themselves to الله by worshiping and serving الله so there are these two levels of servitude in the meaning of عبد one is ontological dependence which all creation share and then a willing dependence by those selected for devotion which only the people of الله share', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 36, NULL, 'Now as human beings, we can only willingly submit to the one we love. Because عَبْد, the second meaning, the more profound meaning of عَبْد, means willing submission. And we can only willingly submit to the one we love. That''s how willing submission works. It cannot be forced. You cannot force anyone to love.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'now as human beings we can only willingly submit to the one we love because عبد the second meaning the more profound meaning of عبد means willing submission and we can only willingly submit to the one we love thats how willing submission works it cannot be forced you cannot force anyone to love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 37, NULL, 'You cannot put a gun to someone''s head and say be a Muslim. It doesn''t work that way. You have to submit. This is why you always fall in love. It''s a falling. I have never heard anyone say I rose in love. They always say I fell in love, right? Submission, it absolutely requires love. But in the process of falling, in that process of submission, you rise in the eyes of the beloved. Isn''t that true? In the process of falling, in the process of that submission, you elevate yourself in the eyes of the beloved. How?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'you cannot put a gun to someones head and say be a muslim it doesnt work that way you have to submit this is why you always fall in love its a falling i have never heard anyone say i rose in love they always say i fell in love right submission it absolutely requires love but in the process of falling in that process of submission you rise in the eyes of the beloved isnt that true in the process of falling in the process of that submission you elevate yourself in the eyes of the beloved how', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 38, NULL, 'By becoming the best version of yourself to make the beloved happy. Isn''t that true? You become obsessed with pleasing the beloved. And in that process, you free yourself from pleasing everybody else. Everyone else, you don''t care. All you care is the pleasure of the beloved. You don''t care about anything else. ... وَلَيْتَ الَّذِي بَيْنِي وَبَيْنَكَ عَامِرٌ، وَبَيْنِي وَبَيْنَ الْعَالَمِينَ خَرَابُ، إِذَا صَحَّ مِنْكَ الْوُدُّ، فَالْكُلُّ هَيِّنٌ، وَكُلُّ الَّذِي فَوْقَ التُّرَابِ تُرَابُ. If I get the sweetness of your love, I don''t care if my entire life becomes bitter. Right? If you are pleased with me, I don''t care if everybody becomes angry with me.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'by becoming the best version of yourself to make the beloved happy isnt that true you become obsessed with pleasing the beloved and in that process you free yourself from pleasing everybody else everyone else you dont care all you care is the pleasure of the beloved you dont care about anything else وليت الذي بيني وبينك عامر وبيني وبين العالمين خراب اذا صح منك الود فالكل هين وكل الذي فوق التراب تراب if i get the sweetness of your love i dont care if my entire life becomes bitter right if you are pleased with me i dont care if everybody becomes angry with me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 39, NULL, 'وَلَيْتَ الَّذِي بَيْنِي وَبَيْنَكَ عَامِرٌ وَبَيْنِي وَبَيْنَ الْعَالَمِينَ خَرَابُ, as long as what''s between you and I, as long as our love is flourishing, this world can become derelict, you know, I don''t care. إِذَا صَحَّ مِنْكَ الْوُدُّ فَالْكُلُّ هَيِّنٌ, if I have your love, then everything is beautiful to me. Otherwise, everything on the face of this earth is just dust to me. سُبْحَانَ اللَّهِ. I mean, that''s what love does, right? That''s the power of love.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'وليت الذي بيني وبينك عامر وبيني وبين العالمين خراب as long as whats between you and i as long as our love is flourishing this world can become derelict you know i dont care اذا صح منك الود فالكل هين if i have your love then everything is beautiful to me otherwise everything on the face of this earth is just dust to me سبحان الله i mean thats what love does right thats the power of love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 40, NULL, 'I saw this advertisement for learning Italian a few years ago. It was one of those language learning DVDs, and you know, they showed this farm boy who''s in love with this Italian celebrity, and they tell him that he''s gonna have one chance to meet him. I don''t know if you''ve ever seen this ad, but they tell him that you''re gonna have one shot at meeting this celebrity, so he wants to learn Italian to be able to speak to her, just for one moment. This was just an ad, right, of learning language, but whoever designed it, he really understood love. Because when you''re in love with someone, you will do anything. You will go to any extremes for the beloved.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'i saw this advertisement for learning italian a few years ago it was one of those language learning dvds and you know they showed this farm boy whos in love with this italian celebrity and they tell him that hes gonna have one chance to meet him i dont know if youve ever seen this ad but they tell him that youre gonna have one shot at meeting this celebrity so he wants to learn italian to be able to speak to her just for one moment this was just an ad right of learning language but whoever designed it he really understood love because when youre in love with someone you will do anything you will go to any extremes for the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 41, NULL, 'You''ll learn a whole new language just to spend one moment with the beloved. I really hope you experience true love at some point in your life, because اللَّه made love in this world. He gave us this gift of love. This worldly love, right? He made it to show us what divine love is supposed to be like. He gave us love to make us understand how to love اللَّه. It''s a حُجَّة, a proof against us. You know these stories of Laila Majnun or Romeo and Juliet. These are proofs against us. Because if this is the love of a created thing for another created thing, then what should be the love of a creation for his Creator? Right? If that''s what, you know, if that''s what you''ll do, if you''ll go to these lengths for another person, then how far should you go for your Creator?', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'youll learn a whole new language just to spend one moment with the beloved i really hope you experience true love at some point in your life because الله made love in this world he gave us this gift of love this worldly love right he made it to show us what divine love is supposed to be like he gave us love to make us understand how to love الله its a حجه a proof against us you know these stories of laila majnun or romeo and juliet these are proofs against us because if this is the love of a created thing for another created thing then what should be the love of a creation for his creator right if thats what you know if thats what youll do if youll go to these lengths for another person then how far should you go for your creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 42, NULL, 'And this is where رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ comes into the picture for us. You know, this is where his submission, his servitude for his creation comes into play. He loved اللَّه so much that اللَّه made His love a necessary condition for the acceptance of our love. Say if you love اللَّه then follow me and اللَّه will love you. Why? Because loving our Prophet will transform us into someone that اللَّه will love. Which, by the way, is a very inverted concept if you think about it, right? اللَّه should be the beloved because He''s the Creator, and our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he''s just a creation. Creation is supposed to love the Creator, not the other way around. But what we learn from the Quran is that اللَّه is in love with this man صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. What does that tell you about this man? Quran is filled with اللَّه''s expression of His love for His Prophet. These names, these beautiful titles that He uses to address His messenger. He swears by things. I mean, that is love.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'and this is where رسول الله صلي الله عليه وسلم comes into the picture for us you know this is where his submission his servitude for his creation comes into play he loved الله so much that الله made his love a necessary condition for the acceptance of our love say if you love الله then follow me and الله will love you why because loving our prophet will transform us into someone that الله will love which by the way is a very inverted concept if you think about it right الله should be the beloved because hes the creator and our prophet صلي الله عليه وسلم hes just a creation creation is supposed to love the creator not the other way around but what we learn from the quran is that الله is in love with this man صلي الله عليه وسلم what does that tell you about this man quran is filled with اللهs expression of his love for his prophet these names these beautiful titles that he uses to address his messenger he swears by things i mean that is love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 43, NULL, 'Why does اللَّه love this man so much? Because he used his free will to submit to اللَّه, and in the process he transformed himself into the best of creation. اللَّه fell in love with the qualities exhibited by this man. This is what الْإِسْلَام is. This is what الْإِسْلَام is all about. This is what ﻿شَرِيعَة is all about. We have a religion that is based in love, that is full of love. الْإِسْلَام is a love-based religion, and anyone who tells you differently has not understood this religion. وَاللَّهِ, I swear to you, the one thing I have consistently found in my years and years of study is love.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'why does الله love this man so much because he used his free will to submit to الله and in the process he transformed himself into the best of creation الله fell in love with the qualities exhibited by this man this is what الاسلام is this is what الاسلام is all about this is what شريعه is all about we have a religion that is based in love that is full of love الاسلام is a love based religion and anyone who tells you differently has not understood this religion والله i swear to you the one thing i have consistently found in my years and years of study is love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 44, NULL, 'We as creation are an expression of اللَّه''s love. Everything the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ did for us was out of pure love. If you read his سِيرَة, that is the one consistent emotion you''ll find behind every action. And he didn''t need to do this. He didn''t need to do any of it. You know, just as اللَّه, as the creator, did not need to fall in love with رَسُولُ اللَّهِ, who was his creation, رَسُولُ اللَّهِ did not need to love us. He did not need to suffer and face hardships in his life to guide us. He did not, you know, he didn''t need to lead us out of darkness into light, but he did it anyway. Why? Because of that love he had for us, that selfless love. And so it is only fair to return love with love, because you cannot love اللَّه without getting to know him and without falling in love with his beloved, which is رَسُولُ اللَّهِ.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'we as creation are an expression of اللهs love everything the prophet صلي الله عليه وسلم did for us was out of pure love if you read his سيره that is the one consistent emotion youll find behind every action and he didnt need to do this he didnt need to do any of it you know just as الله as the creator did not need to fall in love with رسول الله who was his creation رسول الله did not need to love us he did not need to suffer and face hardships in his life to guide us he did not you know he didnt need to lead us out of darkness into light but he did it anyway why because of that love he had for us that selfless love and so it is only fair to return love with love because you cannot love الله without getting to know him and without falling in love with his beloved which is رسول الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 45, NULL, 'This is why he said none of you are true believers until you love me, until you get to know me, because I am the one that اللَّه fell in love with, because loving me will naturally transform you into someone that اللَّه loves. Love is a fire, right? And fire softens and it bends steel. Fire allows the ironsmith to mold a shapeless, useless piece of steel into something beautiful, which then graces the mantle of your house, right? Burning in the fire of our messenger''s love is going to mold us into something beautiful that اللَّه would want in his presence.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'this is why he said none of you are true believers until you love me until you get to know me because i am the one that الله fell in love with because loving me will naturally transform you into someone that الله loves love is a fire right and fire softens and it bends steel fire allows the ironsmith to mold a shapeless useless piece of steel into something beautiful which then graces the mantle of your house right burning in the fire of our messengers love is going to mold us into something beautiful that الله would want in his presence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'love based religion', 'Love Based Religion', 46, NULL, 'This is why he is the greatest sign, the greatest آيَةٌ of اللهُ سُبْحَانَهُ وَتَعَالَى, a living role model, the one that اللَّه wants us to emulate. And as I said, love will naturally engender submission, and through our willing submission to the free, by submitting to the one who is free, to the high, we ourselves will become free. And we will elevate ourselves to realize our greatest potential for which we were created, which is true happiness, صَدًى, felicity, the ultimate purpose of life.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'this is why he is the greatest sign the greatest ايه of الله سبحانه وتعالي a living role model the one that الله wants us to emulate and as i said love will naturally engender submission and through our willing submission to the free by submitting to the one who is free to the high we ourselves will become free and we will elevate ourselves to realize our greatest potential for which we were created which is true happiness صدي felicity the ultimate purpose of life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 0, NULL, 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ خَالِقِ الْوُجُودِ مِنَ الْعَدَمِ وَجَاعِلِ النُّورِ مِنَ الظُّلَمِ وَمُخْرِجِ الصَّبْرِ مِنَ الْأَلَمِ وَمُمَلِّكِ التَّوْبَةِ عَلَى النَّدَمِ فَنَشْكُرُهُ عَلَى الْمَصَائِبِ كَنَشْكُرُهُ عَلَى النِّعَمِ وَنُصَلِّي عَلَى رَسُولِهِ الْأَكْرَمِ ذِي الشَّرَفِ الْأَشَمِّ وَالنُّورِ الْأَتَمِّ وَالْكِتَابِ الْمُحْكَمِ وَكَمَالِ النَّبِيِّينَ وَخَاتَمِ سَيِّدِ وَلَدِ آدَمَ الَّذِي بَشَّرَ بِهِ عِيسَى ابْنُ مَرْيَمَ وَدَعَا لَهُ بِأَسَاسِهِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ حِينَ كَانَ يَرْفَعُ قَوَاعِدَ بَيْتِ اللهِ الْمُحَرَّمِ فَصَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ وَعَلَى أَتْبَاعِهِ خَيْرِ الْأُمَمِ الَّذِينَ بَارَكَ اللهُ بِهِمْ كَافَّةَ النَّاسِ الْعَرَبِ مِنْهُمْ وَالْعَجَمِ وَصَلَّى اللهُ عَلَى أَمِيرِ الْمُؤْمِنِينَ الْأَنْزَعِ الْبَطِينِ وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ الْغَالِبِ عَلَى كُلِّ غَالِبٍ مَطْلُوبِ كُلِّ طَالِبٍ الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ وَنَعُوذُ بِاللهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا مَنْ يَهْدِهِ اللهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ وَنَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللهِ وَرَسُولُهُ أَرْسَلَهُ اللهُ تَعَالَى بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللهِ شَهِيدًا وَنَشْهَدُ أَنَّ مَوْلَانَا عَلِيَّ بْنَ أَبِي طَالِبٍ وَصِيُّهُ وَوَزِيرُهُ فَصَلَّى اللهُ عَلَيْهِمْ وَعَلَى آلِهِمْ وَسَلِّمْ عَلَيْهِمْ تَسْلِيمًا كَثِيرًا كَثِيرًا اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ عَيْنٍ لَا تَدْمَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ فَمَا بَعْدُ أَقُولُ سُبْحَانَهُ وَتَعَالَى فِي كِتَابِهِ الْكَرِيمِ بَعْدَ قَوْلِهِ أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَهَ إِلَّا اللهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', '', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ خَالِقِ الْوُجُودِ مِنَ الْعَدَمِ وَجَاعِلِ النُّورِ مِنَ الظُّلَمِ وَمُخْرِجِ الصَّبْرِ مِنَ الْأَلَمِ وَمُمَلِّكِ التَّوْبَةِ عَلَى النَّدَمِ فَنَشْكُرُهُ عَلَى الْمَصَائِبِ كَنَشْكُرُهُ عَلَى النِّعَمِ وَنُصَلِّي عَلَى رَسُولِهِ الْأَكْرَمِ ذِي الشَّرَفِ الْأَشَمِّ وَالنُّورِ الْأَتَمِّ وَالْكِتَابِ الْمُحْكَمِ وَكَمَالِ النَّبِيِّينَ وَخَاتَمِ سَيِّدِ وَلَدِ آدَمَ الَّذِي بَشَّرَ بِهِ عِيسَى ابْنُ مَرْيَمَ وَدَعَا لَهُ بِأَسَاسِهِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ حِينَ كَانَ يَرْفَعُ قَوَاعِدَ بَيْتِ اللهِ الْمُحَرَّمِ فَصَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ وَعَلَى أَتْبَاعِهِ خَيْرِ الْأُمَمِ الَّذِينَ بَارَكَ اللهُ بِهِمْ كَافَّةَ النَّاسِ الْعَرَبِ مِنْهُمْ وَالْعَجَمِ وَصَلَّى اللهُ عَلَى أَمِيرِ الْمُؤْمِنِينَ الْأَنْزَعِ الْبَطِينِ وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ الْغَالِبِ عَلَى كُلِّ غَالِبٍ مَطْلُوبِ كُلِّ طَالِبٍ الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ وَنَعُوذُ بِاللهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا مَنْ يَهْدِهِ اللهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ وَنَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللهِ وَرَسُولُهُ أَرْسَلَهُ اللهُ تَعَالَى بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللهِ شَهِيدًا وَنَشْهَدُ أَنَّ مَوْلَانَا عَلِيَّ بْنَ أَبِي طَالِبٍ وَصِيُّهُ وَوَزِيرُهُ فَصَلَّى اللهُ عَلَيْهِمْ وَعَلَى آلِهِمْ وَسَلِّمْ عَلَيْهِمْ تَسْلِيمًا كَثِيرًا كَثِيرًا اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ عَيْنٍ لَا تَدْمَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ فَمَا بَعْدُ أَقُولُ سُبْحَانَهُ وَتَعَالَى فِي كِتَابِهِ الْكَرِيمِ بَعْدَ قَوْلِهِ أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَهَ إِلَّا اللهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', NULL, NULL, NULL, 'love of the prophet need for messengers', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله خالق الوجود من العدم وجاعل النور من الظلم ومخرج الصبر من الالم ومملك التوبه علي الندم فنشكره علي المصايب كنشكره علي النعم ونصلي علي رسوله الاكرم ذي الشرف الاشم والنور الاتم والكتاب المحكم وكمال النبيين وخاتم سيد ولد ادم الذي بشر به عيسي ابن مريم ودعا له باساسه ابراهيم عليه السلام حين كان يرفع قواعد بيت الله المحرم فصلي الله عليه وعلي اله وسلم وعلي اتباعه خير الامم الذين بارك الله بهم كافه الناس العرب منهم والعجم وصلي الله علي امير المومنين الانزع البطين وقايد الغر المحجلين الغالب علي كل غالب مطلوب كل طالب الحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه ونعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا ونشهد ان مولانا علي بن ابي طالب وصيه ووزيره فصلي الله عليهم وعلي الهم وسلم عليهم تسليما كثيرا كثيرا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع فما بعد اقول سبحانه وتعالي في كتابه الكريم بعد قوله اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله خالق الوجود من العدم وجاعل النور من الظلم ومخرج الصبر من الالم ومملك التوبه علي الندم فنشكره علي المصايب كنشكره علي النعم ونصلي علي رسوله الاكرم ذي الشرف الاشم والنور الاتم والكتاب المحكم وكمال النبيين وخاتم سيد ولد ادم الذي بشر به عيسي ابن مريم ودعا له باساسه ابراهيم عليه السلام حين كان يرفع قواعد بيت الله المحرم فصلي الله عليه وعلي اله وسلم وعلي اتباعه خير الامم الذين بارك الله بهم كافه الناس العرب منهم والعجم وصلي الله علي امير المومنين الانزع البطين وقايد الغر المحجلين الغالب علي كل غالب مطلوب كل طالب الحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه ونعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا ونشهد ان مولانا علي بن ابي طالب وصيه ووزيره فصلي الله عليهم وعلي الهم وسلم عليهم تسليما كثيرا كثيرا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع فما بعد اقول سبحانه وتعالي في كتابه الكريم بعد قوله اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 1, NULL, 'Once again, السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ. In today''s session, we''re going to look at the purpose and the need for sending messengers, which are the رَسُول, right? So when I say purpose, I mean purpose from اللّٰه''s perspective and need from our perspective.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'once again السلام عليكم ورحمه الله وبركاته in todays session were going to look at the purpose and the need for sending messengers which are the رسول right so when i say purpose i mean purpose from اللهs perspective and need from our perspective', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 2, NULL, 'So the word رَسُول, it comes from the root word رَسَلَ, which means to transmit or to correspond or to delegate forward. So the idea is that this message or this book, it comes from اللّٰه, but then they''re delivered to us through an intermediary or these intermediaries that are called messengers or مُرْسَلِينَ, the plural form. So then after believing in اللّٰه, His book, His angels, the next thing we have to believe in as Muslims is the messengers.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'so the word رسول it comes from the root word رسل which means to transmit or to correspond or to delegate forward so the idea is that this message or this book it comes from الله but then theyre delivered to us through an intermediary or these intermediaries that are called messengers or مرسلين the plural form so then after believing in الله his book his angels the next thing we have to believe in as muslims is the messengers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 3, NULL, 'Now when these messengers, they deliver اللّٰه''s message to humanity, there is a response to that message. It is either met with إِيمَان or it is met with كُفْر. It is met with acceptance or rejection.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'now when these messengers they deliver اللهs message to humanity there is a response to that message it is either met with ايمان or it is met with كفر it is met with acceptance or rejection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 4, NULL, 'Now this word كُفْر, you''ll almost always see translated in books as disbelief. So a ***** is used for a non-believer or a disbeliever. And that actually is not the correct translation of كُفْر and it''s not a good translation. If you look at the root meaning of this word, right? It comes from, which means to conceal, to hide. The active participle of this root is, which actually means a farmer. A in Arabic literally means a farmer. Why? Because what a farmer does is that he covers a seed with dirt. He conceals the seed with dirt. He puts the seed into darkness.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'now this word كفر youll almost always see translated in books as disbelief so a is used for a non believer or a disbeliever and that actually is not the correct translation of كفر and its not a good translation if you look at the root meaning of this word right it comes from which means to conceal to hide the active participle of this root is which actually means a farmer a in arabic literally means a farmer why because what a farmer does is that he covers a seed with dirt he conceals the seed with dirt he puts the seed into darkness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 5, NULL, 'So the idea there is that كُفْر is placing a covering over something. That is the essence of it. So in the الإِسْلَامic sense, كُفْر is actually seen as truth concealed. And the idea there is that in reality, everyone recognizes the truth. No one can be a disbeliever. You can either accept the truth, which is إِيمَان, or you can conceal it, which is كُفْر.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'so the idea there is that كفر is placing a covering over something that is the essence of it so in the الاسلامic sense كفر is actually seen as truth concealed and the idea there is that in reality everyone recognizes the truth no one can be a disbeliever you can either accept the truth which is ايمان or you can conceal it which is كفر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 6, NULL, 'And this is why the greatest truth concealer in the الإِسْلَامic worldview is إِبْلِيس. He was actually one of the closest to God, and he knew the truth. He recognized that آدَم was superior to him, but then he concealed it, using his rationalizations of fire being better than clay.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'and this is why the greatest truth concealer in the الاسلامic worldview is ابليس he was actually one of the closest to god and he knew the truth he recognized that ادم was superior to him but then he concealed it using his rationalizations of fire being better than clay', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 7, NULL, 'Now one of the problems with modern Muslims is that they assume that everybody is a ***** if they''re not a Muslim, right? These verses in the قُرْآن', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'now one of the problems with modern muslims is that they assume that everybody is a if theyre not a muslim right these verses in the قران', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 8, NULL, 'that are talking about the كُفَّار are not talking to everybody who''s not a Muslim. They''re talking to people who are arrogant, who are puffed up, who are filled with pride, and who wouldn''t give you the time of the day. I mean, read the descriptions of the كُفَّار in the قُرْآن. They''re مُتَكَبِّر, they''re مُخْتَالٌ فَخُورٌ, they''re ظَالِمٌ, right? I mean, these are the attributes that اللّٰه gives them in the قُرْآن. Most people that he talks to in the قُرْآن are simply a نَصٌّ, right? A lot of them have simply just not heard the message, or they''ve not properly understood it, or they''re just in غَفْلَة, you know, they''re in the state of heedlessness.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'that are talking about the كفار are not talking to everybody whos not a muslim theyre talking to people who are arrogant who are puffed up who are filled with pride and who wouldnt give you the time of the day i mean read the descriptions of the كفار in the قران theyre متكبر theyre مختال فخور theyre ظالم right i mean these are the attributes that الله gives them in the قران most people that he talks to in the قران are simply a نص right a lot of them have simply just not heard the message or theyve not properly understood it or theyre just in غفله you know theyre in the state of heedlessness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 9, NULL, 'And قُرْآن refers to these people as أُنْس. And this is why اللّٰه first calls people يَا أَيُّهَا النَّاسُ before he calls them يَا أَيُّهَا الْكَافِرُونَ or يَا أَيُّهَا الَّذِينَ كَفَرُوا. He simply calls them يَا أَيُّهَا النَّاسُ. If you look at the chronology of the revelation of the قُرْآن, اللّٰه did not initially call the Arabs يَا أَيُّهَا الْكَافِرُونَ, because they weren''t كَافِرٌ. But then after seeing miracles after miracles and witnessing everything that they had witnessed, and after treating the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ the way they treated him for doing nothing other than calling them to their own success, that''s when اللّٰه said, you know, حُبُّ الْقَوْلِ. No, this is too much. You''re not going to get away with this. And that''s when the verses started turning into قُلْ يَا أَيُّهَا الْكَافِرُونَ. So that''s a very important distinction to make.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'and قران refers to these people as انس and this is why الله first calls people يا ايها الناس before he calls them يا ايها الكافرون or يا ايها الذين كفروا he simply calls them يا ايها الناس if you look at the chronology of the revelation of the قران الله did not initially call the arabs يا ايها الكافرون because they werent كافر but then after seeing miracles after miracles and witnessing everything that they had witnessed and after treating the prophet صلي الله عليه وسلم the way they treated him for doing nothing other than calling them to their own success thats when الله said you know حب القول no this is too much youre not going to get away with this and thats when the verses started turning into قل يا ايها الكافرون so thats a very important distinction to make', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 10, NULL, 'Now, what''s interesting is that there are many ways to conceal the truth. And certainly many, many Muslims are truth concealers in reality. So I can be a Muslim, and here I am doing all the right things, fulfilling my obligations, all of that. But in reality, I''m concealing the truth. How is that? The essence of truth concealing is ingratitude. The essence of truth concealing is ingratitude, not being grateful. And this is why a كَافِرٌ is also called an ingrate in the قُرْآن. اللّٰه says, you know, He gave you everything that you asked for. If you try to enumerate the blessings of اللّٰه, you will not be able to count them. Indeed, a man is extremely unjust and he is an ingrate.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'now whats interesting is that there are many ways to conceal the truth and certainly many many muslims are truth concealers in reality so i can be a muslim and here i am doing all the right things fulfilling my obligations all of that but in reality im concealing the truth how is that the essence of truth concealing is ingratitude the essence of truth concealing is ingratitude not being grateful and this is why a كافر is also called an ingrate in the قران الله says you know he gave you everything that you asked for if you try to enumerate the blessings of الله you will not be able to count them indeed a man is extremely unjust and he is an ingrate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 11, NULL, 'The word كَفَّرَ here in this verse does not mean disbeliever. It means an ingrate. The idea is that the real reason for sending messengers is good intention. In other words, اللّٰه has a good intention towards his creation, and this is why he sent messengers. If God simply created the human being and just threw away the manual and said, work it all out for yourselves, we would all spend our life in turmoil and darkness, and we would have no clue what to do or where to go. Like that Mullah Naseeruddin. I mean, I don''t know if this new generation, if you''ve ever heard that name or not, but I know people of my age, and we grew up reading these Mullah Naseeruddin stories. It''s a Middle East character that they tell stories using him. So in one of these stories, Mullah Naseeruddin was in a tavern all night, and he goes out early morning, like wee hours of the morning. He goes out and he''s wandering the city just aimlessly, right? And this policeman comes up to him and says, Mullah, what are you doing out here at this time?', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'the word كفر here in this verse does not mean disbeliever it means an ingrate the idea is that the real reason for sending messengers is good intention in other words الله has a good intention towards his creation and this is why he sent messengers if god simply created the human being and just threw away the manual and said work it all out for yourselves we would all spend our life in turmoil and darkness and we would have no clue what to do or where to go like that mullah naseeruddin i mean i dont know if this new generation if youve ever heard that name or not but i know people of my age and we grew up reading these mullah naseeruddin stories its a middle east character that they tell stories using him so in one of these stories mullah naseeruddin was in a tavern all night and he goes out early morning like wee hours of the morning he goes out and hes wandering the city just aimlessly right and this policeman comes up to him and says mullah what are you doing out here at this time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 12, NULL, 'And he says, if I knew the answer to that question, I''d be home in bed. Right? But this is the state of many, many people. They''re just literally wandering around in a drunken stupor, and they have no clue what they''re doing. And so all they do is they just try to keep themselves just constantly distracted, right? Constantly entertained. Rumi talks about the many wines that God has put on this earth to put people out of their misery, you know, these distractions. He says, Jesus was drunk in the love of God, and his donkey was high on barley. So there are many, many ways that people are trying to deal with this human condition, which is dealing with the pain of existence. And then they develop this mindset like, you know, John Lennon said, whatever gets you through the night, right? So there are many people that have this attitude. I''m just', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'and he says if i knew the answer to that question id be home in bed right but this is the state of many many people theyre just literally wandering around in a drunken stupor and they have no clue what theyre doing and so all they do is they just try to keep themselves just constantly distracted right constantly entertained rumi talks about the many wines that god has put on this earth to put people out of their misery you know these distractions he says jesus was drunk in the love of god and his donkey was high on barley so there are many many ways that people are trying to deal with this human condition which is dealing with the pain of existence and then they develop this mindset like you know john lennon said whatever gets you through the night right so there are many people that have this attitude im just', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 13, NULL, 'gonna get through this life, whatever it takes. That, from a Muslim perspective, is a type of ingratitude because the messengers have come. They have given people news. They have given people guidance, but they don''t wanna accept it. It''s like if you''re thirsty and I give you directions to the river and you say, "No, you know, I''m just gonna watch some Netflix or I''m gonna play a video game and I''m just gonna try to forget that I''m thirsty." That''s ingratitude. But then there is a whole bunch of people who are trying to distract themselves. Now, another Mullah story that kind of is another way of looking at this is that Mullah Naseeruddin was looking around one day for something. And somebody came by and he said, "Mullah, what are you looking for?" He says, "Some keys that I lost." So this man starts helping him out, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'gonna get through this life whatever it takes that from a muslim perspective is a type of ingratitude because the messengers have come they have given people news they have given people guidance but they dont wanna accept it its like if youre thirsty and i give you directions to the river and you say no you know im just gonna watch some netflix or im gonna play a video game and im just gonna try to forget that im thirsty thats ingratitude but then there is a whole bunch of people who are trying to distract themselves now another mullah story that kind of is another way of looking at this is that mullah naseeruddin was looking around one day for something and somebody came by and he said mullah what are you looking for he says some keys that i lost so this man starts helping him out right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 14, NULL, 'And after about an hour or two, he says, "Listen, where exactly do you think you lost them?" So Mullah Naseeruddin, he says, "Oh, way over there." So this man says, "Then what are you looking here for?" And he says, "The light is better over here." Right? There''s this idea that people will go where it''s easy instead of going where it''s hard. And this is also considered a type of truth concealment, to go where it''s easy instead of going where it''s hard. And this is where we begin to dilute religion to make our own lives easy. And this is why these messengers, you know, they are first and foremost, they are human beings. And this is why they present this incredible example for us through their character, by following the book of اللّٰه to the letter, setting this precedent for us that it is humanly possible to achieve what the book says.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'and after about an hour or two he says listen where exactly do you think you lost them so mullah naseeruddin he says oh way over there so this man says then what are you looking here for and he says the light is better over here right theres this idea that people will go where its easy instead of going where its hard and this is also considered a type of truth concealment to go where its easy instead of going where its hard and this is where we begin to dilute religion to make our own lives easy and this is why these messengers you know they are first and foremost they are human beings and this is why they present this incredible example for us through their character by following the book of الله to the letter setting this precedent for us that it is humanly possible to achieve what the book says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 15, NULL, 'Another interesting aspect of prophethood is this idea that we have forgotten our true purpose. We''re all distracted by the shine and the glimmer of this world. And this kind of relates to the قُرْآنic concept of غَفْلَة, which means heedlessness or forgetfulness.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'another interesting aspect of prophethood is this idea that we have forgotten our true purpose were all distracted by the shine and the glimmer of this world and this kind of relates to the قرانic concept of غفله which means heedlessness or forgetfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 16, NULL, 'That the human being by his nature is just forgetful. And if you look at this in terms of the analogy of the Vanity Fair, right? The servant is sent by the king to go to the marketplace and get something. But on the way to the marketplace there''s this Vanity Fair. You know, "Oh, I''ve got plenty of time, sun''s high, I''m going to go look at the fair." So he goes into the fair and then suddenly, entertainment, right? Suspension of purpose. And he gets preoccupied and he just loses himself in the fun, and before he knows it, the sun''s gone down. "Oh my God, the king sent me to the marketplace to get this thing, and the marketplace is closed, and I wasted my time in the Vanity Fair." So this type of metaphor is related to this human condition, which is غَفْلَة. That we become immersed in a type of heedlessness because this world by its nature is powerful. It''s powerful in the sense that we get preoccupied. So how do we remind ourselves? How do we pull ourselves out of the Vanity Fair and remind ourselves daily that this world is temporal and there''s a journey coming? From the Muslim perspective, it is the reminder itself, a ذِكْر. This is why the قُرْآن is called a ذِكْر, because it keeps reminding us of our true purpose in life.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'that the human being by his nature is just forgetful and if you look at this in terms of the analogy of the vanity fair right the servant is sent by the king to go to the marketplace and get something but on the way to the marketplace theres this vanity fair you know oh ive got plenty of time suns high im going to go look at the fair so he goes into the fair and then suddenly entertainment right suspension of purpose and he gets preoccupied and he just loses himself in the fun and before he knows it the suns gone down oh my god the king sent me to the marketplace to get this thing and the marketplace is closed and i wasted my time in the vanity fair so this type of metaphor is related to this human condition which is غفله that we become immersed in a type of heedlessness because this world by its nature is powerful its powerful in the sense that we get preoccupied so how do we remind ourselves how do we pull ourselves out of the vanity fair and remind ourselves daily that this world is temporal and theres a journey coming from the muslim perspective it is the reminder itself a ذكر this is why the قران is called a ذكر because it keeps reminding us of our true purpose in life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 17, NULL, 'Now, contrary to our forgetful natures, messengers are awakened beings. They''re awakened beings. All prophets, they share four common qualities. The first is truthfulness. They''re always truthful. They never lie. The second is trustworthiness. They''re trustworthy. If he says he''s going to be there tomorrow, he''s there. The third is conveyance, that they have this ability to articulate and convey the message. And the fourth is wakefulness, فَتْنَة. Messengers are wakeful beings.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'now contrary to our forgetful natures messengers are awakened beings theyre awakened beings all prophets they share four common qualities the first is truthfulness theyre always truthful they never lie the second is trustworthiness theyre trustworthy if he says hes going to be there tomorrow hes there the third is conveyance that they have this ability to articulate and convey the message and the fourth is wakefulness فتنه messengers are wakeful beings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 18, NULL, 'So these messengers, they are individuals who have woken up to the truth. They are like the cave dwellers of Plato''s analogy. If you''ve read the Republic, in the seventh book where Plato talks about justice, truth, and things like beauty, he gives this allegory of a group of prisoners who have been confined in a cavern since their birth. And they have no knowledge of the outside world. They are chained facing a wall and they''re not able to turn their heads around. And there''s a fire burning behind them, giving off a light and casting shadows on the wall in front of them. Now, occasionally people pass by, you know, this fire behind them, carrying these figures or animals and some other objects, and these objects, they cast a shadow on the wall, which the prisoner sees as reality. So they begin naming and classifying these illusions. And then suddenly one prisoner is freed and he walks out of the cave for the first time. And the sunlight begins to hurt his eyes and he finds this new environment completely disorienting. And then when he''s told that the things around him are actually real and the shadows in the cave, they were just reflections.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'so these messengers they are individuals who have woken up to the truth they are like the cave dwellers of platos analogy if youve read the republic in the seventh book where plato talks about justice truth and things like beauty he gives this allegory of a group of prisoners who have been confined in a cavern since their birth and they have no knowledge of the outside world they are chained facing a wall and theyre not able to turn their heads around and theres a fire burning behind them giving off a light and casting shadows on the wall in front of them now occasionally people pass by you know this fire behind them carrying these figures or animals and some other objects and these objects they cast a shadow on the wall which the prisoner sees as reality so they begin naming and classifying these illusions and then suddenly one prisoner is freed and he walks out of the cave for the first time and the sunlight begins to hurt his eyes and he finds this new environment completely disorienting and then when hes told that the things around him are actually real and the shadows in the cave they were just reflections', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 19, NULL, 'He cannot believe it because these shadows, they appeared so much more clear to them. But gradually his eyes adjust until he can actually look at the reflections in the water. He can literally see the objects directly. And finally he can see the sun, which is the ultimate source of light for everything. So this freed prisoner, he returns to the cave to share his incredible discovery with the others. But since he''s no longer used to the darkness, he now has a hard time seeing the shadows on the wall. And these other prisoners, they think that this journey has made him crazy and he''s blind and he has no idea what he''s talking about. And so they violently resist all his attempts to free them. Very interesting passage. And Plato introduces this passage as an analogy of what it is like to be a messenger. What it is like trying to educate people.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'he cannot believe it because these shadows they appeared so much more clear to them but gradually his eyes adjust until he can actually look at the reflections in the water he can literally see the objects directly and finally he can see the sun which is the ultimate source of light for everything so this freed prisoner he returns to the cave to share his incredible discovery with the others but since hes no longer used to the darkness he now has a hard time seeing the shadows on the wall and these other prisoners they think that this journey has made him crazy and hes blind and he has no idea what hes talking about and so they violently resist all his attempts to free them very interesting passage and plato introduces this passage as an analogy of what it is like to be a messenger what it is like trying to educate people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 20, NULL, 'The challenges they face when they come to wake people up out of their slumber and their distractions. They face these enormous resistance, right? So the cave in his passage is this دُنْيَا. And the world outside the cave is the آخِرَة. Everything that we see in this world, every encounter, every emotion, every event, it''s a reflection of the آخِرَة. But we believe it as being real. It''s just casting a shadow of the آخِرَة. But most people are so comfortable in their ignorance that they actually become hostile to anyone who points it out to them. But then what''s worse is that these people are not even interested in examining the proposition. And that''s what''s called acedia. The word acedia is a Latin term that''s generally translated as sloth.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'the challenges they face when they come to wake people up out of their slumber and their distractions they face these enormous resistance right so the cave in his passage is this دنيا and the world outside the cave is the اخره everything that we see in this world every encounter every emotion every event its a reflection of the اخره but we believe it as being real its just casting a shadow of the اخره but most people are so comfortable in their ignorance that they actually become hostile to anyone who points it out to them but then whats worse is that these people are not even interested in examining the proposition and thats whats called acedia the word acedia is a latin term thats generally translated as sloth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 21, NULL, 'It''s actually a Christian theology term. The seven cardinal sins, one of them is sloth. So they translate acedia as sloth, which means laziness or some resistance to work. But in the Christian theology, acedia did not originally mean laziness. You know, people that are lazy in their work. Acedia, it actually meant spiritual laziness. That people weren''t interested in finding out the truth. And that''s just arrogance. اللّٰه calls these people مُقْمَحُونَ, right? In سُورَةُ يس. And the term مُقْمَه is a term taken from camels. The Arabs say that, you know, when they would take their camel to the water, why would they take their camel to the water? To help it out, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'its actually a christian theology term the seven cardinal sins one of them is sloth so they translate acedia as sloth which means laziness or some resistance to work but in the christian theology acedia did not originally mean laziness you know people that are lazy in their work acedia it actually meant spiritual laziness that people werent interested in finding out the truth and thats just arrogance الله calls these people مقمحون right in سوره يس and the term مقمه is a term taken from camels the arabs say that you know when they would take their camel to the water why would they take their camel to the water to help it out right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 22, NULL, 'Quench its thirst. But what the camel would do is it would raise its head up and refuse to go down and drink. That''s a . The messenger takes them to the river of knowledge to quench their thirst, but they''re too arrogant to bow down and take the drink. And that is arrogance. And I''ve met so many of the قُرْآن, why should I read that book? Well, because one out of every four people actually think it''s from God. That seems like a pretty good reason just to be interested in it, right? Just to read it and see maybe there is something there. Give it a chance. But no, you know, too arrogant to even examine the proposition.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'quench its thirst but what the camel would do is it would raise its head up and refuse to go down and drink thats a the messenger takes them to the river of knowledge to quench their thirst but theyre too arrogant to bow down and take the drink and that is arrogance and ive met so many of the قران why should i read that book well because one out of every four people actually think its from god that seems like a pretty good reason just to be interested in it right just to read it and see maybe there is something there give it a chance but no you know too arrogant to even examine the proposition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 23, NULL, 'So human beings by default are in the state of غَفْلَة, which is the opposite of ذِكْر or remembrance. And this is why in the قُرْآن these two terms are always juxtaposed, right? Heedlessness, remembrance. Heedlessness, remembrance. They are focused on the outward appearances of things, but they are completely heedless about their afterlife.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'so human beings by default are in the state of غفله which is the opposite of ذكر or remembrance and this is why in the قران these two terms are always juxtaposed right heedlessness remembrance heedlessness remembrance they are focused on the outward appearances of things but they are completely heedless about their afterlife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 24, NULL, 'Now, when the prophets come, they tell the people, they give the people a formula. And that formula is . There is no god except اللّٰه. There is no entity, nothing worthy of submission or worship or love except اللّٰه. And the belief in the قُرْآن is that no messenger has ever come except that he has said لَآ إِلَهَ إِلَّا ٱللَّهُ. Indeed the religion with اللّٰه has always been الإِسْلَام, submission. So every messenger that has come from the beginning of time has come with this exact same message, لَآ إِلَهَ إِلَّا ٱللَّهُ. That is a universal message for all prophets. What will change is the second part of the شَهَادَة. For the Muslims it is now مُّحَمَّدٌۭ رَّسُولُ ٱللَّهِ. At one time it was عِيسَى رَسُولُ اللَّهِ.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'now when the prophets come they tell the people they give the people a formula and that formula is there is no god except الله there is no entity nothing worthy of submission or worship or love except الله and the belief in the قران is that no messenger has ever come except that he has said لا اله الا الله indeed the religion with الله has always been الاسلام submission so every messenger that has come from the beginning of time has come with this exact same message لا اله الا الله that is a universal message for all prophets what will change is the second part of the شهاده for the muslims it is now محمد رسول الله at one time it was عيسي رسول الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 25, NULL, 'At another time it was مُوسَى رَسُولُ اللَّهِ. Jesus is the messenger of اللّٰه. Moses is the messenger of اللّٰه. Noah is the messenger of اللّٰه. So this idea from the Muslim perspective is that all of humanity has been given these messengers to remind them about God and get them out of their state of heedlessness, from, you know, cure their state of acedia.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'at another time it was موسي رسول الله jesus is the messenger of الله moses is the messenger of الله noah is the messenger of الله so this idea from the muslim perspective is that all of humanity has been given these messengers to remind them about god and get them out of their state of heedlessness from you know cure their state of acedia', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 26, NULL, 'Now why are they doing that? To understand that, let''s examine this. Our religion, right, our Prophet''s religion is called دِينُ الْإِسْلَامِ. So let''s break this term down. The word الإِسْلَام, right, it comes from the root word سَلَامًا, which means to submit, to willingly submit to the love of God. And we talked about this yesterday, that you cannot submit until you love, right? Love is a precondition for submission. So الإِسْلَام means to submit, to willingly submit to the love of God. The word دِين in Arabic, it comes from the root ضَنٍ. And ضَنٍ in Arabic means a debt. And so our religion is called دِينُ الْإِسْلَامِ, which literally translates to the debt of willing submission.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'now why are they doing that to understand that lets examine this our religion right our prophets religion is called دين الاسلام so lets break this term down the word الاسلام right it comes from the root word سلاما which means to submit to willingly submit to the love of god and we talked about this yesterday that you cannot submit until you love right love is a precondition for submission so الاسلام means to submit to willingly submit to the love of god the word دين in arabic it comes from the root ضن and ضن in arabic means a debt and so our religion is called دين الاسلام which literally translates to the debt of willing submission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 27, NULL, 'The debt of willing submission. In other words, the idea is that we have been endowed with innumerable blessings by our Lord. And for those blessings, we owe Him a debt of gratitude through our willing submission. That''s دِينُ الْإِسْلَامِ. اللّٰه says in the قُرْآن, أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ. Do they seek anything other than the دِين of اللّٰه? وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَوَتِ وَٱلْأَرْضِ طَوْعًۭا وَكَرْهًۭا. When all creatures in the heavens and the earth, they have bowed down to Him in submission. طَوْعًا وَكَرْهًا. Willingly or unwillingly. So what اللّٰه is asking rhetorically is that, do these people seek other than repaying their debt? When in reality, everything in existence is paying back its debt to its Creator by being in a state of submission, willingly or unwillingly.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'the debt of willing submission in other words the idea is that we have been endowed with innumerable blessings by our lord and for those blessings we owe him a debt of gratitude through our willing submission thats دين الاسلام الله says in the قران افغير دين الله يبغون do they seek anything other than the دين of الله وله اسلم من في السموت والارض طوعا وكرها when all creatures in the heavens and the earth they have bowed down to him in submission طوعا وكرها willingly or unwillingly so what الله is asking rhetorically is that do these people seek other than repaying their debt when in reality everything in existence is paying back its debt to its creator by being in a state of submission willingly or unwillingly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 28, NULL, 'We see that the sun is in a state of submission. It will rise and it will set according to what has been decreed for it, right? It''s consistent. You can calculate sunrises and sunsets for the next 10 years. Now, what is the power of a human being in comparison to the sun? We''re insignificant, right? And yet this immense celestial ball of fire, many times the size of this earth, is in a state of submission to its Creator. It''s fulfilling its purpose. But the human being is not. And same goes for everything else in the universe, right? Galaxies, solar systems, sun, moon, stars, oceans, rivers, mountains. They''re all in a state of submission.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'we see that the sun is in a state of submission it will rise and it will set according to what has been decreed for it right its consistent you can calculate sunrises and sunsets for the next 10 years now what is the power of a human being in comparison to the sun were insignificant right and yet this immense celestial ball of fire many times the size of this earth is in a state of submission to its creator its fulfilling its purpose but the human being is not and same goes for everything else in the universe right galaxies solar systems sun moon stars oceans rivers mountains theyre all in a state of submission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 29, NULL, 'They''re doing what they were created to do except the human being. Now, there are areas of willing or unwilling submission that even we as human beings, we recognize, right? One of them is the call to nature, right? We have to do certain things that we cannot avoid. One of them is to eat. That is part of our nature. When we get hungry, we must eat or we die. We need to drink water when we''re thirsty. If we don''t drink, we die. We have to relieve ourselves once we have eaten or taken drink. We don''t have a choice in these matters. We have to sleep.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'theyre doing what they were created to do except the human being now there are areas of willing or unwilling submission that even we as human beings we recognize right one of them is the call to nature right we have to do certain things that we cannot avoid one of them is to eat that is part of our nature when we get hungry we must eat or we die we need to drink water when were thirsty if we dont drink we die we have to relieve ourselves once we have eaten or taken drink we dont have a choice in these matters we have to sleep', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 30, NULL, 'When sleep comes upon us, there''s only so much we can fight it. Eventually we have to submit to it or we''ll go into the state of acute psychosis. So there is this idea of submission to nature by itself. And then there is also submission to our own beings, to our physical bodies, our limitations. We can only eat so much. We can only drink so much. We can only do so much physically before we''re exhausted, right? So we have limitations in our movements because just the way our bodies are designed, the structure of our creation. So there is a type of submission of the self, given that we are temporal creatures and we''re limited by the physical aspects of our nature. So in the قُرْآن, there is this idea that everything is in a state of submission, including us. Everything in the heavens and the earth are in a state of submission, willingly or unwillingly. But then it is followed by a reminder.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'when sleep comes upon us theres only so much we can fight it eventually we have to submit to it or well go into the state of acute psychosis so there is this idea of submission to nature by itself and then there is also submission to our own beings to our physical bodies our limitations we can only eat so much we can only drink so much we can only do so much physically before were exhausted right so we have limitations in our movements because just the way our bodies are designed the structure of our creation so there is a type of submission of the self given that we are temporal creatures and were limited by the physical aspects of our nature so in the قران there is this idea that everything is in a state of submission including us everything in the heavens and the earth are in a state of submission willingly or unwillingly but then it is followed by a reminder', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 31, NULL, 'The same verse, it continues: "And to Him is their return." Now, if you look into creation, things are emerging and then they are returning into non-existence. Everything that has life that comes into existence, it returns back to non-existence. Plants, vegetables, animal kingdom, ultimately even the mineral kingdom. All of this is returning back to non-existence after it had come to existence. So what we''ve established so far is that everything in existence is paying back their debt of submission to their Creator, whether it''s willing or unwilling, and they are returning back to the Creator. But the only species that is not paying back this debt is the human being. And then there''s a difference. The difference is that the human being is asked for willing submission. The human being, the إِنْسَان, the believer, is asked for willing submission, which is out of love, not by force. Not — same word is used over there: there is no compulsion in religion, there is no force in religion. So that''s one difference compared to every other species, that اللّٰه is asking us for our willing submission.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'the same verse it continues and to him is their return now if you look into creation things are emerging and then they are returning into non existence everything that has life that comes into existence it returns back to non existence plants vegetables animal kingdom ultimately even the mineral kingdom all of this is returning back to non existence after it had come to existence so what weve established so far is that everything in existence is paying back their debt of submission to their creator whether its willing or unwilling and they are returning back to the creator but the only species that is not paying back this debt is the human being and then theres a difference the difference is that the human being is asked for willing submission the human being the انسان the believer is asked for willing submission which is out of love not by force not same word is used over there there is no compulsion in religion there is no force in religion so thats one difference compared to every other species that الله is asking us for our willing submission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 32, NULL, 'The others, the rest, they are in submission whether they like it or not, whether they want to or not. We have been given free will. Another difference is that human beings are not asked about their debts right now. Nobody is holding a gun to my head for repaying this debt that I owe اللّٰه. When will we be asked about this? On the Day of Judgment, right? Who will ask us about it? Who''s going to take us to account for this debt? In سُورَةُ الْفَاتِحَةِ, right, the fourth verse, , the owner and the king of the day.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'the others the rest they are in submission whether they like it or not whether they want to or not we have been given free will another difference is that human beings are not asked about their debts right now nobody is holding a gun to my head for repaying this debt that i owe الله when will we be asked about this on the day of judgment right who will ask us about it whos going to take us to account for this debt in سوره الفاتحه right the fourth verse the owner and the king of the day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 33, NULL, 'That''s مَلِك. مَلِك is the one who''s an owner and a king. So مَلِك, the owner and the king, يَوْمُ الدِّينِ, of the day when the debt of willing submission falls due. يَوْمُ الدِّينِ is the day when the debt of submission falls due. It''s payback time. How you transact with others is the way you will be transacted with. It''s also called يَوْمُ الْحِسَابِ, the day of accountability. رَسُولُ اللهِ says in one of the hadith, حَاسِبُوا أَنْفُسَكُمْ...', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'thats ملك ملك is the one whos an owner and a king so ملك the owner and the king يوم الدين of the day when the debt of willing submission falls due يوم الدين is the day when the debt of submission falls due its payback time how you transact with others is the way you will be transacted with its also called يوم الحساب the day of accountability رسول الله says in one of the hadith حاسبوا انفسكم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 34, NULL, 'حَاسِبُوا قَبْلَ أَنْ تُحَاسَبُوا. Take yourself to account before you are taken to account. Now, here''s something really interesting. There''s a debt of submission that we owe اللهُ سُبْحَانَهُ وَتَعَالَى for everything that He''s done for us. But then there is also a debt that اللهُ سُبْحَانَهُ وَتَعَالَى owes us.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'حاسبوا قبل ان تحاسبوا take yourself to account before you are taken to account now heres something really interesting theres a debt of submission that we owe الله سبحانه وتعالي for everything that hes done for us but then there is also a debt that الله سبحانه وتعالي owes us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 35, NULL, 'Isn''t that interesting? So just as we owe اللّٰه a debt, اللّٰه owes us a debt as well. See, when the master issues a command to his slave, right, the fulfillment of that command is a debt on that slave. Now there are only two possibilities. He either obeys the command or he disobeys the command. If I ask my daughter to bring me a glass of water, she has only two choices. She will either bring me the glass of water or she will not bring me the glass of water. In both cases, right, a return falls due on the master. If the slave is obeyed and he fulfills his obligation, his master now owes him a reward. And if he disobeyed the command, then he owes him a punishment. And that''s essentially يَوْمُ الدِّينِ. That''s the day when the debt falls due on both, on us as well as اللهُ سُبْحَانَهُ وَتَعَالَى. And this is why He says in the قُرْآن, who will indebt اللّٰه with a beautiful debt? Why is اللّٰه asking us for this debt, for this loan? So that اللّٰه multiplies its reward many, many times over and returns it back to His slaves. So in this verse, اللّٰه سُبْحَانَهُ وَتَعَالَى is asking us, His slaves, that who among you will give Me a loan? A loan of good deeds, a loan of submission, a loan of obedience.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'isnt that interesting so just as we owe الله a debt الله owes us a debt as well see when the master issues a command to his slave right the fulfillment of that command is a debt on that slave now there are only two possibilities he either obeys the command or he disobeys the command if i ask my daughter to bring me a glass of water she has only two choices she will either bring me the glass of water or she will not bring me the glass of water in both cases right a return falls due on the master if the slave is obeyed and he fulfills his obligation his master now owes him a reward and if he disobeyed the command then he owes him a punishment and thats essentially يوم الدين thats the day when the debt falls due on both on us as well as الله سبحانه وتعالي and this is why he says in the قران who will indebt الله with a beautiful debt why is الله asking us for this debt for this loan so that الله multiplies its reward many many times over and returns it back to his slaves so in this verse الله سبحانه وتعالي is asking us his slaves that who among you will give me a loan a loan of good deeds a loan of submission a loan of obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 36, NULL, 'Who will indebt Me so that I can multiply its reward many, many times over and pay you back? For He has the most generous rewards, the most noble rewards. سُبْحَانَ اللهِ. So to summarize, this wake-up call is essentially the purpose of sending messengers. To wake us up, to wake humanity up. Because we''re in a state of heedlessness. Our day of reckoning is drawing near. We''re losing sand in our hourglass every second, and we have absolutely no worries about that day. We are drowned in غَفْلَة. Let''s examine this word غَفْلَة, actually, because it''s quite an interesting word, and, you know, this might get too technical, but it''s very interesting. I find these things very interesting. Because in Arabic linguistics, right, whenever a word begins with the letter غَيْن — غَفْلَة begins with the letter غَيْن —', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'who will indebt me so that i can multiply its reward many many times over and pay you back for he has the most generous rewards the most noble rewards سبحان الله so to summarize this wake up call is essentially the purpose of sending messengers to wake us up to wake humanity up because were in a state of heedlessness our day of reckoning is drawing near were losing sand in our hourglass every second and we have absolutely no worries about that day we are drowned in غفله lets examine this word غفله actually because its quite an interesting word and you know this might get too technical but its very interesting i find these things very interesting because in arabic linguistics right whenever a word begins with the letter غين غفله begins with the letter غين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 37, NULL, 'It usually implies some sort of a covering, you know, or something being hidden or something being veiled like , right? They all have this meaning of being hidden or veiled or confined, like , right? It''s confined. So the idea is that our intellects have been veiled by the desires and temptations of this world, this . We''re unable to use our intellects. You know, a simpleton or a fool in Arabic is called مُغَفَّل because they''re very easy to trick. You know, like people that fall for these Ponzi schemes, generally they would be called مُغَفَّلٌ. So that''s what غَفْلَة means. Somebody who, مُغَفَّل is somebody whose intellect has been veiled. The other meaning of the word غَفْلَة is the inability to digest milk, which is also very interesting. It is the inability to digest milk, lactose intolerance.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'it usually implies some sort of a covering you know or something being hidden or something being veiled like right they all have this meaning of being hidden or veiled or confined like right its confined so the idea is that our intellects have been veiled by the desires and temptations of this world this were unable to use our intellects you know a simpleton or a fool in arabic is called مغفل because theyre very easy to trick you know like people that fall for these ponzi schemes generally they would be called مغفل so thats what غفله means somebody who مغفل is somebody whose intellect has been veiled the other meaning of the word غفله is the inability to digest milk which is also very interesting it is the inability to digest milk lactose intolerance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 38, NULL, 'Because milk is one of the most beneficial things in this world for mankind, right? And so to not accept that benefit, it''s غَفْلَة. And this is nothing against the lactose intolerant, right? It''s just imagery to create concepts, because Arabic words have images rather than meanings. But that''s what غَفْلَة is. And our scholars have said that all of sin, all wrongdoings are rooted in غَفْلَة. That''s the basis of it, that if you were really aware of God, you could never sin. You know, if God was present in your heart, it would be impossible for you to sin. اللّٰه says in the قُرْآن, oh my human being, what has put you in the state of delusion about your generous Lord? You know this , I need a whole session to explain. I swear, I''m not even kidding. I''m not exaggerating this.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'because milk is one of the most beneficial things in this world for mankind right and so to not accept that benefit its غفله and this is nothing against the lactose intolerant right its just imagery to create concepts because arabic words have images rather than meanings but thats what غفله is and our scholars have said that all of sin all wrongdoings are rooted in غفله thats the basis of it that if you were really aware of god you could never sin you know if god was present in your heart it would be impossible for you to sin الله says in the قران oh my human being what has put you in the state of delusion about your generous lord you know this i need a whole session to explain i swear im not even kidding im not exaggerating this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 39, NULL, ', the love in the statement, I need a whole session to explain it. From a linguistic perspective. Oh my beloved human being, what has put you in this state of delusion about your generous Lord? A scholar said, he said, اللّٰه put the answer to that question in the question itself. What has taken you away from your generous Lord? What makes you think you can do all these things and that you''re not going to be taken into account for it? What did it? Where''s the answer? Where''s the answer in the question? Your generosity. Your generosity is what has made me delusional.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'the love in the statement i need a whole session to explain it from a linguistic perspective oh my beloved human being what has put you in this state of delusion about your generous lord a scholar said he said الله put the answer to that question in the question itself what has taken you away from your generous lord what makes you think you can do all these things and that youre not going to be taken into account for it what did it wheres the answer wheres the answer in the question your generosity your generosity is what has made me delusional', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 40, NULL, 'I am heedless about sinning because you don''t react immediately with punishment. You''re extremely generous with me. I mean, that''s why I sin. The people you love the most and the people who are the most generous with you, you take them the most for granted, isn''t it? اللّٰه is so generous in his gifts to creation that we just forget that he''s our master. And that''s what غَفْلَة is. His كَرَمٌ, his generosity, his immense mercy has made us bold.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'i am heedless about sinning because you dont react immediately with punishment youre extremely generous with me i mean thats why i sin the people you love the most and the people who are the most generous with you you take them the most for granted isnt it الله is so generous in his gifts to creation that we just forget that hes our master and thats what غفله is his كرم his generosity his immense mercy has made us bold', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 41, NULL, 'You know, there''s this amazing hadith, I just suddenly remembered, in which our Prophet , he describes this conversation between اللّٰه and his angels regarding human beings. It''s such a — you know, this was one of, I remember, one of the most life-changing things for me. But according to this narration, the oceans, the earth, and the angels, they are complaining to اللّٰه, right? And it goes something like, مَا مِنْ يَوْمٍ إِلَّا وَالْبَحْرُ يَسْتَأْذِنُ رَبَّهُ أَنْ يُغْرِقَ ابْنَ آدَمَ، وَأَنَّ الْأَرْضَ تَسْتَأْذِنُ رَبَّهَا لِتَبْتَلِعَهُمْ، وَالْمَلَائِكَةُ تَسْتَأْذِنُ أَنْ تُعَاجِلَهُ وَتُهْلِكَهُ. That not a single day passes, not a single day goes by that the oceans do not ask permissions from its master. يَا اللَّهُ, give me permission to drown them. They enjoy your countless blessings and then they dare disobey you. Just say the word.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'you know theres this amazing hadith i just suddenly remembered in which our prophet he describes this conversation between الله and his angels regarding human beings its such a you know this was one of i remember one of the most life changing things for me but according to this narration the oceans the earth and the angels they are complaining to الله right and it goes something like ما من يوم الا والبحر يستاذن ربه ان يغرق ابن ادم وان الارض تستاذن ربها لتبتلعهم والملايكه تستاذن ان تعاجله وتهلكه that not a single day passes not a single day goes by that the oceans do not ask permissions from its master يا الله give me permission to drown them they enjoy your countless blessings and then they dare disobey you just say the word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 42, NULL, 'Let me teach them a lesson. Let me show them your power. Let me show them your wrath. The earth begs its master. يَا اللَّهُ, give me permission. I''ll swallow them all. They walk on your earth, eat from your blessings, live upon it and then not prostrate to you. اللّٰه, give me permission to remove them from the face of this earth. The angels: يَا اللَّهُ, give us permission. It will take us an instant. We will annihilate this whole lot of arrogant people in a moment. Who do these people think they are, standing against you?', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'let me teach them a lesson let me show them your power let me show them your wrath the earth begs its master يا الله give me permission ill swallow them all they walk on your earth eat from your blessings live upon it and then not prostrate to you الله give me permission to remove them from the face of this earth the angels يا الله give us permission it will take us an instant we will annihilate this whole lot of arrogant people in a moment who do these people think they are standing against you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 43, NULL, 'You know, scholars have explained that these oceans, the ocean, the earth, the angels, these entities, these are creations of اللّٰه who absolutely love their creator because they''re in complete submission. And they are شُهَدَاء, they are witnesses. They''re constantly witnessing their creator being disobeyed, being constantly rejected, being made fun of. How would you feel?', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'you know scholars have explained that these oceans the ocean the earth the angels these entities these are creations of الله who absolutely love their creator because theyre in complete submission and they are شهداء they are witnesses theyre constantly witnessing their creator being disobeyed being constantly rejected being made fun of how would you feel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 44, NULL, 'How would you feel if your loved ones, people that you love were constantly being humiliated and rejected? Wouldn''t that make you angry? Right? So in their anger, in their frustration based on what they''re seeing, they call upon اللّٰه for his permission to destroy us. They are creation just like us, right? And they want destroy us because of our arrogance. But our Creator, the one who we are disobeying, the one who we are humiliating, the one who we are ignoring, He says to them, وَالرَّبُّ تَعَالَى يَقُولُ: دَعَا عَبْدِي، فَأَنَا أَعْلَمُ بِهِ إِذَا أَنْشَأْتُهُمْ مِنَ الْآيَاتِ He says, He replies to them, you know, leave my slaves alone. I know everything about them since the moment I created them from this earth. If they are your creation if you created them he''s talking to the ocean he''s talking to the earth the angels if you created them do whatever you want with them drown them swallow them destroy them do whatever you want if they are your creation but if they are my creation then hand them over to me and walk away I swear by my power and my majesty if they come to me in the night I will accept them if they come to me in the day I will accept it وَإِنْ تَقَرَّبَ مِنِّي شِبْرًا تَقَرَّبْتُ مِنْهُ ذِرَاعًا، وَإِنْ تَقَرَّبَ مِنِّي ذِرَاعًا تَقَرَّبْتُ مِنْهُ بَاعًا، وَإِنْ مَشَى إِلَيَّ هَرْوَلْتُ إِلَيْهِ If he takes a step towards me, I will move an arm''s length towards him If he moves an arm''s length towards me, I will move a yard towards him If he walks towards me, I will run towards him.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'how would you feel if your loved ones people that you love were constantly being humiliated and rejected wouldnt that make you angry right so in their anger in their frustration based on what theyre seeing they call upon الله for his permission to destroy us they are creation just like us right and they want destroy us because of our arrogance but our creator the one who we are disobeying the one who we are humiliating the one who we are ignoring he says to them والرب تعالي يقول دعا عبدي فانا اعلم به اذا انشاتهم من الايات he says he replies to them you know leave my slaves alone i know everything about them since the moment i created them from this earth if they are your creation if you created them hes talking to the ocean hes talking to the earth the angels if you created them do whatever you want with them drown them swallow them destroy them do whatever you want if they are your creation but if they are my creation then hand them over to me and walk away i swear by my power and my majesty if they come to me in the night i will accept them if they come to me in the day i will accept it وان تقرب مني شبرا تقربت منه ذراعا وان تقرب مني ذراعا تقربت منه باعا وان مشي الي هرولت اليه if he takes a step towards me i will move an arms length towards him if he moves an arms length towards me i will move a yard towards him if he walks towards me i will run towards him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 45, NULL, 'If he asks, if he seeks my forgiveness, I will forgive him and when he repents on his sin, I will accept his repentance. من تقرّب إليّ لقيته من بعيد، ومن أعرض عني ناديته من قريب', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'if he asks if he seeks my forgiveness i will forgive him and when he repents on his sin i will accept his repentance من تقرب الي لقيته من بعيد ومن اعرض عني ناديته من قريب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 46, NULL, 'مَنْ تَقَرَّبَ إِلَيَّ لَقِيْتُهُ مِنْ بَعِيدٍ، وَمَنْ أَعْرَضَ عَنِّي نَادَيْتُهُ مِنْ قَرِيبٍ When He approaches me, I rush from afar to welcome Him. And when He turns away from me, I walk up to Him and I say, أَوَلَكَ كَرَبٌ كَوْنَ غَيْرِي؟ Do you have a Lord that is better than me? ‏مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ ‎ Don''t you see that when you come to me with one good deed, I reward you ten times over for that deed, and when you come to me with one sin, I respond with just what is due to remove it. And even then so many times I choose to forgive it. اللهُ أَكْبَرُ. This is our Lord. This is our loving merciful creator. اللهُ سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'من تقرب الي لقيته من بعيد ومن اعرض عني ناديته من قريب when he approaches me i rush from afar to welcome him and when he turns away from me i walk up to him and i say اولك كرب كون غيري do you have a lord that is better than me من جاء بالحسنه فله عشر امثالها ومن جاء بالسييه فلا يجزي الا مثلها وهم لا يظلمون dont you see that when you come to me with one good deed i reward you ten times over for that deed and when you come to me with one sin i respond with just what is due to remove it and even then so many times i choose to forgive it الله اكبر this is our lord this is our loving merciful creator الله سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 47, NULL, 'Who told you that our Lord is cruel? Why do we have this impression in our minds that he''s just someone waiting to burn us in hell? He created us with his own hands according to the قُرْآن. He honored us by having the angels prostrate to us. What more do we want? You think he enjoys burning us in fire? I mean, seriously. Those of you who have children, right? Your children make these ridiculous drawings, these stick figures when they''re little. And you proudly stick it up on your refrigerator. You show it to the world. You put it on display.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'who told you that our lord is cruel why do we have this impression in our minds that hes just someone waiting to burn us in hell he created us with his own hands according to the قران he honored us by having the angels prostrate to us what more do we want you think he enjoys burning us in fire i mean seriously those of you who have children right your children make these ridiculous drawings these stick figures when theyre little and you proudly stick it up on your refrigerator you show it to the world you put it on display', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 48, NULL, 'You didn''t even create your children. You just gave them birth. Mothers didn''t do any work in developing the fetus in their wombs. اللّٰه did it. And yet you would never do, never do anything to hurt your child. And اللّٰه enjoys hurting us. We are His greatest, His most beloved creation and you think He wants to cause us pain? Where do you get that information? I don''t understand. Who made الإِسْلَام so ugly for you? Who turned this incredibly loving Creator into a monster for you? I''m shocked when I talk to some of ...', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'you didnt even create your children you just gave them birth mothers didnt do any work in developing the fetus in their wombs الله did it and yet you would never do never do anything to hurt your child and الله enjoys hurting us we are his greatest his most beloved creation and you think he wants to cause us pain where do you get that information i dont understand who made الاسلام so ugly for you who turned this incredibly loving creator into a monster for you im shocked when i talk to some of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'need for messengers', 'Need For Messengers', 49, NULL, '... my beloved human being, what has put you in this delusional state about your generous Lord? You know, I really don''t know what more to say about this. It''s just ..................', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'my beloved human being what has put you in this delusional state about your generous lord you know i really dont know what more to say about this its just', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 0, NULL, 'أَرْغَبُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللهِ الرَّحْمَٰنِ الرَّحِيمِ، الْحَمْدُ لِلَّهِ الَّذِي لَا يَبْلُغُ مِدْحَتَهُ الْقَائِلُونَ، وَلَا يُحْصِي نَعْمَاءَهُ الْعَادُّونَ، وَلَا يُؤَدِّي حَقَّهُ الْمُجْتَهِدُونَ، الَّذِي لَا يُدْرِكُهُ بُعْدُ الْهِمَمِ، وَلَا يَنَالُهُ غَوْصُ الْفِطَنِ، الَّذِي لَيْسَ لِصِفَاتِهِ حَدٌّ مَحْدُودٌ، وَلَا نَعْتٌ مَوْجُودٌ، وَلَا وَقْتٌ مَعْدُودٌ، وَلَا أَجَلٌ مَمْدُودٌ، فَطَرَ الْخَلَائِقَ بِقُدْرَتِهِ، وَنَشَرَ الرِّيَاحَ بِرَحْمَتِهِ، وَوَتَّدَ بِالصُّخُورِ مَيَدَانَ أَرْضِهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى سَيِّدِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ، خَاتَمِ النَّبِيِّينَ، السَّيِّدِ الْمُمَجَّدِ، الْبَشِيرِ الْمُصَدَّقِ، النَّذِيرِ الْمُؤَيَّدِ، الْمُصْطَفَى الْأَمْجَدِ، الْمَحْمُودِ الْأَحْمَدِ، أَبِي الْقَاسِمِ مُحَمَّدٍ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى وَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَأَمِيرِ الْمُؤْمِنِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى سَيِّدِنَا الْإِمَامِ الطَّيِّبِ، صَاحِبِ الدَّعْوَةِ النَّبَوِيَّةِ، وَالصَّوْلَةِ الْحَيْدَرِيَّةِ، وَالْعِصْمَةِ الْفَاطِمِيَّةِ، وَالشَّجَاعَةِ الْحُسَيْنِيَّةِ، وَالْعُلُومِ الْبَاقِرِيَّةِ، وَالْمَعَاقِلِ الْجَعْفَرِيَّةِ، وَالْحِكْمَةِ الْإِسْمَاعِيلِيَّةِ، وَالْجُودِ الْمُحَمَّدِيَّةِ، صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِمْ وَسَلَّمَهُمْ تَسْلِيمًا كَثِيرًا كَثِيرَا، اللَّهُمَّ عَلِّمْ لَنَا إِلَى مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ، اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا، اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ عَيْنٍ لَا تَدْمَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ، اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا وَمِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ، فَأَمَّا بَعْدُ، يَقُولُ سُبْحَانَهُ وَتَعَالَى فِي كِتَابِهِ الْكَرِيمِ بَعْدَ أَقُولُ أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَٰنِ الرَّحِيمِ: رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ عَلَيَّ، وَأَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ، اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَٰهَ إِلَّا اللهُ، اللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ، آمِينَ يَا رَبَّ الْعَالَمِينَ', '', 'أَرْغَبُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللهِ الرَّحْمَٰنِ الرَّحِيمِ، الْحَمْدُ لِلَّهِ الَّذِي لَا يَبْلُغُ مِدْحَتَهُ الْقَائِلُونَ، وَلَا يُحْصِي نَعْمَاءَهُ الْعَادُّونَ، وَلَا يُؤَدِّي حَقَّهُ الْمُجْتَهِدُونَ، الَّذِي لَا يُدْرِكُهُ بُعْدُ الْهِمَمِ، وَلَا يَنَالُهُ غَوْصُ الْفِطَنِ، الَّذِي لَيْسَ لِصِفَاتِهِ حَدٌّ مَحْدُودٌ، وَلَا نَعْتٌ مَوْجُودٌ، وَلَا وَقْتٌ مَعْدُودٌ، وَلَا أَجَلٌ مَمْدُودٌ، فَطَرَ الْخَلَائِقَ بِقُدْرَتِهِ، وَنَشَرَ الرِّيَاحَ بِرَحْمَتِهِ، وَوَتَّدَ بِالصُّخُورِ مَيَدَانَ أَرْضِهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى سَيِّدِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ، خَاتَمِ النَّبِيِّينَ، السَّيِّدِ الْمُمَجَّدِ، الْبَشِيرِ الْمُصَدَّقِ، النَّذِيرِ الْمُؤَيَّدِ، الْمُصْطَفَى الْأَمْجَدِ، الْمَحْمُودِ الْأَحْمَدِ، أَبِي الْقَاسِمِ مُحَمَّدٍ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى وَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَأَمِيرِ الْمُؤْمِنِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى سَيِّدِنَا الْإِمَامِ الطَّيِّبِ، صَاحِبِ الدَّعْوَةِ النَّبَوِيَّةِ، وَالصَّوْلَةِ الْحَيْدَرِيَّةِ، وَالْعِصْمَةِ الْفَاطِمِيَّةِ، وَالشَّجَاعَةِ الْحُسَيْنِيَّةِ، وَالْعُلُومِ الْبَاقِرِيَّةِ، وَالْمَعَاقِلِ الْجَعْفَرِيَّةِ، وَالْحِكْمَةِ الْإِسْمَاعِيلِيَّةِ، وَالْجُودِ الْمُحَمَّدِيَّةِ، صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِمْ وَسَلَّمَهُمْ تَسْلِيمًا كَثِيرًا كَثِيرَا، اللَّهُمَّ عَلِّمْ لَنَا إِلَى مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ، اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا، اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ عَيْنٍ لَا تَدْمَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ، اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا وَمِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ، فَأَمَّا بَعْدُ، يَقُولُ سُبْحَانَهُ وَتَعَالَى فِي كِتَابِهِ الْكَرِيمِ بَعْدَ أَقُولُ أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَٰنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ عَلَيَّ، وَأَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ، اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَٰهَ إِلَّا اللهُ، اللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ، آمِينَ يَا رَبَّ الْعَالَمِينَ', NULL, NULL, NULL, 'love of the prophet islam as an experience', 'ارغب بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله الذي لا يبلغ مدحته القايلون ولا يحصي نعماءه العادون ولا يودي حقه المجتهدون الذي لا يدركه بعد الهمم ولا يناله غوص الفطن الذي ليس لصفاته حد محدود ولا نعت موجود ولا وقت معدود ولا اجل ممدود فطر الخلايق بقدرته ونشر الرياح برحمته ووتد بالصخور ميدان ارضه والصلاه والسلام علي سيد الانبياء والمرسلين خاتم النبيين السيد الممجد البشير المصدق النذير المويد المصطفي الامجد المحمود الاحمد ابي القاسم محمد والصلاه والسلام علي وصيه علي بن ابي طالب اشرف الوصيين وامير المومنين والصلاه والسلام علي سيدنا الامام الطيب صاحب الدعوه النبويه والصوله الحيدريه والعصمه الفاطميه والشجاعه الحسينيه والعلوم الباقريه والمعاقل الجعفريه والحكمه الاسماعيليه والجود المحمديه صلي الله عليه وعلي الهم وسلمهم تسليما كثيرا كثيرا اللهم علم لنا الي ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع اللهم انا نعوذ بك من دعوه لا يستجاب لها ومن منكرات الاخلاق والاعمال والاهواء فاما بعد يقول سبحانه وتعالي في كتابه الكريم بعد اقول اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم اني اعوذ بك ان اضل او اضل او ازل او ازل او اظلم او اظلم علي واجهل او يجهل علي اللهم ثبتنا عند الموت بلا اله الا الله اللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين', 'ارغب بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله الذي لا يبلغ مدحته القايلون ولا يحصي نعماءه العادون ولا يودي حقه المجتهدون الذي لا يدركه بعد الهمم ولا يناله غوص الفطن الذي ليس لصفاته حد محدود ولا نعت موجود ولا وقت معدود ولا اجل ممدود فطر الخلايق بقدرته ونشر الرياح برحمته ووتد بالصخور ميدان ارضه والصلاه والسلام علي سيد الانبياء والمرسلين خاتم النبيين السيد الممجد البشير المصدق النذير المويد المصطفي الامجد المحمود الاحمد ابي القاسم محمد والصلاه والسلام علي وصيه علي بن ابي طالب اشرف الوصيين وامير المومنين والصلاه والسلام علي سيدنا الامام الطيب صاحب الدعوه النبويه والصوله الحيدريه والعصمه الفاطميه والشجاعه الحسينيه والعلوم الباقريه والمعاقل الجعفريه والحكمه الاسماعيليه والجود المحمديه صلي الله عليه وعلي الهم وسلمهم تسليما كثيرا كثيرا اللهم علم لنا الي ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع اللهم انا نعوذ بك من دعوه لا يستجاب لها ومن منكرات الاخلاق والاعمال والاهواء فاما بعد يقول سبحانه وتعالي في كتابه الكريم بعد اقول اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم اني اعوذ بك ان اضل او اضل او ازل او ازل او اظلم او اظلم علي واجهل او يجهل علي اللهم ثبتنا عند الموت بلا اله الا الله اللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 1, NULL, 'السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ. There''s a حَدِيث which is called حَدِيثُ جِبْرِيلَ. It''s a very famous حَدِيث, where جِبْرِيل comes to the Prophet in the form of a man. And he asks him four questions. What is الْإِسْلَام? What is إِيمَان? What is إِحْسَان? And then he asks him about the signs of the end of time. So when, I mean, you can look it up and, you know, you can get all the information about it.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'السلام عليكم ورحمه الله وبركاته theres a حديث which is called حديث جبريل its a very famous حديث where جبريل comes to the prophet in the form of a man and he asks him four questions what is الاسلام what is ايمان what is احسان and then he asks him about the signs of the end of time so when i mean you can look it up and you know you can get all the information about it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 2, NULL, 'I''m just going to talk about الْإِسْلَام, that when he was asked about الْإِسْلَام, the Prophet replied, الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ. He said, الْإِسْلَام is to bear witness that there is no God but اللَّه. And Muhammad صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ says, Messenger. وَتُقِيمَ الصَّلَاةَ, to establish prayer. وَتُقْتِيَ الزَّكَاةَ, to give alms. وَتَصُومَ رَمَضَانَ, to fast the 30 days in رَمَضَان. وَتُحَجَّ الْبَيْتُ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا. And to perform the pilgrimage to the House of God if you have the means.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'im just going to talk about الاسلام that when he was asked about الاسلام the prophet replied الاسلام ان تشهد ان لا اله الا الله وان محمدا رسول الله he said الاسلام is to bear witness that there is no god but الله and muhammad صلي الله عليه وسلم says messenger وتقيم الصلاه to establish prayer وتقتي الزكاه to give alms وتصوم رمضان to fast the 30 days in رمضان وتحج البيت ان استطعت اليه سبيلا and to perform the pilgrimage to the house of god if you have the means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 3, NULL, 'Now what''s interesting about this حَدِيث is that rather than giving a definition of الْإِسْلَام, which I would have expected, رَسُولُ اللهِ عَلَيْهِ السَّلَامُ, he described it as a set of practices. In other words, what he''s saying is that الْإِسْلَام is work, right? But what we forget is that this is not how الْإِسْلَام started. الْإِسْلَام as a human phenomenon, it began with an incredible experience for the Prophet and then finally culminated in a set of practices. For most of us, الْإِسْلَام begins as a practice. It never begins for us as an experience, but that''s not how it began for the Prophet.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'now whats interesting about this حديث is that rather than giving a definition of الاسلام which i would have expected رسول الله عليه السلام he described it as a set of practices in other words what hes saying is that الاسلام is work right but what we forget is that this is not how الاسلام started الاسلام as a human phenomenon it began with an incredible experience for the prophet and then finally culminated in a set of practices for most of us الاسلام begins as a practice it never begins for us as an experience but thats not how it began for the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 4, NULL, 'How did it begin for him? It began with a direct experience of the noumenal realm, right? So you have the phenomenal realm, which is this world. This world of appearances or what we call the seen world, عَالَمُ الشَّهَادَةِ. And then there is the noumenal realm, which is the unseen world, right? عَالَمُ الْغَيْبِ, which constitutes the metaphysical realities like God, angels, heaven, hell, all those things. And the Prophet experienced both in his lifetime. He had the phenomenal experience in the cave of حِرَاء. And then he also had the noumenal experience with his ascension, right, the مِعْرَاج.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'how did it begin for him it began with a direct experience of the noumenal realm right so you have the phenomenal realm which is this world this world of appearances or what we call the seen world عالم الشهاده and then there is the noumenal realm which is the unseen world right عالم الغيب which constitutes the metaphysical realities like god angels heaven hell all those things and the prophet experienced both in his lifetime he had the phenomenal experience in the cave of حراء and then he also had the noumenal experience with his ascension right the معراج', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 5, NULL, 'So in today''s session, what I wanted to do is I want us to connect with both those experiences. Sort of step in his shoes and try to understand what it must have felt like. Because his experiences, particularly these two experiences, they set a precedent for us in terms of what الْإِسْلَام is meant to feel like. We all know what it is in terms of practice, but it''s important for us to understand what the feeling or the experience of الْإِسْلَام is as it was for the Prophet. So that once we connect with that, then we will talk about how we can use his experience for our own benefit.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so in todays session what i wanted to do is i want us to connect with both those experiences sort of step in his shoes and try to understand what it must have felt like because his experiences particularly these two experiences they set a precedent for us in terms of what الاسلام is meant to feel like we all know what it is in terms of practice but its important for us to understand what the feeling or the experience of الاسلام is as it was for the prophet so that once we connect with that then we will talk about how we can use his experience for our own benefit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 6, NULL, 'So the year is 620 AD. Our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he''s 40 years old. Socially, the culture that he lives in is very troublesome for him. He''s bothered by the behavior of these جَاهِلِيّ Arabs, especially idol worship, because he had a natural disinclination towards superstitions or any kind of animism for that matter. So he''s troubled, right? And when you''re troubled, what do you do?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so the year is 620 ad our prophet صلي الله عليه وسلم hes 40 years old socially the culture that he lives in is very troublesome for him hes bothered by the behavior of these جاهلي arabs especially idol worship because he had a natural disinclination towards superstitions or any kind of animism for that matter so hes troubled right and when youre troubled what do you do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 7, NULL, 'You retreat. So he wanted to get away from it all. And in order to do that, he made it a habit to go to this cave within a mountain called جَبَلُ النُّورِ, which literally means the mountain of light. And the cave itself was called حِرَاء, which means darkness. And I find that interesting, right? A cave named darkness within a mountain named the mountain of light. Anyway, so he gets into this regular practice of contemplation and reflection, which today we call meditation, or تَحَنُّث, which is emptying the mind. The word تَحَنُّس comes from حُبُّ النَّبِيِّ, which in Arabic means شِرْك, attributing partners with God. In سُورَةُ الْوَاقِعَةِ, اللَّه says, these people, they insist on committing great شِرْك. So, حُبُّ النَّبِيِّ is شِرْك, attributing partners. In Arabic morphology, there''s something called بَابَ تَفَاؤُل, where you add a طه before the word and the meaning morphs into avoidance of.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'you retreat so he wanted to get away from it all and in order to do that he made it a habit to go to this cave within a mountain called جبل النور which literally means the mountain of light and the cave itself was called حراء which means darkness and i find that interesting right a cave named darkness within a mountain named the mountain of light anyway so he gets into this regular practice of contemplation and reflection which today we call meditation or تحنث which is emptying the mind the word تحنس comes from حب النبي which in arabic means شرك attributing partners with god in سوره الواقعه الله says these people they insist on committing great شرك so حب النبي is شرك attributing partners in arabic morphology theres something called باب تفاول where you add a طه before the word and the meaning morphs into avoidance of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 8, NULL, 'So حُبُّ النَّبِيِّ, as it''s used in the verse, حُبُّ النَّبِيِّ means شِرْك. تَحَنُّث means the avoidance of شِرْك. جَنَّبْ means side or nearness. تَجَنُّب means to avoid somebody''s nearness. So there are a lot of words like حَجُد, which means sleep. تَهَجُّد means to avoid sleep. Anyway, these are all these different words that follow the same pattern and morphology. So one day, this 40-year-old man, he''s busy meditating in this cave at the top of this mountain. And just like any other day, he gets into this deep contemplative state, and his desire is this attempt to empty out forms. That''s what he''s trying to do. He''s trying to disconnect himself from this physical world.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so حب النبي as its used in the verse حب النبي means شرك تحنث means the avoidance of شرك جنب means side or nearness تجنب means to avoid somebodys nearness so there are a lot of words like حجد which means sleep تهجد means to avoid sleep anyway these are all these different words that follow the same pattern and morphology so one day this 40 year old man hes busy meditating in this cave at the top of this mountain and just like any other day he gets into this deep contemplative state and his desire is this attempt to empty out forms thats what hes trying to do hes trying to disconnect himself from this physical world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 9, NULL, 'He wants to free himself from all of these forms or attachments of this world. Now, what''s the greatest شِرْك of all? What is the greatest شِرْك of all? The greatest, it''s the worship of the self. Idolatry has nothing on self-olatry. I just made that word up. But really, idolatry has nothing on self-worship or egocentricity. According to our tradition, worship of the self, which pretty much everyone is engaged in today, it''s the most destructive thing there is for the soul. اللَّه talks about these people who worship their desires and their passions. Do you not see the one who took his own desires, his own passions as his God? Do you not see the one that when his desire commands, he just simply submits? Because that''s worship.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'he wants to free himself from all of these forms or attachments of this world now whats the greatest شرك of all what is the greatest شرك of all the greatest its the worship of the self idolatry has nothing on self olatry i just made that word up but really idolatry has nothing on self worship or egocentricity according to our tradition worship of the self which pretty much everyone is engaged in today its the most destructive thing there is for the soul الله talks about these people who worship their desires and their passions do you not see the one who took his own desires his own passions as his god do you not see the one that when his desire commands he just simply submits because thats worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 10, NULL, 'So رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ is in this cave in deep reflection, working on himself. He''s trying to empty his heart out of all these attachments. And even in Chinese, you have this thing, empty your cup so that it can be filled with something new. Because the soul has to be emptied of all forms before it can gain knowledge of the one who has no form. Because forms, they impinge on that understanding. And as he''s doing that, suddenly he sees the horizons filled with the presence of an angelic being. And this being says to him, Muhammad, I am جِبْرِيل and you have been chosen as the messenger of اللَّه. So he raises his head to see who''s speaking to him, and he sees جِبْرِيل filling up the horizons. Now think about that for a second. If all of us stepped out right now, and we saw an angelic presence from one horizon to the other and as far up in the sky as we could see, how would that affect us? How would that affect us psychologically?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so رسول الله صلي الله عليه وسلم is in this cave in deep reflection working on himself hes trying to empty his heart out of all these attachments and even in chinese you have this thing empty your cup so that it can be filled with something new because the soul has to be emptied of all forms before it can gain knowledge of the one who has no form because forms they impinge on that understanding and as hes doing that suddenly he sees the horizons filled with the presence of an angelic being and this being says to him muhammad i am جبريل and you have been chosen as the messenger of الله so he raises his head to see whos speaking to him and he sees جبريل filling up the horizons now think about that for a second if all of us stepped out right now and we saw an angelic presence from one horizon to the other and as far up in the sky as we could see how would that affect us how would that affect us psychologically', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 11, NULL, 'How would that affect us physically? What would you and I experience in that moment? Would we be terrified? Would we be horrified? Would we be shocked? What would we experience? See, the interesting thing about experience is that it is not a logical proposition. You cannot prove or disprove experience. You can discuss it, you can talk about it, you can try to interpret it, but you cannot say whether it''s true or false. Because experience is always real for the one experiencing it. The challenge then is to determine whether or not that experience has an objective reality or it has a subjective reality. In other words, is that experience really a true experience, or is it something that is just happening to this individual as a type of psychosis?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'how would that affect us physically what would you and i experience in that moment would we be terrified would we be horrified would we be shocked what would we experience see the interesting thing about experience is that it is not a logical proposition you cannot prove or disprove experience you can discuss it you can talk about it you can try to interpret it but you cannot say whether its true or false because experience is always real for the one experiencing it the challenge then is to determine whether or not that experience has an objective reality or it has a subjective reality in other words is that experience really a true experience or is it something that is just happening to this individual as a type of psychosis', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 12, NULL, 'Because we do have a lot of people in psychic wards today speaking to God directly, right? They will tell you that they speak to God and they can hear God speaking to them. These people are not lying, because even though they are in a delusional state, they actually believe what they''re experiencing. Their delusions are very real to them. So the Prophet naturally is filled with all those human emotions: fear, shock, horror. So he turns his face away from him, but no matter where he turns, he sees the angel in the exact same form. And then جِبْرِيل says to him, "Recite." And he replies, "What should I recite? I don''t know what to recite." And at that point, جِبْرِيل wraps his wings around him and he squeezes him three times.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'because we do have a lot of people in psychic wards today speaking to god directly right they will tell you that they speak to god and they can hear god speaking to them these people are not lying because even though they are in a delusional state they actually believe what theyre experiencing their delusions are very real to them so the prophet naturally is filled with all those human emotions fear shock horror so he turns his face away from him but no matter where he turns he sees the angel in the exact same form and then جبريل says to him recite and he replies what should i recite i dont know what to recite and at that point جبريل wraps his wings around him and he squeezes him three times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 13, NULL, 'And according to the Prophet, this squeeze was so hard that he felt stifled to the point where he thought he would die. And scholars have commented that this squeezing was a physical manifestation of a spiritual reality, which was removing any and all remnants of this world from his soul. He was being emptied out in order to later be filled with three divine vessels: الْإِسْلَام, إِيمَان, and إِحْسَان. And so there had to be a complete emptying out before the filling could take place. And this is what he was seeking. That''s what he was trying to do to begin with, with that meditation in . And also this is what the companions used to say about the Prophet, that he would literally empty us out of ignorance, of جَاهِلِيَّة, and then fill us up with الْإِسْلَام. Right? And this is why لَآ إِلَهَ إِلَّا ٱللَّهُ starts with a negation. There is no God. It starts with a negation for emptying out, breaking false pretenses, breaking false understandings.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'and according to the prophet this squeeze was so hard that he felt stifled to the point where he thought he would die and scholars have commented that this squeezing was a physical manifestation of a spiritual reality which was removing any and all remnants of this world from his soul he was being emptied out in order to later be filled with three divine vessels الاسلام ايمان and احسان and so there had to be a complete emptying out before the filling could take place and this is what he was seeking thats what he was trying to do to begin with with that meditation in and also this is what the companions used to say about the prophet that he would literally empty us out of ignorance of جاهليه and then fill us up with الاسلام right and this is why لا اله الا الله starts with a negation there is no god it starts with a negation for emptying out breaking false pretenses breaking false understandings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 14, NULL, 'Then it says إِلَّا اللَّه, which is an affirmation. So every الْإِسْلَام always began with, every religion began with an emptying out. And so even for رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, الْإِسْلَام was actually a complete emptying before it was a filling. And this in Arabic is called تَخْلِيَة. The Arabs say, that the emptying out must precede the ornaments. In other words, you have to be stripped off of what is ugly before you can be ornamented with what is beautiful. So that squeeze was meant to empty his soul out. And then he says, then he starts filling him with وَحْيٌ. ‏خَلَقَ ٱلْإِنسَنَ مِنْ عَلَقٍ ‎. ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ. ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ. ‏عَلَّمَ ٱلْإِنسَنَ مَا لَمْ يَعْلَمْ ‎.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'then it says الا الله which is an affirmation so every الاسلام always began with every religion began with an emptying out and so even for رسول الله صلي الله عليه وسلم الاسلام was actually a complete emptying before it was a filling and this in arabic is called تخليه the arabs say that the emptying out must precede the ornaments in other words you have to be stripped off of what is ugly before you can be ornamented with what is beautiful so that squeeze was meant to empty his soul out and then he says then he starts filling him with وحي خلق الانسن من علق اقرا وربك الاكرم الذي علم بالقلم علم الانسن ما لم يعلم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 15, NULL, 'Recite. Recite in the name of your Lord who created you. Created man from a clinging substance. ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ. Recite, for your Lord is the most generous. ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ. Who taught by the means of the pen. Who taught man that which he did not know. So now the Prophet moves into a new realm, and a troublesome realm, I think. Because for every human being, for every intellectual human being at least, one of the fundamental crises of religion becomes, is my object of devotion indeed a transcendent reality? Or is it some kind of a distortion of my human consciousness?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'recite recite in the name of your lord who created you created man from a clinging substance اقرا وربك الاكرم recite for your lord is the most generous الذي علم بالقلم who taught by the means of the pen who taught man that which he did not know so now the prophet moves into a new realm and a troublesome realm i think because for every human being for every intellectual human being at least one of the fundamental crises of religion becomes is my object of devotion indeed a transcendent reality or is it some kind of a distortion of my human consciousness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 16, NULL, 'In other words, is this experience really true? Or am I having some kind of a psychological breakdown? Now, how do you differentiate between a true divine experience and a demonic experience? And this is key, so pay attention to this, because this is the key that differentiates between a demonic experience and a true spiritual experience. A demonic experience is always accompanied with an expansion of the self. A demonic experience always begins with, you know, it''s a very exciting, very joyful experience, very pleasurable experience, but then it always inevitably results in pain and despair in the end. And you can think of anything that الْإِسْلَام deems حَرَم, right? Drugs, alcohol, sexual deviancy, smoking, any kind of overindulgence. They all begin with a rush, an excitement, ecstasy, can''t stop feeling high, euphoria, but it ends, always ends', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'in other words is this experience really true or am i having some kind of a psychological breakdown now how do you differentiate between a true divine experience and a demonic experience and this is key so pay attention to this because this is the key that differentiates between a demonic experience and a true spiritual experience a demonic experience is always accompanied with an expansion of the self a demonic experience always begins with you know its a very exciting very joyful experience very pleasurable experience but then it always inevitably results in pain and despair in the end and you can think of anything that الاسلام deems حرم right drugs alcohol sexual deviancy smoking any kind of overindulgence they all begin with a rush an excitement ecstasy cant stop feeling high euphoria but it ends always ends', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 17, NULL, 'in suffering. I mean, and this is not just, you know, like major things like alcohol, that those end in like whatever, hangovers and DUIs and liver diseases. Drugs end in addictions, in ruining families. Smoking ends in cancer, heart diseases. But when the person actually starts smoking, when he starts drinking or whatever, right, it''s the coolest thing ever. It''s like awesome. That psychological high is intense, but it never ends well. And it doesn''t have to be this drastic, like food, gluttony, right? If there is something delicious in front of me and I pig out, right? If I stuff my face with it to the point where I can''t breathe, how do I end up feeling? While I''m eating it, while I''m tasting it, it''s like really pleasurable, I''m enjoying everything of it. But when I get that sick, full feeling, how does that feel, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'in suffering i mean and this is not just you know like major things like alcohol that those end in like whatever hangovers and duis and liver diseases drugs end in addictions in ruining families smoking ends in cancer heart diseases but when the person actually starts smoking when he starts drinking or whatever right its the coolest thing ever its like awesome that psychological high is intense but it never ends well and it doesnt have to be this drastic like food gluttony right if there is something delicious in front of me and i pig out right if i stuff my face with it to the point where i cant breathe how do i end up feeling while im eating it while im tasting it its like really pleasurable im enjoying everything of it but when i get that sick full feeling how does that feel right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 18, NULL, 'So every kind of demonic experience, any kind of extreme is always gonna end up in pain. This is why رَسُولُ اللهِ said that, the middle path is the best for everything. So the point is that every demonic experience begins with joy and a sense of elation, right? This expansion, but then it ends in constriction and misery. Now, on the contrary, a true spiritual experience is exactly the opposite. The initial experience is always incredible constriction, extreme fear, dreadful feeling, you know, the pressure of hard work, but it always ends in a sense of joy and expansion. And this is just a principle. It''s not a — like, it''s not limited to Muslims. Take any man who has ever achieved any greatness in this world, like Mahatma Gandhi, Mother Teresa, you know, Martin Luther King, famous painters, poets, anyone. Their initial experience is a struggle, suffering, hard work, but their final experience is just this incredible expansion, fame, glory. People celebrate them years after they die.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so every kind of demonic experience any kind of extreme is always gonna end up in pain this is why رسول الله said that the middle path is the best for everything so the point is that every demonic experience begins with joy and a sense of elation right this expansion but then it ends in constriction and misery now on the contrary a true spiritual experience is exactly the opposite the initial experience is always incredible constriction extreme fear dreadful feeling you know the pressure of hard work but it always ends in a sense of joy and expansion and this is just a principle its not a like its not limited to muslims take any man who has ever achieved any greatness in this world like mahatma gandhi mother teresa you know martin luther king famous painters poets anyone their initial experience is a struggle suffering hard work but their final experience is just this incredible expansion fame glory people celebrate them years after they die', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 19, NULL, 'You know, they''re gone. Now, in this experience of our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ and the experience of all Prophets before him, we find the exact same reaction to revelation. The قُرْآن tells us that the first divine words for مُوسَى عَلَيْهِ السَّلَامُ were what? Don''t be afraid. Because his first experience was filled with fear when he saw God on the mountain. إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ also had the same experience, right? حَضْرَتْ مَرْيَم, the mother of عِشْق, terrified when she saw the angel. I seek refuge of the most compassionate from you. She got scared out of her mind. And so this is something we find consistent in the قُرْآن and also what the Jews and the Christians believe in their traditions, that every religious experience is always overwhelming, it incapacitates the self. So when رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ received this first revelation of اِقْرَأْ, it was a very painful process for him. And this is what I want you to connect with.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'you know theyre gone now in this experience of our prophet صلي الله عليه وسلم and the experience of all prophets before him we find the exact same reaction to revelation the قران tells us that the first divine words for موسي عليه السلام were what dont be afraid because his first experience was filled with fear when he saw god on the mountain ابراهيم عليه السلام also had the same experience right حضرت مريم the mother of عشق terrified when she saw the angel i seek refuge of the most compassionate from you she got scared out of her mind and so this is something we find consistent in the قران and also what the jews and the christians believe in their traditions that every religious experience is always overwhelming it incapacitates the self so when رسول الله صلي الله عليه وسلم received this first revelation of اقرا it was a very painful process for him and this is what i want you to connect with', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 20, NULL, 'That this is not, you know, someone who just enjoyed the whole process of prophethood. He went through a lot of pain because جِبْرِيل did not feed him the words that he repeated to the قُرَيْش later on through this rote memorization. What was being delivered to him were the meanings. And these meanings were being directly breathed into him. The Arabic word for breath and for spirit, it''s the same, it''s رُوح. They come from the same root. So when these meanings, this وَحْيٌ was being just blown into him, breathed into him, it was a very painful experience. Imagine, just imagine being given mouth to mouth by a giant. What do you imagine that would feel like? Probably like every cell of your body is being taken over by this immense pressure of that air, right? And then you have this feeling of complete helplessness while that''s happening.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'that this is not you know someone who just enjoyed the whole process of prophethood he went through a lot of pain because جبريل did not feed him the words that he repeated to the قريش later on through this rote memorization what was being delivered to him were the meanings and these meanings were being directly breathed into him the arabic word for breath and for spirit its the same its روح they come from the same root so when these meanings this وحي was being just blown into him breathed into him it was a very painful experience imagine just imagine being given mouth to mouth by a giant what do you imagine that would feel like probably like every cell of your body is being taken over by this immense pressure of that air right and then you have this feeling of complete helplessness while thats happening', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 21, NULL, 'So even as that breath is giving you life, it would feel like it''s squashing the life out of you, suffocating you under its enormous weight. That pressure, right? This is why, according to the narrations, in the early period of الْإِسْلَام, our Prophet would start convulsing when he received revelation. Because it was a very, very painful experience for him. And the disbelievers would use that as an excuse to say, look, he''s possessed by a جِنٌّ, look, he''s crazy. But in his own words, in the Prophet''s words, he describes the process. He says, it felt as though the message was being engraved on my heart. Engraved, that''s the word he used. Have you seen anyone ever do an engraving? Imagine that agonizing pain of a sharp blade carving deep inside your heart as you lie helplessly beneath it. You''re completely conscious of the pain, but you are unable to struggle against it.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so even as that breath is giving you life it would feel like its squashing the life out of you suffocating you under its enormous weight that pressure right this is why according to the narrations in the early period of الاسلام our prophet would start convulsing when he received revelation because it was a very very painful experience for him and the disbelievers would use that as an excuse to say look hes possessed by a جن look hes crazy but in his own words in the prophets words he describes the process he says it felt as though the message was being engraved on my heart engraved thats the word he used have you seen anyone ever do an engraving imagine that agonizing pain of a sharp blade carving deep inside your heart as you lie helplessly beneath it youre completely conscious of the pain but you are unable to struggle against it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 22, NULL, 'Just imagine that, that is how difficult this process of وَحْيٌ was for him initially. But later on, it got a lot easier for him to the point where people would, they wouldn''t even know when revelation came upon him. So after the Prophet had this very first experience of revelation, this very first difficult experience of revelation, he went into a state of extreme shock. Lesley Hazleton, an incredible author, and if you''ve ever read her book, The First Muslim, she beautifully portrays his emotions after this first encounter with جِبْرِيل. She writes, he did not come floating off the mountain as though he was walking on air. He did not run down shouting Hallelujah and Bless the Lord, I am your prophet. He did not radiate light and joy. There were no choir of angels, no music from the heavens, no elation, no ecstasy, no golden aura surrounding him. He did nothing that might seem as the reaction of a man who just crossed the border between this world and the spiritual world. That is such a beautiful description. See, if he had done that, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'just imagine that that is how difficult this process of وحي was for him initially but later on it got a lot easier for him to the point where people would they wouldnt even know when revelation came upon him so after the prophet had this very first experience of revelation this very first difficult experience of revelation he went into a state of extreme shock lesley hazleton an incredible author and if youve ever read her book the first muslim she beautifully portrays his emotions after this first encounter with جبريل she writes he did not come floating off the mountain as though he was walking on air he did not run down shouting hallelujah and bless the lord i am your prophet he did not radiate light and joy there were no choir of angels no music from the heavens no elation no ecstasy no golden aura surrounding him he did nothing that might seem as the reaction of a man who just crossed the border between this world and the spiritual world that is such a beautiful description see if he had done that right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 23, NULL, 'If he came down the mountain feeling top of the world, shouting hallelujah, that would have indicated signs of psychosis. Because this is how a crazy person speaking to God behaves in the psych ward. So, he had no signs or symptoms of a demonic experience. On the contrary, she writes, he was convinced that what he had encountered could not be real. See, such a human reaction. He was convinced that what he had encountered could not be real. He thought it was a hallucination or a trick of the senses. He thought he had been possessed by an evil جِنٌّ. So the man who fled down the mountain of Hera trembled, not with joy, but with a stark primordial fear. He was overwhelmed, not with conviction, he was overwhelmed with doubt. Now, if you think about this, right, this is exactly our initial encounter with الْإِسْلَام. A feeling of this constriction, that feeling of doubt.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'if he came down the mountain feeling top of the world shouting hallelujah that would have indicated signs of psychosis because this is how a crazy person speaking to god behaves in the psych ward so he had no signs or symptoms of a demonic experience on the contrary she writes he was convinced that what he had encountered could not be real see such a human reaction he was convinced that what he had encountered could not be real he thought it was a hallucination or a trick of the senses he thought he had been possessed by an evil جن so the man who fled down the mountain of hera trembled not with joy but with a stark primordial fear he was overwhelmed not with conviction he was overwhelmed with doubt now if you think about this right this is exactly our initial encounter with الاسلام a feeling of this constriction that feeling of doubt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 24, NULL, 'Is this real? Is there really a God? Is there an afterlife? Is there heaven? Hell? And then it''s, you know, followed by the burden of practice. You know, when you take أَحَادِيثُ شَرِيفٌ, right? Look at that, that pressure you feel. That''s the same experience as he had at Hera, right? It''s that burden of responsibility. Am I going to be able to do this? What if I''m not able to do this?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'is this real is there really a god is there an afterlife is there heaven hell and then its you know followed by the burden of practice you know when you take احاديث شريف right look at that that pressure you feel thats the same experience as he had at hera right its that burden of responsibility am i going to be able to do this what if im not able to do this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 25, NULL, 'That''s expected with any spiritual experience. That''s the point I''m trying to make, that it always begins with a constriction. So scholars say that what happened up there on the mountain, just the sheer humanness of رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَs reaction, that is the strongest argument for its historical reality. Whether you believe that the words he heard came from inside himself or from outside, it is clear that he experienced them. And he experienced them with the force that shattered his sense of being. You know, normally when people go into shock, they lose their ability to think. We know this, right? But with the Messenger عَلَيْهِ السَّلَامُ, it was the opposite. He was able to maintain his focus and presence of mind. How do we know that? The proof of that consciousness is in what he said to his wife, حَضْرَتْ خَدِيجَة, سَلَامُ اللهِ عَلَيْهَا, when he returned home.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'thats expected with any spiritual experience thats the point im trying to make that it always begins with a constriction so scholars say that what happened up there on the mountain just the sheer humanness of رسول الله صلي الله عليه وسلمs reaction that is the strongest argument for its historical reality whether you believe that the words he heard came from inside himself or from outside it is clear that he experienced them and he experienced them with the force that shattered his sense of being you know normally when people go into shock they lose their ability to think we know this right but with the messenger عليه السلام it was the opposite he was able to maintain his focus and presence of mind how do we know that the proof of that consciousness is in what he said to his wife حضرت خديجه سلام الله عليها when he returned home', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 26, NULL, 'What did he say? The first words that came out of his mouth when he returned home, what did he say? زَمِّلُونِي زَمِّلُونِي, which means wrap me up, wrap me up. Now we know that people who experience shock, one of the first things the paramedics will do is they''ll wrap them up, right? You''re actually told to wrap them up to create some sort of containment, because part of the shock is a loss of the self, because the outward and the inward, they crash. That experience, that psychic integrity that we all have of the self being whole, it gets completely shattered when we''re in shock because something has forced itself on the soul. And the Prophet realized that, and so he asked his wife to wrap him up, سُبْحَانَ اللَّهِ. So this was his first encounter with God, with revelation, and that feeling of intense constriction that he experienced. And his very first human response to that experience while maintaining his perfect consciousness. And scholars say that this is a proof that the experience was a divine spiritual experience and not a demonic one. Now let''s look at his second divine experience, which is the night journey of إِسْرَاء, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'what did he say the first words that came out of his mouth when he returned home what did he say زملوني زملوني which means wrap me up wrap me up now we know that people who experience shock one of the first things the paramedics will do is theyll wrap them up right youre actually told to wrap them up to create some sort of containment because part of the shock is a loss of the self because the outward and the inward they crash that experience that psychic integrity that we all have of the self being whole it gets completely shattered when were in shock because something has forced itself on the soul and the prophet realized that and so he asked his wife to wrap him up سبحان الله so this was his first encounter with god with revelation and that feeling of intense constriction that he experienced and his very first human response to that experience while maintaining his perfect consciousness and scholars say that this is a proof that the experience was a divine spiritual experience and not a demonic one now lets look at his second divine experience which is the night journey of اسراء right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 27, NULL, 'And that actual ascension to the heavens, which is مَحَرَجْ. The first experience was establishing a connection with the noumenal realm. The second was actually making a journey from the phenomenal realm to the noumenal realm. اللَّه says in the قُرْآن, سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى. Glorified is the one who took his slave by the night from the sanctuary in Mecca to the sanctuary in أَقْصَى in Jerusalem. The word سَارَى in Arabic means to travel in the night. And أَثَرًا is used when someone takes you by the night. You''re not traveling alone, but somebody is taking you. And one of the benefits of using the word night in its singular form, it''s because the Arabs, it took them 40 nights to make the journey from Mecca to Jerusalem. So the verse is emphasizing, highlighting that this journey took place in one single night. Now this migration, interestingly, has two aspects.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'and that actual ascension to the heavens which is محرج the first experience was establishing a connection with the noumenal realm the second was actually making a journey from the phenomenal realm to the noumenal realm الله says in the قران سبحان الذي اسري بعبده ليلا من المسجد الحرام الي المسجد الاقصي glorified is the one who took his slave by the night from the sanctuary in mecca to the sanctuary in اقصي in jerusalem the word ساري in arabic means to travel in the night and اثرا is used when someone takes you by the night youre not traveling alone but somebody is taking you and one of the benefits of using the word night in its singular form its because the arabs it took them 40 nights to make the journey from mecca to jerusalem so the verse is emphasizing highlighting that this journey took place in one single night now this migration interestingly has two aspects', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 28, NULL, 'The first was a physical aspect in which a steed named البُرَاق was brought for the Prophet. البُرَاق is defined as a steed that was smaller than a horse and bigger than a mule. And البُرَاق comes from the word بَرْق, which means lightning. It also means بَرَكَة, which means luminous. So this was a luminous steed that moved at the speed of light, because it went, according to traditions, according to the narrations, it went from one horizon to the other in one step. So it traveled at the speed of light, which we can understand that today. But in those days, that was إِمَامَةٌ, right? So even though it was a physical journey from Makkah to Jerusalem, it took place almost instantaneously. It was at the fastest speed that is possible in the physical world, in this phenomenal realm. But then once he reaches the Mosque of أَقْصَى, the actual ascension, the مِعْرَاج, that''s a metaphysical journey. It was beyond the speed of light.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'the first was a physical aspect in which a steed named البراق was brought for the prophet البراق is defined as a steed that was smaller than a horse and bigger than a mule and البراق comes from the word برق which means lightning it also means بركه which means luminous so this was a luminous steed that moved at the speed of light because it went according to traditions according to the narrations it went from one horizon to the other in one step so it traveled at the speed of light which we can understand that today but in those days that was امامه right so even though it was a physical journey from makkah to jerusalem it took place almost instantaneously it was at the fastest speed that is possible in the physical world in this phenomenal realm but then once he reaches the mosque of اقصي the actual ascension the معراج thats a metaphysical journey it was beyond the speed of light', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 29, NULL, 'It was beyond time and space. You know, today in modern physics, we know that there are things like wormholes, where you can be in one part of the universe and then you go through this wormhole and you''re instantly transported to another part of the universe, right? Thanos in the Avengers. So, I mean, we can understand these things today, but these were unimaginable ideas back in the day, and they were completely unthinkable. So this was the experience of مِعْرَاج. The word مِعْرَاج, it means an instrument of ascension, like a ladder or a stairway. أَرَجًا, the root word, it means a ladder. So the first aspect of the journey, إِسْرَاء, was a physical journey, even if it was at the speed of light. But it was a physical journey. The second one, مِعْرَاج, was beyond the speed of light, where he had a witnessing of اللهُ سُبْحَانَهُ وَتَعَالَى. The قُرْآن says, he came so close to God, he came so close to اللَّه until he was at a distance of two bows'' length with God, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'it was beyond time and space you know today in modern physics we know that there are things like wormholes where you can be in one part of the universe and then you go through this wormhole and youre instantly transported to another part of the universe right thanos in the avengers so i mean we can understand these things today but these were unimaginable ideas back in the day and they were completely unthinkable so this was the experience of معراج the word معراج it means an instrument of ascension like a ladder or a stairway ارجا the root word it means a ladder so the first aspect of the journey اسراء was a physical journey even if it was at the speed of light but it was a physical journey the second one معراج was beyond the speed of light where he had a witnessing of الله سبحانه وتعالي the قران says he came so close to god he came so close to الله until he was at a distance of two bows length with god right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 30, NULL, 'So if you have a bow and arrow and you put two bows one in front of the other, that was the distance between him and his Lord. And scholars say that, I mean, this تَأْوِيل and all of that behind that, without going into any of that, the general description that scholars have given is that it''s an, it''s the two bows is an honorific expression of how close the Prophet SAW got to his Lord without breaching the أَدَب. Because you know, in those traditions, in that time, the closest you could get to a king was the distance of two bows. And of course, قُرْآن always speaks in a language that the Arabs can understand. So اللَّه uses the same metaphors that they understand. And دَنَا actually represents a مَقَام. It doesn''t represent a مَكَان, right? A مَقَام is a station. So it represents the closeness of station, not of place, because there is no physicality there. You cannot go into the physical presence of اللَّه because he''s not physical and he''s beyond physicality.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so if you have a bow and arrow and you put two bows one in front of the other that was the distance between him and his lord and scholars say that i mean this تاويل and all of that behind that without going into any of that the general description that scholars have given is that its an its the two bows is an honorific expression of how close the prophet saw got to his lord without breaching the ادب because you know in those traditions in that time the closest you could get to a king was the distance of two bows and of course قران always speaks in a language that the arabs can understand so الله uses the same metaphors that they understand and دنا actually represents a مقام it doesnt represent a مكان right a مقام is a station so it represents the closeness of station not of place because there is no physicality there you cannot go into the physical presence of الله because hes not physical and hes beyond physicality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 31, NULL, 'Now, if you look at the قُرْآنic description of this experience that he had in مِعْرَاج, it says, ‏مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ ‎. His vision did not deviate, nor did it rebel against him. Now, we need to understand this in the context of what was happening to him. Imagine, I want you to imagine as I say this, that he''s moving through the seven heavens, which means that he was being given this unveiling of the unseen world, this numenal realm. The عَالِمُ الْغَيْبِ, the unseen world, was literally being unveiled for him. Now if we all had that same experience of this unveiling right now, right, if اللَّه removed this veil from before us, the vast majority of us would just literally go insane. We''d just not be able to handle it. Because it would be too much stimulation, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'now if you look at the قرانic description of this experience that he had in معراج it says ما زاغ البصر وما طغي his vision did not deviate nor did it rebel against him now we need to understand this in the context of what was happening to him imagine i want you to imagine as i say this that hes moving through the seven heavens which means that he was being given this unveiling of the unseen world this numenal realm the عالم الغيب the unseen world was literally being unveiled for him now if we all had that same experience of this unveiling right now right if الله removed this veil from before us the vast majority of us would just literally go insane wed just not be able to handle it because it would be too much stimulation right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 32, NULL, 'We know in our material sciences today, we know that we''re seeing less than a billionth of the material stimuli at any given moment. In other words, when you and I look out into the room we''re sitting in right now, we are seeing less than a billionth of what is materially there to stimulate our senses. Visible light, it''s a very small spectrum on the electromagnetic spectrum. I mean, and that''s how limited we are if we have 20/20 vision. So, and then we also know that the majority of the universe is dark matter. We know that, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'we know in our material sciences today we know that were seeing less than a billionth of the material stimuli at any given moment in other words when you and i look out into the room were sitting in right now we are seeing less than a billionth of what is materially there to stimulate our senses visible light its a very small spectrum on the electromagnetic spectrum i mean and thats how limited we are if we have 20 20 vision so and then we also know that the majority of the universe is dark matter we know that right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 33, NULL, '95% of the physical universe is not even perceived. So when these scientists, when they started looking outside, they saw all these stars everywhere. So they had to ask the question, why isn''t the night sky as bright as the day sky? Because if light travels and if all of these enormous lights are out there, right? If the heavens is filled with these orbs of light, then why aren''t they filling up the night sky the same way? Cause it should be like really bright all the time. Because we only see about 3,000 stars on a really clear, like a moonless night. And what they found out is that only the light from certain stars are penetrating through. It''s literally a visitation. Like they''re visiting and then returning back. And that''s really interesting because the قُرْآن says, He says, I swear by the night and the night visitor.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', '95 of the physical universe is not even perceived so when these scientists when they started looking outside they saw all these stars everywhere so they had to ask the question why isnt the night sky as bright as the day sky because if light travels and if all of these enormous lights are out there right if the heavens is filled with these orbs of light then why arent they filling up the night sky the same way cause it should be like really bright all the time because we only see about 3 000 stars on a really clear like a moonless night and what they found out is that only the light from certain stars are penetrating through its literally a visitation like theyre visiting and then returning back and thats really interesting because the قران says he says i swear by the night and the night visitor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 34, NULL, 'سُبْحَانَ اللهِ, 1400 years back, the قُرْآن is saying that the light from the stars make a journey to get here. And it''s quite literally like a guest who comes in the night. And then it says, . What will convey to you what this night visitor is? The piercing star. Now, سُقْب in Arabic, it means to put a hole through a pearl. That''s what سُقْب means. You know, when you make a pearl تَسْبِيح, you have to literally make a hole in each pearl so that you can penetrate the thread through it, right? That''s سُقْب, to put a hole through a pearl. And this light of the stars that we know today, they''re reaching us, they''re literally penetrating and making a hole in this celestial pearl. Isn''t that fascinating? سُبْحَانَ اللهِ.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'سبحان الله 1400 years back the قران is saying that the light from the stars make a journey to get here and its quite literally like a guest who comes in the night and then it says what will convey to you what this night visitor is the piercing star now سقب in arabic it means to put a hole through a pearl thats what سقب means you know when you make a pearl تسبيح you have to literally make a hole in each pearl so that you can penetrate the thread through it right thats سقب to put a hole through a pearl and this light of the stars that we know today theyre reaching us theyre literally penetrating and making a hole in this celestial pearl isnt that fascinating سبحان الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 35, NULL, 'Anyway, I was saying that what we know about this seen world is incredibly small, and yet the unseen world we have absolutely no knowledge of. But then, as he''s on about this journey, اللَّه says His vision did not deviate nor did it rebel against him. My question is, why not? Why did it not deviate? I mean, if you''re traveling through this unseen realm for the first time and all of this unveiling was occurring and you were witnessing these extraordinary things, why would you not be distracted? Right?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'anyway i was saying that what we know about this seen world is incredibly small and yet the unseen world we have absolutely no knowledge of but then as hes on about this journey الله says his vision did not deviate nor did it rebel against him my question is why not why did it not deviate i mean if youre traveling through this unseen realm for the first time and all of this unveiling was occurring and you were witnessing these extraordinary things why would you not be distracted right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 36, NULL, 'The answer goes back to the heart of the Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, who had only one concern that night, which was to visit his Lord. To meet his Lord. He was on a journey to meet his beloved, and he was not interested in the particulars, no matter how amazing they were. And so he was not distracted by anything else, because to him this was the journey of a lover to meet his beloved. I mean, if you''ve ever had that experience, you know you''re not going to care about anything else in the world. All you want is to see the face of your beloved. You''ll travel continents, fly across oceans to do it. Because they say, everything that you can ever desire exists in your beloved.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'the answer goes back to the heart of the prophet صلي الله عليه وسلم who had only one concern that night which was to visit his lord to meet his lord he was on a journey to meet his beloved and he was not interested in the particulars no matter how amazing they were and so he was not distracted by anything else because to him this was the journey of a lover to meet his beloved i mean if youve ever had that experience you know youre not going to care about anything else in the world all you want is to see the face of your beloved youll travel continents fly across oceans to do it because they say everything that you can ever desire exists in your beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 37, NULL, 'Your beloved is the star, the moon, the universe, right? And so the actual things don''t really matter. And this holds true in the worldly sense for us human beings. But here we''re talking about اللهُ سُبْحَانَهُ وَتَعَالَى, so you can only imagine, right? His heart''s desire was اللَّه and nothing else. And to be honest about it, if you think about, you know, everything that we are running and chasing in this world, everything we''re looking for, searching for, it''s ultimately our heart''s desire. That''s all what this is about.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'your beloved is the star the moon the universe right and so the actual things dont really matter and this holds true in the worldly sense for us human beings but here were talking about الله سبحانه وتعالي so you can only imagine right his hearts desire was الله and nothing else and to be honest about it if you think about you know everything that we are running and chasing in this world everything were looking for searching for its ultimately our hearts desire thats all what this is about', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 38, NULL, 'So now when he returns from that divine experience, he''s completely transformed. He is now ready to move on to the next phase, which is to be in this world free of all attachments. Because the world is no longer a threat to him as a distraction. He has seen the ultimate reality. So now he can never misperceive this world.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so now when he returns from that divine experience hes completely transformed he is now ready to move on to the next phase which is to be in this world free of all attachments because the world is no longer a threat to him as a distraction he has seen the ultimate reality so now he can never misperceive this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 39, NULL, 'This, in our tradition, is what''s called the right understanding or the first understanding. That we must perceive the world correctly, because our lack of perception, our misinterpretation of this world is what causes pain. And this concept is actually very dominant in the Buddhist tradition, that, you know, all suffering comes from a lack of understanding of the true nature of things. Suffering is related to desire. Now, what I find really fascinating is that the word for desire in Arabic, which is , it also means oppression. That''s awesome. The word for desire and the word for oppression are the same in Arabic. Why? Because desires oppress. So the concept of freedom in الْإِسْلَام is not the elimination of desire. It is not the elimination of desire. الْإِسْلَام does not ask us to eliminate desire, because that''s impossible.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'this in our tradition is whats called the right understanding or the first understanding that we must perceive the world correctly because our lack of perception our misinterpretation of this world is what causes pain and this concept is actually very dominant in the buddhist tradition that you know all suffering comes from a lack of understanding of the true nature of things suffering is related to desire now what i find really fascinating is that the word for desire in arabic which is it also means oppression thats awesome the word for desire and the word for oppression are the same in arabic why because desires oppress so the concept of freedom in الاسلام is not the elimination of desire it is not the elimination of desire الاسلام does not ask us to eliminate desire because thats impossible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 40, NULL, 'Right? What الْإِسْلَام teaches us is to make our desire the right desire. To desire the right things. And for a believer, there is nothing more desirable than the company of اللَّه. So these are the two incredible experiences of our Prophet, right? The experience of وَحْيٌ through the medium of جِبْرِيل, and a second experience, which is a direct witnessing of his master without any veils, where he receives this gift of this immense expansion in his soul, taking him to the pinnacle of his الْإِسْلَام. But الْإِسْلَام did not begin that way for him, did it? It did not begin with a direct experience. It began with an intermediary one, through a learning process through جِبْرِيل. It began with an extreme constriction of the heart, with fear, with doubts, physical pain, of absorbing the revelation. And then followed by 13 years of persecution, trials, hardships, only then the unveiling of the unseen realm occurred for him.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'right what الاسلام teaches us is to make our desire the right desire to desire the right things and for a believer there is nothing more desirable than the company of الله so these are the two incredible experiences of our prophet right the experience of وحي through the medium of جبريل and a second experience which is a direct witnessing of his master without any veils where he receives this gift of this immense expansion in his soul taking him to the pinnacle of his الاسلام but الاسلام did not begin that way for him did it it did not begin with a direct experience it began with an intermediary one through a learning process through جبريل it began with an extreme constriction of the heart with fear with doubts physical pain of absorbing the revelation and then followed by 13 years of persecution trials hardships only then the unveiling of the unseen realm occurred for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 41, NULL, 'Right? And the reason I wanted to share this with you because this had really like an incredible impact on me, so I just thought, you know, I wanted to share this with you so that, you know, especially my young, the young adults in this group, I have my nieces, my nephews, and I wanted to share this because to me, this felt like the Prophet''s experience, for me, it''s like an archetype. It''s like a precedent. Because for me, this is generally the experience of entering الْإِسْلَام. It''s a journey for us. We are all on a path traveling towards our master. And the experience of رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ sets this precedence for us. You know, just as the journey for him began with تَخْلِيَة, an emptying of the heart, just as it began with تَحَنُّث, the identification and the detachment from elements of this world that distract us from اللَّه, we have to go through the same exercise. We have to work on managing our desires, not eliminating it, managing it, channeling it, making our desires the right desire, which is اللهُ سُبْحَانَهُ وَتَعَالَى, right? And we are in the process of the first journey, where we are learning, the noumenal realm is being unveiled for us through intermediaries, through our teachers, through our مَنَاصِب, دُعَاءٌ, ائِمَّة.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'right and the reason i wanted to share this with you because this had really like an incredible impact on me so i just thought you know i wanted to share this with you so that you know especially my young the young adults in this group i have my nieces my nephews and i wanted to share this because to me this felt like the prophets experience for me its like an archetype its like a precedent because for me this is generally the experience of entering الاسلام its a journey for us we are all on a path traveling towards our master and the experience of رسول الله صلي الله عليه وسلم sets this precedence for us you know just as the journey for him began with تخليه an emptying of the heart just as it began with تحنث the identification and the detachment from elements of this world that distract us from الله we have to go through the same exercise we have to work on managing our desires not eliminating it managing it channeling it making our desires the right desire which is الله سبحانه وتعالي right and we are in the process of the first journey where we are learning the noumenal realm is being unveiled for us through intermediaries through our teachers through our مناصب دعاء ايمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 42, NULL, 'These are all our intermediaries. We''re going through the same process. For him it was جِبْرِيل, for us it is them. Because we can''t really, we can''t absorb that revelation directly. So it has to be filtered. Right? But this is where it all began. And that''s what الْإِسْلَام is, at the end of the day that''s what this is. Do you want to make this journey or not? I mean, if you''re not interested in this journey, then الْإِسْلَام is not for you. Seriously. Enjoy the pleasures of this world and actually make the most of it while you can.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'these are all our intermediaries were going through the same process for him it was جبريل for us it is them because we cant really we cant absorb that revelation directly so it has to be filtered right but this is where it all began and thats what الاسلام is at the end of the day thats what this is do you want to make this journey or not i mean if youre not interested in this journey then الاسلام is not for you seriously enjoy the pleasures of this world and actually make the most of it while you can', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 43, NULL, 'That''s my advice to you. If you''re not interested in taking this journey to اللَّه, enjoy the world. Because it''s not gonna last. Before you know it, it''s gonna be over and you''re gonna be left in misery and despair. These are principles. We''re not making this up. This is true. You can see this, right? So first decide what you want to do. I mean, when you go on vacations, holidays, what''s the first thing you do? You look it up, right? You Google those vacation spots.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'thats my advice to you if youre not interested in taking this journey to الله enjoy the world because its not gonna last before you know it its gonna be over and youre gonna be left in misery and despair these are principles were not making this up this is true you can see this right so first decide what you want to do i mean when you go on vacations holidays whats the first thing you do you look it up right you google those vacation spots', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 44, NULL, 'Why do you do that? To find out if it''s worth your effort. Right? If you''re going to spend so much money, make the effort to travel all the way across continents. You want to make sure that you''ll get what you''re looking for. Right? You ask people, have you been there? How was it? Did you have a really good time? Was it a good experience? Was it relaxing? Did you have fun?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'why do you do that to find out if its worth your effort right if youre going to spend so much money make the effort to travel all the way across continents you want to make sure that youll get what youre looking for right you ask people have you been there how was it did you have a really good time was it a good experience was it relaxing did you have fun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 45, NULL, 'Was it beautiful? Can you show me pictures? Right? Same thing here. Look it up. Look up الْإِسْلَام, learn about الْإِسْلَام. Find out what it offers in the end, and then decide whether you want it or not. And if you don''t, no problem. Tell them that the truth has been revealed by your master. Whoever desires it can become a believer. Who does not desire it, he can reject it. This is اللَّه saying in the قُرْآن. الْإِسْلَام is not for everyone. It really isn''t. I mean, الْإِسْلَام is an enormous gift that has to be earned. The company of اللَّه, the company of the Prophet is an incredible privilege that has to be earned. This is not a cheap religion. This is not an easy religion in terms of work.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'was it beautiful can you show me pictures right same thing here look it up look up الاسلام learn about الاسلام find out what it offers in the end and then decide whether you want it or not and if you dont no problem tell them that the truth has been revealed by your master whoever desires it can become a believer who does not desire it he can reject it this is الله saying in the قران الاسلام is not for everyone it really isnt i mean الاسلام is an enormous gift that has to be earned the company of الله the company of the prophet is an incredible privilege that has to be earned this is not a cheap religion this is not an easy religion in terms of work', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 46, NULL, 'It requires hard work. I mean, if you don''t believe me, study the life of رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, then look at the end of his journey, right? Like I said, happiness is the sum total of your life. That''s felicity. It''s not the means, it''s the end. مَوْلَانَا عَلِيٌّ عَلَيْهِ السَّلَامُ says in one of his sermons in نَهْجُ الْبَلَاغَةِ, he says, and I''m paraphrasing, but he says something like, if you are looking for glory and greatness, look at the life of the Prophet. Did اللَّه elevate him in this world for his hard work, or did he abase him? If you say he abased him, then you are a liar. But if you say that he gave him glory, then you have spoken the truth, for his name and his efforts will shine on the sky of الْإِسْلَام like the sun till the end of time. سُبْحَانَ اللهِ. Like, I don''t know, can''t say it in any better words. His example is right here. Look who he is, who he became and who he has become to the world, the love for him. But it wasn''t easy.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'it requires hard work i mean if you dont believe me study the life of رسول الله صلي الله عليه وسلم then look at the end of his journey right like i said happiness is the sum total of your life thats felicity its not the means its the end مولانا علي عليه السلام says in one of his sermons in نهج البلاغه he says and im paraphrasing but he says something like if you are looking for glory and greatness look at the life of the prophet did الله elevate him in this world for his hard work or did he abase him if you say he abased him then you are a liar but if you say that he gave him glory then you have spoken the truth for his name and his efforts will shine on the sky of الاسلام like the sun till the end of time سبحان الله like i dont know cant say it in any better words his example is right here look who he is who he became and who he has become to the world the love for him but it wasnt easy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 47, NULL, 'So you make a decision. Have you guys watched that Matrix? It''s literally blue pill or red pill. You can take the blue pill and you can go back to sleep and enjoy the delusions and shadows of this world, right? Or you can take the red pill and wake up. Disconnect from the Matrix. I mean, it''s a choice. Now, if you do decide to take the red pill, even in that movie, right, Keanu Reeves, what does he have to do once you take the red pill? It''s all work, training. So if you decide that you want to take this journey, then prepare for it. Don''t be afraid of hard work.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'so you make a decision have you guys watched that matrix its literally blue pill or red pill you can take the blue pill and you can go back to sleep and enjoy the delusions and shadows of this world right or you can take the red pill and wake up disconnect from the matrix i mean its a choice now if you do decide to take the red pill even in that movie right keanu reeves what does he have to do once you take the red pill its all work training so if you decide that you want to take this journey then prepare for it dont be afraid of hard work', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 48, NULL, 'Yes, الْإِسْلَام is a lot of hard work. So what? Look at a bodybuilder, right? Look at these incredible athletes. I mean, you think they got where they are today just by wanting to get there? No. Hard work, discipline, endless hours of training, proper diet, millions of reps and sets consistently done year after year. But go and ask them if it was worth it, see what they say. They''ll say it was absolutely worth it. So if you want this path of spiritual ascension, then focus. His vision did not deviate. It did not rebel against him.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'yes الاسلام is a lot of hard work so what look at a bodybuilder right look at these incredible athletes i mean you think they got where they are today just by wanting to get there no hard work discipline endless hours of training proper diet millions of reps and sets consistently done year after year but go and ask them if it was worth it see what they say theyll say it was absolutely worth it so if you want this path of spiritual ascension then focus his vision did not deviate it did not rebel against him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 49, NULL, 'Don''t let the world distract you. Don''t let the temptations get you off your path. And we will make it. I mean, I know what I want. I made my choice a long time ago. To me personally, الْإِسْلَام was really difficult when I started, but the more I learned about it, the more I practiced it, the easier it got for me. And I''m sure many in this group, we have elders, my parents are in here, they''ll testify that it''s true to be as their own experience. I love my الْإِسْلَام today. I love the experience of my الْإِسْلَام. I''m not just saying that, you know that I do. Many of you know me personally, right? It has transformed me completely.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'dont let the world distract you dont let the temptations get you off your path and we will make it i mean i know what i want i made my choice a long time ago to me personally الاسلام was really difficult when i started but the more i learned about it the more i practiced it the easier it got for me and im sure many in this group we have elders my parents are in here theyll testify that its true to be as their own experience i love my الاسلام today i love the experience of my الاسلام im not just saying that you know that i do many of you know me personally right it has transformed me completely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 50, NULL, 'I mean the contentment, the freedom that I feel. اللَّهُ أَكْبَرُ. My خَلَّاصٌ are actually in this group. I have at least three خَلَّاصٌ in here and others from my family. Ask them, seriously. They''ll tell you who I used to be compared to who I am today. الْحَمْدُ لِلَّهِ. And yes, I''ll make mistakes. I''ll still continue to make mistakes along the way. So what? Who has asked you for perfection? Show me one verse in the قُرْآن that demands perfection. One verse. Over 6000 verses in the قُرْآن, show me one verse that says you have to be perfect. No, never. All it demands is effort, right? All I want from this life is to meet my Lord, my Prophet as a better and improved version of from when I came in this world. That''s all. I''m never going to be perfect. I''m never gonna not miss my prayer. I''m never gonna not miss a fast. I will sin from time to time. So what? I''m not God. I''m human. Only God is perfect. What, bodybuilders, they don''t miss a training day? They don''t have cheat days? Athletes don''t make mistakes? So what, do they stop training? Do they stop playing?', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'i mean the contentment the freedom that i feel الله اكبر my خلاص are actually in this group i have at least three خلاص in here and others from my family ask them seriously theyll tell you who i used to be compared to who i am today الحمد لله and yes ill make mistakes ill still continue to make mistakes along the way so what who has asked you for perfection show me one verse in the قران that demands perfection one verse over 6000 verses in the قران show me one verse that says you have to be perfect no never all it demands is effort right all i want from this life is to meet my lord my prophet as a better and improved version of from when i came in this world thats all im never going to be perfect im never gonna not miss my prayer im never gonna not miss a fast i will sin from time to time so what im not god im human only god is perfect what bodybuilders they dont miss a training day they dont have cheat days athletes dont make mistakes so what do they stop training do they stop playing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 51, NULL, 'Did they start blaming the game? I mean, that''s ridiculous, right? Anyway, I just wanted to, you know, honestly share these experiences with you because they really helped me make a choice. You know, I really clearly know what I want and I know what I have to do to get where I wanted to get and, you know, what I''ll have to give up for it, and I''m cool with that. I have no regrets about it.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'did they start blaming the game i mean thats ridiculous right anyway i just wanted to you know honestly share these experiences with you because they really helped me make a choice you know i really clearly know what i want and i know what i have to do to get where i wanted to get and you know what ill have to give up for it and im cool with that i have no regrets about it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 52, NULL, 'And this amazing experience of contentment, of just freedom, is something you can have also. So may اللَّه help us all follow in the footsteps of our Prophet, and may He enable us to truly, truly experience the beauty of الْإِسْلَام, because it is so beautiful. I can''t, I mean... الْحَمْدُ لِلَّهِ, I can''t, you know, there''s my grandfather, used to, my mother used to say that, he said that, you know, if you knew how lucky we are to be Muslims, we would never raise our head from سَجْدَة. And I never got that. I''m like, that is such an extreme exaggeration.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'and this amazing experience of contentment of just freedom is something you can have also so may الله help us all follow in the footsteps of our prophet and may he enable us to truly truly experience the beauty of الاسلام because it is so beautiful i cant i mean الحمد لله i cant you know theres my grandfather used to my mother used to say that he said that you know if you knew how lucky we are to be muslims we would never raise our head from سجده and i never got that im like that is such an extreme exaggeration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'islam as an experience', 'Islam As An Experience', 53, NULL, 'Like, what does that even mean? But today, I know what that means. I honestly, وَاللَّهِ, I know what it means. I cannot, I cannot even express how grateful I am for this guidance that اللَّه has blessed me with. الْحَمْدُ لِلَّهِ، رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِ مُحَمَّدٍ الْخَاتِمِ عَلَيْهِمْ أَجْمَعِينَ. رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا. رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ. رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ', '', 'وَاللَّهِ اللَّه الْحَمْدُ لِلَّهِ، رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِ مُحَمَّدٍ الْخَاتِمِ عَلَيْهِمْ أَجْمَعِينَ رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ', NULL, NULL, NULL, 'love of the prophet islam as an experience', 'like what does that even mean but today i know what that means i honestly والله i know what it means i cannot i cannot even express how grateful i am for this guidance that الله has blessed me with الحمد لله رب العالمين والصلاه والسلام علي رسوله سيد محمد الخاتم عليهم اجمعين ربنا اننا سمعنا مناديا ينادي للايمان ان امنوا بربكم فامنا ربنا فاغفر لنا ذنوبنا وكفر عنا سيياتنا وتوفنا مع الابرار ربنا واتنا ما وعدتنا علي رسلك', 'والله الله الحمد لله رب العالمين والصلاه والسلام علي رسوله سيد محمد الخاتم عليهم اجمعين ربنا اننا سمعنا مناديا ينادي للايمان ان امنوا بربكم فامنا ربنا فاغفر لنا ذنوبنا وكفر عنا سيياتنا وتوفنا مع الابرار ربنا واتنا ما وعدتنا علي رسلك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 0, NULL, 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ صَانِعِ الْخَلْقِ عَلَى أَتَمِّ نِظَامٍ وَأَحْسَنِ قِوَامٍ الْوَاضِعِ عَلَى أَشْرَفِ أَجْدَرِ مَقَامٍ وَأَرْفَقِ مَقَامٍ الْحَمْدُ لِلَّهِ عَدَدَ خَلْقِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ وَمُنْتَهَى عِلْمِهِ وَجَمِيعَ مَا شَاءَ وَخَلَقَ وَبَرَأَ وَهُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الرَّحْمَنُ الرَّحِيمُ الْمَلِكُ الْقُدُّوسُ الْعَزِيزُ الْحَكِيمُ وَالصَّلَاةُ وَالسَّلَامُ عَلَى الْمُؤَيَّدِ أَبْلَغِ الْكَلَامِ مُحَمَّدٍ الْمَبْعُوثِ صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ لِهِدَايَةِ كَافَّةِ الْأَنَامِ إِلَى سُبُلِ السَّلَامِ وَإِلَى مَدَلَّةِ اللَّيَالِي وَالْأَيَّامِ الَّذِي أَرْسَلَهُ اللهُ تَعَالَى بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللهِ شَهِيدًا وَنَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ وَنَشْهَدُ أَنَّ مَوْلَانَا عَلِيًّا وَصِيُّهُ وَوَزِيرُهُ فَصَلَّى اللهُ عَلَيْهِمْ وَعَلَى آلِ عَلَيْهِمْ وَسَلِّمْ عَلَيْهِمْ تَسْلِيمًا كَثِيرًا كَثِيرًا اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا اللَّهُمَّ آتِ نُفُوسَنَا تَقْوَاهَا وَزَكِّهَا فَأَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّنَا وَمَوْلَانَا وَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ الْعَلِيِّ الْعَظِيمِ فَأَمَّا بَعْدُ يَقُولُ سُبْحَانَهُ وَتَعَالَى فِي كِتَابِهِ الْكَرِيمِ بَعْدَ أَقُولُ أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَمَاتِ عَلَى لَا إِلَهَ إِلَّا اللهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', '', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ صَانِعِ الْخَلْقِ عَلَى أَتَمِّ نِظَامٍ وَأَحْسَنِ قِوَامٍ الْوَاضِعِ عَلَى أَشْرَفِ أَجْدَرِ مَقَامٍ وَأَرْفَقِ مَقَامٍ الْحَمْدُ لِلَّهِ عَدَدَ خَلْقِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ وَمُنْتَهَى عِلْمِهِ وَجَمِيعَ مَا شَاءَ وَخَلَقَ وَبَرَأَ وَهُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الرَّحْمَنُ الرَّحِيمُ الْمَلِكُ الْقُدُّوسُ الْعَزِيزُ الْحَكِيمُ وَالصَّلَاةُ وَالسَّلَامُ عَلَى الْمُؤَيَّدِ أَبْلَغِ الْكَلَامِ مُحَمَّدٍ الْمَبْعُوثِ صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ لِهِدَايَةِ كَافَّةِ الْأَنَامِ إِلَى سُبُلِ السَّلَامِ وَإِلَى مَدَلَّةِ اللَّيَالِي وَالْأَيَّامِ الَّذِي أَرْسَلَهُ اللهُ تَعَالَى بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللهِ شَهِيدًا وَنَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ وَنَشْهَدُ أَنَّ مَوْلَانَا عَلِيًّا وَصِيُّهُ وَوَزِيرُهُ فَصَلَّى اللهُ عَلَيْهِمْ وَعَلَى آلِ عَلَيْهِمْ وَسَلِّمْ عَلَيْهِمْ تَسْلِيمًا كَثِيرًا كَثِيرًا اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا اللَّهُمَّ آتِ نُفُوسَنَا تَقْوَاهَا وَزَكِّهَا فَأَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّنَا وَمَوْلَانَا وَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ الْعَلِيِّ الْعَظِيمِ فَأَمَّا بَعْدُ يَقُولُ سُبْحَانَهُ وَتَعَالَى فِي كِتَابِهِ الْكَرِيمِ بَعْدَ أَقُولُ أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَمَاتِ عَلَى لَا إِلَهَ إِلَّا اللهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', NULL, NULL, NULL, 'love of the prophet character of the prophet', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله صانع الخلق علي اتم نظام واحسن قوام الواضع علي اشرف اجدر مقام وارفق مقام الحمد لله عدد خلقه وزنه عرشه ومداد كلماته ومنتهي علمه وجميع ما شاء وخلق وبرا وهو عالم الغيب والشهاده الرحمن الرحيم الملك القدوس العزيز الحكيم والصلاه والسلام علي المويد ابلغ الكلام محمد المبعوث صلي الله عليه وعلي اله وسلم لهدايه كافه الانام الي سبل السلام والي مدله الليالي والايام الذي ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبده ورسوله ونشهد ان مولانا عليا وصيه ووزيره فصلي الله عليهم وعلي ال عليهم وسلم عليهم تسليما كثيرا كثيرا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم ات نفوسنا تقواها وزكها فانت خير من زكاها انت ولينا ومولانا ونعم المولي ونعم النصير ولا حول ولا قوه الا بالله العلي العظيم فاما بعد يقول سبحانه وتعالي في كتابه الكريم بعد اقول اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الممات علي لا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله صانع الخلق علي اتم نظام واحسن قوام الواضع علي اشرف اجدر مقام وارفق مقام الحمد لله عدد خلقه وزنه عرشه ومداد كلماته ومنتهي علمه وجميع ما شاء وخلق وبرا وهو عالم الغيب والشهاده الرحمن الرحيم الملك القدوس العزيز الحكيم والصلاه والسلام علي المويد ابلغ الكلام محمد المبعوث صلي الله عليه وعلي اله وسلم لهدايه كافه الانام الي سبل السلام والي مدله الليالي والايام الذي ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبده ورسوله ونشهد ان مولانا عليا وصيه ووزيره فصلي الله عليهم وعلي ال عليهم وسلم عليهم تسليما كثيرا كثيرا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم ات نفوسنا تقواها وزكها فانت خير من زكاها انت ولينا ومولانا ونعم المولي ونعم النصير ولا حول ولا قوه الا بالله العلي العظيم فاما بعد يقول سبحانه وتعالي في كتابه الكريم بعد اقول اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الممات علي لا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 1, NULL, 'Once again, سَلَامٌ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. الْحَمْدُ لِلَّهِ, today I حُبُّ النَّبِيِّve the honor of speaking about the beloved of اللهُ. He was حَبِيبُ اللهِ, the beloved of اللهُ. His name is Muحُبُّ النَّبِيِّmmad. The name Muحُبُّ النَّبِيِّmmad comes from the root word حَمْد, which means praise and gratitude. And Muحُبُّ النَّبِيِّmmad is the one who is constantly praised and who is worthy of eternal gratitude. And so, just as اللهُ is رَبُّ الْعَالَمِينَ, the master of everything in existence, His messenger is رَحْمَةً لِلْعَالَمِينَ.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'once again سلام عليكم ورحمه الله وبركاته الحمد لله today i حب النبيve the honor of speaking about the beloved of الله he was حبيب الله the beloved of الله his name is muحب النبيmmad the name muحب النبيmmad comes from the root word حمد which means praise and gratitude and muحب النبيmmad is the one who is constantly praised and who is worthy of eternal gratitude and so just as الله is رب العالمين the master of everything in existence his messenger is رحمه للعالمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 2, NULL, 'He is a mercy for everything in existence. So everything tحُبُّ النَّبِيِّt اللهُ is the رَبّ of, He is a mercy for. And He is the one whose love اللهُ حُبُّ النَّبِيِّs made a prerequisite for His own love, in tحُبُّ النَّبِيِّt we cannot claim the love of اللهُ without loving His beloved Messenger, صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he is a mercy for everything in existence so everything tحب النبيt الله is the رب of he is a mercy for and he is the one whose love الله حب النبيs made a prerequisite for his own love in tحب النبيt we cannot claim the love of الله without loving his beloved messenger صلي الله عليه وسلم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 3, NULL, 'Scholars say tحُبُّ النَّبِيِّt مَحَبَّة, or love, for most human beings, it arises out of three things. The first, they say, is physical love. You see something beautiful, your heart inclines towards them, right? Your eyes delight in it. If you see a human being tحُبُّ النَّبِيِّt is physically beautiful, you can fall in love. It can حُبُّ النَّبِيِّppen just from sight. And the عُلَمَاء حُبُّ النَّبِيِّve maintained the physical description of our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, which is the description of a very حُبُّ النَّبِيِّndsome man.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'scholars say tحب النبيt محبه or love for most human beings it arises out of three things the first they say is physical love you see something beautiful your heart inclines towards them right your eyes delight in it if you see a human being tحب النبيt is physically beautiful you can fall in love it can حب النبيppen just from sight and the علماء حب النبيve maintained the physical description of our prophet صلي الله عليه وسلم which is the description of a very حب النبيndsome man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 4, NULL, 'The second type of love comes from when you hear about the beautiful qualities of a person. So there is outward beauty, and then there is inward beauty, which is wحُبُّ النَّبِيِّt I حُبُّ النَّبِيِّve the honor of sحُبُّ النَّبِيِّring with you today.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'the second type of love comes from when you hear about the beautiful qualities of a person so there is outward beauty and then there is inward beauty which is wحب النبيt i حب النبيve the honor of sحب النبيring with you today', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 5, NULL, 'The third type of love, they say, is wحُبُّ النَّبِيِّt you feel for someone who حُبُّ النَّبِيِّs done good for you, or tحُبُّ النَّبِيِّt you find out tحُبُّ النَّبِيِّt somebody made a sacrifice for you. So when someone does something good to a decent human being, they love them more and more for tحُبُّ النَّبِيِّt reason. But when good is done to an ingrate, he resents tحُبُّ النَّبِيِّt person because it generates an envy in his heart. They begin to feel indebted and they do not like tحُبُّ النَّبِيِّt feeling of being indebted. So they begin to use strategies within themselves to not feel indebted to tحُبُّ النَّبِيِّt person, and these are sick people. This is why the hypocrites, the مُنَافِقُونَ, are the sickest people, and they are rightfully in the lowest place in the eyes of اللهُ. Because human hearts by nature love those who do good to them. If somebody does good for you and then you do not حُبُّ النَّبِيِّve love for them in return, it''s because the heart is not in a natural state, it''s in a diseased state. And if you knew wحُبُّ النَّبِيِّt the Prophet did for you, you would just naturally fall in love with him. And he did not just do it for you or for, you know, certain people.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'the third type of love they say is wحب النبيt you feel for someone who حب النبيs done good for you or tحب النبيt you find out tحب النبيt somebody made a sacrifice for you so when someone does something good to a decent human being they love them more and more for tحب النبيt reason but when good is done to an ingrate he resents tحب النبيt person because it generates an envy in his heart they begin to feel indebted and they do not like tحب النبيt feeling of being indebted so they begin to use strategies within themselves to not feel indebted to tحب النبيt person and these are sick people this is why the hypocrites the منافقون are the sickest people and they are rightfully in the lowest place in the eyes of الله because human hearts by nature love those who do good to them if somebody does good for you and then you do not حب النبيve love for them in return its because the heart is not in a natural state its in a diseased state and if you knew wحب النبيt the prophet did for you you would just naturally fall in love with him and he did not just do it for you or for you know certain people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 6, NULL, 'He did it for the entire humanity. His concern was not just for his companions or his family. You know, most human beings, we''re just concerned, you know, we حُبُّ النَّبِيِّve limited concerns. Our concern is limited to wife, children, husband, family, at the most extended family, right? Some people, their concern is the community. They care about the poor people in the community. They want to find them and help them, because ultimately the love حُبُّ النَّبِيِّs to do with the heart. Tحُبُّ النَّبِيِّt''s where love resides, right? The bigger the heart, the more capacity for love, and the smaller the heart, the lower the capacity for love. And our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُبُّ النَّبِيِّd the heart tحُبُّ النَّبِيِّt was concerned for the entire humanity, for generations to come. He was concerned for animals. In the شَرِيعَة, he gave us guidelines on how to treat animals with kindness. صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he did it for the entire humanity his concern was not just for his companions or his family you know most human beings were just concerned you know we حب النبيve limited concerns our concern is limited to wife children husband family at the most extended family right some people their concern is the community they care about the poor people in the community they want to find them and help them because ultimately the love حب النبيs to do with the heart tحب النبيts where love resides right the bigger the heart the more capacity for love and the smaller the heart the lower the capacity for love and our prophet صلي الله عليه وسلم حب النبيd the heart tحب النبيt was concerned for the entire humanity for generations to come he was concerned for animals in the شريعه he gave us guidelines on how to treat animals with kindness صلي الله عليه وسلم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 7, NULL, 'Learning about the Prophet Seera, his life story, is one of the most beautiful things there is to learn. And this information is readily available in books and on the internet. I mean, you can look tحُبُّ النَّبِيِّt up. I would love to speak about it, but for the want of time, I''m just limiting my session to just talk about some of the salient features of his life and sحُبُّ النَّبِيِّre with you wحُبُّ النَّبِيِّt an incredible man he was. And so I want to focus today''s session on أَخْلَاق. إِن شَآءَ ٱللَّهُ, if اللهُ gives me an opportunity, someday I would love to just do a session on his physical description, which is quite incredible.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'learning about the prophet seera his life story is one of the most beautiful things there is to learn and this information is readily available in books and on the internet i mean you can look tحب النبيt up i would love to speak about it but for the want of time im just limiting my session to just talk about some of the salient features of his life and sحب النبيre with you wحب النبيt an incredible man he was and so i want to focus todays session on اخلاق ان شاء الله if الله gives me an opportunity someday i would love to just do a session on his physical description which is quite incredible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 8, NULL, 'Anyway, so today I want to focus this talk on his cحُبُّ النَّبِيِّracter, the أَخْلَاق. The word أَخْلَاق comes from the root word , which means to create. اللهُ سُبْحَانَهُ وَتَعَالَى is خَلْقٌ, He is the creator, and we are مَخْلُوق, we are the creation. We are... اللهُ is the خَلْقٌ, He is the creator, and we are the مَخْلُوق, we are the created beings. We are comprised of a body and a spirit tحُبُّ النَّبِيِّt animates tحُبُّ النَّبِيِّt body, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'anyway so today i want to focus this talk on his cحب النبيracter the اخلاق the word اخلاق comes from the root word which means to create الله سبحانه وتعالي is خلق he is the creator and we are مخلوق we are the creation we are الله is the خلق he is the creator and we are the مخلوق we are the created beings we are comprised of a body and a spirit tحب النبيt animates tحب النبيt body right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 9, NULL, 'Our material form, the material form of our body is the . And the spiritual form of our soul is the . It''s the same three letters. The body is nourished by the physical world, which is food and drink. Our spirits are nourished by knowledge, by cحُبُّ النَّبِيِّracter, which is the plural form of the word . So, the or the represents our physical existence, whereas represents our spiritual existence. And they both begin with the letter . Interestingly, the letter in Arabic is a sound of friction. It''s a sound, they say it''s a sound of effort, even when you articulate it, right? So if you look at any word in the Arabic language tحُبُّ النَّبِيِّt begins with the letter حُبُّ النَّبِيِّ, you''ll see it is either حُبُّ النَّبِيِّrsh in its nature or it requires effort. So for instance, , which is service, servitude, right? begins with حُبُّ النَّبِيِّ and it requires effort.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'our material form the material form of our body is the and the spiritual form of our soul is the its the same three letters the body is nourished by the physical world which is food and drink our spirits are nourished by knowledge by cحب النبيracter which is the plural form of the word so the or the represents our physical existence whereas represents our spiritual existence and they both begin with the letter interestingly the letter in arabic is a sound of friction its a sound they say its a sound of effort even when you articulate it right so if you look at any word in the arabic language tحب النبيt begins with the letter حب النبي youll see it is either حب النبيrsh in its nature or it requires effort so for instance which is service servitude right begins with حب النبي and it requires effort', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 10, NULL, 'Friendship requires effort. Fear, it''s a حُبُّ النَّبِيِّrsh emotion. خَيَالٌ, imagination, it requires effort to build. So you حُبُّ النَّبِيِّve خَلْق and you حُبُّ النَّبِيِّve خُلُقٌ, both starting with the letter حُبُّ النَّبِيِّ. Why? Because the body takes effort to develop and so does cحُبُّ النَّبِيِّracter. Cحُبُّ النَّبِيِّracter takes a lot of effort to develop. When we die, our fully developed body returns back into the earth and our soul with its fully developed cحُبُّ النَّبِيِّracter returns back to the Creator, the خَلْقٌ. So cحُبُّ النَّبِيِّracter is the real earning and the real acquisition of the soul. A soul tحُبُّ النَّبِيِّt returns back to its master without a developed cحُبُّ النَّبِيِّracter is an impoverished soul. When the body is weak, it cannot benefit from the offerings of this world. And when a soul and a spirit is weak, when it lacks cحُبُّ النَّبِيِّracter, it is unable to enjoy the pleasures of the afterlife.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'friendship requires effort fear its a حب النبيrsh emotion خيال imagination it requires effort to build so you حب النبيve خلق and you حب النبيve خلق both starting with the letter حب النبي why because the body takes effort to develop and so does cحب النبيracter cحب النبيracter takes a lot of effort to develop when we die our fully developed body returns back into the earth and our soul with its fully developed cحب النبيracter returns back to the creator the خلق so cحب النبيracter is the real earning and the real acquisition of the soul a soul tحب النبيt returns back to its master without a developed cحب النبيracter is an impoverished soul when the body is weak it cannot benefit from the offerings of this world and when a soul and a spirit is weak when it lacks cحب النبيracter it is unable to enjoy the pleasures of the afterlife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 11, NULL, 'Islam, in its essence, is composed of two parts: worship and the development of cحُبُّ النَّبِيِّracter. أَرِبَ بِهَا and أَخْلَاق. This is why our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ was sent to teach us and perfect our أَخْلَاق. Tحُبُّ النَّبِيِّt was his mission. إِنَّمَا بُعِثْتُ لِأُتَمِّمَ مَكَارِمَ الْأَخْلَاقِ. I was sent for no other reason. إِنَّمَا is a very special usage in the Arabic language. It empحُبُّ النَّبِيِّsizes tحُبُّ النَّبِيِّt wحُبُّ النَّبِيِّtever is being said, tحُبُّ النَّبِيِّt''s the only reason. إِنَّمَا بُعِثْتُ لِأُتَمِّمَ مَكَارِمَ الْأَخْلَاقِ. I was sent for nothing else but to perfect human cحُبُّ النَّبِيِّracter.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'islam in its essence is composed of two parts worship and the development of cحب النبيracter ارب بها and اخلاق this is why our prophet صلي الله عليه وسلم was sent to teach us and perfect our اخلاق tحب النبيt was his mission انما بعثت لاتمم مكارم الاخلاق i was sent for no other reason انما is a very special usage in the arabic language it empحب النبيsizes tحب النبيt wحب النبيtever is being said tحب النبيts the only reason انما بعثت لاتمم مكارم الاخلاق i was sent for nothing else but to perfect human cحب النبيracter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 12, NULL, 'Now, if you ask a Muslim wحُبُّ النَّبِيِّt was the Prophet''s miracle, the unanimous answer tحُبُّ النَّبِيِّt you will get is always the قُرْآن, right? The gift and the miracle indeed to the Arab was the قُرْآن, because the أَجَمْ cannot understand the قُرْآن. The word in Arabic for a non-Arab is أَجَمْ, which means dumb or mute. Somebody who can''t speak, like for instance, the Arabs say, right, the dumb animal. And this is not just limited to Arabic, this applies to other languages as well. For instance, the Greeks, right? The word for a non-Greek for them was بَرْبَر, from which we get بَرْبَرian. So for in Greek بَرْبَر means the one who cannot speak. There''s similar, there''s a word for non-Zulu, right? They حُبُّ النَّبِيِّve the same thing. So people, when they look at other people of other languages and cannot understand them, they assume it must be like animals, because, you know, we can''t understand the speech of animals.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'now if you ask a muslim wحب النبيt was the prophets miracle the unanimous answer tحب النبيt you will get is always the قران right the gift and the miracle indeed to the arab was the قران because the اجم cannot understand the قران the word in arabic for a non arab is اجم which means dumb or mute somebody who cant speak like for instance the arabs say right the dumb animal and this is not just limited to arabic this applies to other languages as well for instance the greeks right the word for a non greek for them was بربر from which we get بربرian so for in greek بربر means the one who cannot speak theres similar theres a word for non zulu right they حب النبيve the same thing so people when they look at other people of other languages and cannot understand them they assume it must be like animals because you know we cant understand the speech of animals', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 13, NULL, 'But the Arabs, when they considered non-Arabs as أَجَمْ, as mute people, it was not out of an insult. They حُبُّ النَّبِيِّd a very good reason for tحُبُّ النَّبِيِّt. Because they would go to a culture, for instance, they would go to a Persian and they would ask, How many words do you حُبُّ النَّبِيِّve for a lion?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'but the arabs when they considered non arabs as اجم as mute people it was not out of an insult they حب النبيd a very good reason for tحب النبيt because they would go to a culture for instance they would go to a persian and they would ask how many words do you حب النبيve for a lion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 14, NULL, 'And the Persians would say, "We حُبُّ النَّبِيِّve one word, lion." Wحُبُّ النَّبِيِّtever in their language the word was for lion. They would say, "We حُبُّ النَّبِيِّve one word for lion." And they would say, "You حُبُّ النَّبِيِّve one word for lion? We حُبُّ النَّبِيِّve over 350 words just for lion." There are over 350 words in the ancient Arabic just for lion. They would say, "We حُبُّ النَّبِيِّve , which is a lion when it hunts at night. We حُبُّ النَّبِيِّve , which is a short, strong lion. We حُبُّ النَّبِيِّve قَسْوَرَة, which is a lion when the animals are fleeing from it. We حُبُّ النَّبِيِّve لَيْث, which is a lion when, you know, they say ... when a lion is circling its prey to attack it, tحُبُّ النَّبِيِّt''s لَيْث." They say, "We حُبُّ النَّبِيِّve أُسْوَةٌ حَسَنَةٌ, which is a lion when it''s leaping to attack."', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'and the persians would say we حب النبيve one word lion wحب النبيtever in their language the word was for lion they would say we حب النبيve one word for lion and they would say you حب النبيve one word for lion we حب النبيve over 350 words just for lion there are over 350 words in the ancient arabic just for lion they would say we حب النبيve which is a lion when it hunts at night we حب النبيve which is a short strong lion we حب النبيve قسوره which is a lion when the animals are fleeing from it we حب النبيve ليث which is a lion when you know they say when a lion is circling its prey to attack it tحب النبيts ليث they say we حب النبيve اسوه حسنه which is a lion when its leaping to attack', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 15, NULL, 'So all of these words tحُبُّ النَّبِيِّt the Arabs use just for a lion. Then there''s حَمْزَة, which is the lion when he''s roaring. There is شِبْلٌ, there is وَرَدَ, there is عَبَّاس, which is used for the leader of the pack. There''s حُبُّ النَّبِيِّ, there''s بَصَلٌ, there is درَامٌ, رِبَال, مَيَّاس, غَضَنْفَر. So many names just for a lion. So when they would hear the Persian say tحُبُّ النَّبِيِّt we حُبُّ النَّبِيِّve only one word for a lion, right, to them they were like أَجَمّ, mute, dumb. So this is the way they would look at things.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'so all of these words tحب النبيt the arabs use just for a lion then theres حمزه which is the lion when hes roaring there is شبل there is ورد there is عباس which is used for the leader of the pack theres حب النبي theres بصل there is درام ربال مياس غضنفر so many names just for a lion so when they would hear the persian say tحب النبيt we حب النبيve only one word for a lion right to them they were like اجم mute dumb so this is the way they would look at things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 16, NULL, 'Now, if you sent a message to people and it''s in Arabic, and the miracle of قُرْآن is truly Arabic, there''s no doubt about tحُبُّ النَّبِيِّt, right? The true أَجْزَلُ الْقُرْآنِ, the true miracle of the قُرْآن is absolutely in the linguistic perfection of Arabic. And I did, I think, over 10 sessions on this a few years ago, looking at the miracle of قُرْآن from 10 different angles, linguistic angles. So Arabic is, no doubt about it, an incredible language. Absolutely no doubt about it. Ancient Arabic, not today''s Arabic, not the dialectical Arabic, the original ancient Arabic. But wحُبُّ النَّبِيِّt does the non-Arab حُبُّ النَّبِيِّve? How does the non-Arab come to know tحُبُّ النَّبِيِّt Islam is indeed a revelation from God? When we read the قُرْآن in English or when we read it in Urdu, we حُبُّ النَّبِيِّve a difficult time understanding it because قُرْآن is not a linear book, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'now if you sent a message to people and its in arabic and the miracle of قران is truly arabic theres no doubt about tحب النبيt right the true اجزل القران the true miracle of the قران is absolutely in the linguistic perfection of arabic and i did i think over 10 sessions on this a few years ago looking at the miracle of قران from 10 different angles linguistic angles so arabic is no doubt about it an incredible language absolutely no doubt about it ancient arabic not todays arabic not the dialectical arabic the original ancient arabic but wحب النبيt does the non arab حب النبيve how does the non arab come to know tحب النبيt islam is indeed a revelation from god when we read the قران in english or when we read it in urdu we حب النبيve a difficult time understanding it because قران is not a linear book right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 17, NULL, 'In the Bible, the Bible, it starts with "in the beginning," right? Bible starts with "in the beginning." Tحُبُّ النَّبِيِّt''s how the Bible starts, "in the beginning." The قُرْآن starts with الم. Wحُبُّ النَّبِيِّt does tحُبُّ النَّبِيِّt mean, الم? We don''t know wحُبُّ النَّبِيِّt tحُبُّ النَّبِيِّt means. And then it says, "Tحُبُّ النَّبِيِّt is the book in which there is no doubt." Not "this is the book in which there is no doubt," "tحُبُّ النَّبِيِّt is the book." So this is how اللهُ begins his book after الْفَاتِحَة.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'in the bible the bible it starts with in the beginning right bible starts with in the beginning tحب النبيts how the bible starts in the beginning the قران starts with الم wحب النبيt does tحب النبيt mean الم we dont know wحب النبيt tحب النبيt means and then it says tحب النبيt is the book in which there is no doubt not this is the book in which there is no doubt tحب النبيt is the book so this is how الله begins his book after الفاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 18, NULL, 'So for us as non-Arabs, it gets very confusing because these things can only be understood properly through Arabic linguistics or the طَوِيل or things like tحُبُّ النَّبِيِّt. But how does the أَجَمْ, the non-Arab, come to understand these things? How does the non-Arab know tحُبُّ النَّبِيِّt this is the truth? And the answer is, look at how they became Muslim. Wherever they went, wherever the Arabs went, wحُبُّ النَّبِيِّt was the factor, tحُبُّ النَّبِيِّt deciding factor tحُبُّ النَّبِيِّt led to for these non-Arabs to become Muslim? It wasn''t the أَعْجَازُ الْقُرْآنِ, because they couldn''t understand Arabic. It was the أَعْجَازُ الْأَخْلَاقِ, it was the أَجَزُّ الْخُلْقِ, the miracle of cحُبُّ النَّبِيِّracter. This was wحُبُّ النَّبِيِّt struck the non-Arab''s heart. And this is why the gift tحُبُّ النَّبِيِّt اللهُ gave to the non-Arabs, to us, is the messenger of اللهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. This is why we see tحُبُّ النَّبِيِّt all over the non-Arab world we find this immense love in the hearts of people for the messenger. Why? Because of his beautiful cحُبُّ النَّبِيِّracter, because of his high ethical standards.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'so for us as non arabs it gets very confusing because these things can only be understood properly through arabic linguistics or the طويل or things like tحب النبيt but how does the اجم the non arab come to understand these things how does the non arab know tحب النبيt this is the truth and the answer is look at how they became muslim wherever they went wherever the arabs went wحب النبيt was the factor tحب النبيt deciding factor tحب النبيt led to for these non arabs to become muslim it wasnt the اعجاز القران because they couldnt understand arabic it was the اعجاز الاخلاق it was the اجز الخلق the miracle of cحب النبيracter this was wحب النبيt struck the non arabs heart and this is why the gift tحب النبيt الله gave to the non arabs to us is the messenger of الله صلي الله عليه وسلم this is why we see tحب النبيt all over the non arab world we find this immense love in the hearts of people for the messenger why because of his beautiful cحب النبيracter because of his high ethical standards', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 19, NULL, 'اللهُ says in the قُرْآن, I think it''s سُورَةُ النُّونِ وَالْقَلَمِ, he begins tحُبُّ النَّبِيِّt surah, I think, with the verse in which he says, اللهُ says to his messenger, absolutely without a doubt you are committed to a high ethical standard, a great ethical standard. Wحُبُّ النَّبِيِّt many people don''t realize is tحُبُّ النَّبِيِّt this particular verse, it was revealed at a very early stage, right after he was chosen as prophet. This verse was revealed right at the beginning of his mission. And wحُبُّ النَّبِيِّt tحُبُّ النَّبِيِّt suggests is tحُبُّ النَّبِيِّt this verse is not referring to the Prophet''s cحُبُّ النَّبِيِّracter as a prophet, it''s referring to his cحُبُّ النَّبِيِّracter as a person, as a member of tحُبُّ النَّبِيِّt society for 40 years, because there is yet the 23 years of his prophethood to unfold. It حُبُّ النَّبِيِّsn''t حُبُّ النَّبِيِّppened yet.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'الله says in the قران i think its سوره النون والقلم he begins tحب النبيt surah i think with the verse in which he says الله says to his messenger absolutely without a doubt you are committed to a high ethical standard a great ethical standard wحب النبيt many people dont realize is tحب النبيt this particular verse it was revealed at a very early stage right after he was chosen as prophet this verse was revealed right at the beginning of his mission and wحب النبيt tحب النبيt suggests is tحب النبيt this verse is not referring to the prophets cحب النبيracter as a prophet its referring to his cحب النبيracter as a person as a member of tحب النبيt society for 40 years because there is yet the 23 years of his prophethood to unfold it حب النبيsnt حب النبيppened yet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 20, NULL, 'This verse is coming right at the beginning, which is showing tحُبُّ النَّبِيِّt this praise is for his cحُبُّ النَّبِيِّracter as a person, not as a prophet. It''s referring to his cحُبُّ النَّبِيِّracter pre-Islam. So he is this regular citizen of this community when God is praising his cحُبُّ النَّبِيِّracter. Why? You know, because you can حُبُّ النَّبِيِّve great things to say, you know, as a preacher, even as a prophet, but a message is hollow in and of itself if it''s not fortified by credibility. And one of the most sustainable forms of credibility is cحُبُّ النَّبِيِّracter. I mean, today you can حُبُّ النَّبِيِّve so many eloquent, well-spoken politicians, right? We see tحُبُّ النَّبِيِّt all the time. But wحُبُّ النَّبِيِّt''s the easiest way to dismantle their entire political campaign? Just smear their cحُبُّ النَّبِيِّracter, right? If you can just find something tحُبُّ النَّبِيِّt''s a flaw in their cحُبُّ النَّبِيِّracter, some kind of corruption, then it doesn''t matter how well they speak or how highly they speak of ideals. None of it really matters at tحُبُّ النَّبِيِّt point because there''s no cحُبُّ النَّبِيِّracter to back up those high claims.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'this verse is coming right at the beginning which is showing tحب النبيt this praise is for his cحب النبيracter as a person not as a prophet its referring to his cحب النبيracter pre islam so he is this regular citizen of this community when god is praising his cحب النبيracter why you know because you can حب النبيve great things to say you know as a preacher even as a prophet but a message is hollow in and of itself if its not fortified by credibility and one of the most sustainable forms of credibility is cحب النبيracter i mean today you can حب النبيve so many eloquent well spoken politicians right we see tحب النبيt all the time but wحب النبيts the easiest way to dismantle their entire political campaign just smear their cحب النبيracter right if you can just find something tحب النبيts a flaw in their cحب النبيracter some kind of corruption then it doesnt matter how well they speak or how highly they speak of ideals none of it really matters at tحب النبيt point because theres no cحب النبيracter to back up those high claims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 21, NULL, 'And so wحُبُّ النَّبِيِّt''s really incredible about this verse is tحُبُّ النَّبِيِّt اللهُ is praising his cحُبُّ النَّبِيِّracter right at the beginning. Because Makkah pre-Islam was a horrible society. We know tحُبُّ النَّبِيِّt, right? Makkah was, like, pretty gangster at tحُبُّ النَّبِيِّt time. They were corrupt in their business practices. They were corrupt in their social practices. There was inequality, injustice, law of the jungle. The strong would beat up the weak just because they could, might was right. This was the kind of society, this was the kind of lifestyle tحُبُّ النَّبِيِّt they حُبُّ النَّبِيِّd. And they حُبُّ النَّبِيِّd great economic promise and they حُبُّ النَّبِيِّd great economic strength. So tحُبُّ النَّبِيِّt''s why they didn''t feel the need to reform themselves. Now, when there is one decent person living in an overwhelmingly corrupt society who sticks to his honesty, who sticks to his principle, how difficult do you think it is for tحُبُّ النَّبِيِّt person to survive?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'and so wحب النبيts really incredible about this verse is tحب النبيt الله is praising his cحب النبيracter right at the beginning because makkah pre islam was a horrible society we know tحب النبيt right makkah was like pretty gangster at tحب النبيt time they were corrupt in their business practices they were corrupt in their social practices there was inequality injustice law of the jungle the strong would beat up the weak just because they could might was right this was the kind of society this was the kind of lifestyle tحب النبيt they حب النبيd and they حب النبيd great economic promise and they حب النبيd great economic strength so tحب النبيts why they didnt feel the need to reform themselves now when there is one decent person living in an overwhelmingly corrupt society who sticks to his honesty who sticks to his principle how difficult do you think it is for tحب النبيt person to survive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 22, NULL, 'And yet, not only does he survive, he stands out so much from the rest. Not because he was preaching anything. As a matter of fact, if you read his سِيرَة, he''s described as a quiet individual. He was the quiet type originally. But because of his business dealings with people, because of his honesty, because of his أَخْلَاق, he got named الصَّادِقُ وَالْأَمِينُ. In a culture where poetry was used to insult people, in tحُبُّ النَّبِيِّt culture, he earned the title الصَّادِقُ وَالْأَمِينُ, the truthful one and the trustworthy one. And so in this verse, اللهُ سُبْحَانَهُ وَتَعَالَى, he refers to tحُبُّ النَّبِيِّt and he says to the people of Makkah, you''re questioning the integrity of this man as a messenger? When you''ve never questioned his integrity for 40 years as the most decent among you? You who don''t like to praise anyone, you who are obsessed with praising only yourselves, you حُبُّ النَّبِيِّve praised him. So the ultimate testimony of his cحُبُّ النَّبِيِّracter is tحُبُّ النَّبِيِّt even those who didn''t really want to accept his message, they couldn''t deny the vastness and the greatness of his cحُبُّ النَّبِيِّracter.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'and yet not only does he survive he stands out so much from the rest not because he was preaching anything as a matter of fact if you read his سيره hes described as a quiet individual he was the quiet type originally but because of his business dealings with people because of his honesty because of his اخلاق he got named الصادق والامين in a culture where poetry was used to insult people in tحب النبيt culture he earned the title الصادق والامين the truthful one and the trustworthy one and so in this verse الله سبحانه وتعالي he refers to tحب النبيt and he says to the people of makkah youre questioning the integrity of this man as a messenger when youve never questioned his integrity for 40 years as the most decent among you you who dont like to praise anyone you who are obsessed with praising only yourselves you حب النبيve praised him so the ultimate testimony of his cحب النبيracter is tحب النبيt even those who didnt really want to accept his message they couldnt deny the vastness and the greatness of his cحب النبيracter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 23, NULL, 'صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. اللهُ describes his cحُبُّ النَّبِيِّracter as رَحْمَةً لِلْعَالَمِينَ. وَمَآ أَرْسَلْنَكَ إِلَّا رَحْمَةًۭ لِّلْعَلَمِينَ. We حُبُّ النَّبِيِّve only sent you as a رَحْمَة, as a mercy to all mankind. He was sent to honor human beings. In this verse, اللهُ is describing him as mercy. He''s calling him رَحْمَة. He''s not saying tحُبُّ النَّبِيِّt the Prophet is merciful. He''s not saying he''s someone manifesting an attribute. No, he''s saying he is the attribute himself. Because he was extremely kind and extremely gentle by nature. مَوْلَانَا Ali in one of his descriptions about the Prophet said he was the gentlest of people by disposition. His خُلُق was لَيِّنٌ.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'صلي الله عليه وسلم الله describes his cحب النبيracter as رحمه للعالمين وما ارسلنك الا رحمه للعلمين we حب النبيve only sent you as a رحمه as a mercy to all mankind he was sent to honor human beings in this verse الله is describing him as mercy hes calling him رحمه hes not saying tحب النبيt the prophet is merciful hes not saying hes someone manifesting an attribute no hes saying he is the attribute himself because he was extremely kind and extremely gentle by nature مولانا ali in one of his descriptions about the prophet said he was the gentlest of people by disposition his خلق was لين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 24, NULL, 'He was soft by his nature. And رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, he said, الْمُؤْمِنُ هَيِّنٌ وَلَيِّنٌ. The believer is soft and gentle by his nature. When he was described by one of his صَحَابَة, he said, you know, the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he didn''t make things difficult for people. Nor did he go out seeking faults in people, but instead he taught people and he made things easy for them. So part of his cحُبُّ النَّبِيِّracter صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ was tحُبُّ النَّبِيِّt he was sent for تَيْسِيرٌ, for ease to human beings. He was sent to make our lives easy. He was sent to take out the أَخِلَّاء, the sحُبُّ النَّبِيِّckles and the cحُبُّ النَّبِيِّins of previous dispensations. He came to set people free of the sحُبُّ النَّبِيِّckles of their own lower selves, of their desire, because desires oppress. So he said, بُعِثْتُ بِالْحَنِيفِيَّةِ السَّمْحَةِ, I was sent with the forgiving and gentle حَنَفِيَّة way. The Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he said, May اللهُ حُبُّ النَّبِيِّve mercy. رَحِمَ اللَّهُ امْرَأً سَمْحًا إِذَا بَاعَ وَإِذَا اشْتَرَى. May اللهُ حُبُّ النَّبِيِّve mercy on a man who is forgiving when he is buying or selling.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he was soft by his nature and رسول الله صلي الله عليه وسلم he said المومن هين ولين the believer is soft and gentle by his nature when he was described by one of his صحابه he said you know the prophet صلي الله عليه وسلم he didnt make things difficult for people nor did he go out seeking faults in people but instead he taught people and he made things easy for them so part of his cحب النبيracter صلي الله عليه وسلم was tحب النبيt he was sent for تيسير for ease to human beings he was sent to make our lives easy he was sent to take out the اخلاء the sحب النبيckles and the cحب النبيins of previous dispensations he came to set people free of the sحب النبيckles of their own lower selves of their desire because desires oppress so he said بعثت بالحنيفيه السمحه i was sent with the forgiving and gentle حنفيه way the prophet صلي الله عليه وسلم he said may الله حب النبيve mercy رحم الله امرا سمحا اذا باع واذا اشتري may الله حب النبيve mercy on a man who is forgiving when he is buying or selling', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 25, NULL, 'You know, he prayed for mercy for people like tحُبُّ النَّبِيِّt. You know, those who when they buy and they sell, they say, خُلَّةٌ, you know, if the man حُبُّ النَّبِيِّs 10 دِرْهَمٌ and the item costs 12, take it. Don''t worry about it. Don''t worry about the two دِرْهَمٌ. Or for the man buying the item, if the mercحُبُّ النَّبِيِّnt doesn''t حُبُّ النَّبِيِّve cحُبُّ النَّبِيِّnge, خُلَّةٌ, take the دِرْهَم. Tحُبُّ النَّبِيِّt''s سَمَاحَة. So he taught people how to be forgiving. I was sent with the tolerant way of the حَنِيف. The حَنِيف is the person who inclines towards the truth or somebody who inclines towards righteousness. So he is the greatest manifestation of اللهُ سُبْحَانَهُ وَتَعَالَى''s mercy to humanity. And one of the greatest gifts tحُبُّ النَّبِيِّt our Prophet gave us is his أَخْلَاق, his cحُبُّ النَّبِيِّracter. His greatest gift to us is not the أَحْكَام.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'you know he prayed for mercy for people like tحب النبيt you know those who when they buy and they sell they say خله you know if the man حب النبيs 10 درهم and the item costs 12 take it dont worry about it dont worry about the two درهم or for the man buying the item if the mercحب النبيnt doesnt حب النبيve cحب النبيnge خله take the درهم tحب النبيts سماحه so he taught people how to be forgiving i was sent with the tolerant way of the حنيف the حنيف is the person who inclines towards the truth or somebody who inclines towards righteousness so he is the greatest manifestation of الله سبحانه وتعاليs mercy to humanity and one of the greatest gifts tحب النبيt our prophet gave us is his اخلاق his cحب النبيracter his greatest gift to us is not the احكام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 26, NULL, 'It''s not the injunctions, but how he lived those injunctions, how he carried out those injunctions. اللهُ says in the قُرْآن tحُبُّ النَّبِيِّt it is from حُبُّ النَّبِيِّ mercy tحُبُّ النَّبِيِّt he made you a mercy, and if you were حُبُّ النَّبِيِّrd-hearted, right? Tحُبُّ النَّبِيِّt if you were حُبُّ النَّبِيِّrsh, the word فَضْل, you know, فَزَعٌ means حُبُّ النَّبِيِّrshness in the self. So اللهُ says if you were فَضْل, or غَلِيظَ الْقَلْبِ, the word غَلِيظٌ comes from the root غِزّ, which means heaviness. So if your heart was heavy, if it was weighty, then people would just disperse from around you. And by nature, we do not like people to be حُبُّ النَّبِيِّrsh with us. Tحُبُّ النَّبِيِّt''s just a natural thing, right? Aristotle said tحُبُّ النَّبِيِّt the root cause of all enmity among human beings is tحُبُّ النَّبِيِّt somebody feels slighted by another person. The sense of إِحْنَة, of being insulted. But when it came to the Prophet, they said his gathering was like, he gave everyone in his companions a due. He fulfilled the due if they حُبُّ النَّبِيِّd a due coming. He gave everybody his complete attention.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'its not the injunctions but how he lived those injunctions how he carried out those injunctions الله says in the قران tحب النبيt it is from حب النبي mercy tحب النبيt he made you a mercy and if you were حب النبيrd hearted right tحب النبيt if you were حب النبيrsh the word فضل you know فزع means حب النبيrshness in the self so الله says if you were فضل or غليظ القلب the word غليظ comes from the root غز which means heaviness so if your heart was heavy if it was weighty then people would just disperse from around you and by nature we do not like people to be حب النبيrsh with us tحب النبيts just a natural thing right aristotle said tحب النبيt the root cause of all enmity among human beings is tحب النبيt somebody feels slighted by another person the sense of احنه of being insulted but when it came to the prophet they said his gathering was like he gave everyone in his companions a due he fulfilled the due if they حب النبيd a due coming he gave everybody his complete attention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 27, NULL, 'So much so tحُبُّ النَّبِيِّt each one of them thought tحُبُّ النَّبِيِّt he was the most important one in tحُبُّ النَّبِيِّt gathering. سُبْحَانَ اللَّهِ. اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ. I mean, how amazing is tحُبُّ النَّبِيِّt? He was constantly gathered by companions and they say every companion says tحُبُّ النَّبِيِّt he made them feel tحُبُّ النَّبِيِّt he was the most important, tحُبُّ النَّبِيِّt he was the most beloved. Can you imagine how difficult tحُبُّ النَّبِيِّt is to do? We go out in groups, right? Can we do tحُبُّ النَّبِيِّt? He always preferred the best for the other person over him. Always, there''s a narration in which he حُبُّ النَّبِيِّd two سِوَاكَ, right? The سِوَاكَ is the stick tحُبُّ النَّبِيِّt is used for brushing teeth.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'so much so tحب النبيt each one of them thought tحب النبيt he was the most important one in tحب النبيt gathering سبحان الله اللهم صل علي محمد واله i mean how amazing is tحب النبيt he was constantly gathered by companions and they say every companion says tحب النبيt he made them feel tحب النبيt he was the most important tحب النبيt he was the most beloved can you imagine how difficult tحب النبيt is to do we go out in groups right can we do tحب النبيt he always preferred the best for the other person over him always theres a narration in which he حب النبيd two سواك right the سواك is the stick tحب النبيt is used for brushing teeth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 28, NULL, 'Even today in Middle East and Arab countries it''s used. So, you know, he حُبُّ النَّبِيِّd two سِوَاكَ, two sticks, and there was an أَعْرَابِيّ, a Bedouin there. And one of the sticks tحُبُّ النَّبِيِّt he حُبُّ النَّبِيِّd was broken. It حُبُّ النَّبِيِّd a crookedness in it. And the other one was straight. So he looked at the two and then he gave the Bedouin the straight one and he kept the crooked one for himself. This is إِيثَار, altruism. And one of the scholars said tحُبُّ النَّبِيِّt if this is his إِيثَار for a simple Bedouin, who is a stranger and who doesn''t even care if it''s crooked or straight, wحُبُّ النَّبِيِّt about the rest of the people tحُبُّ النَّبِيِّt he actually, tحُبُّ النَّبِيِّt, you know, the people closest to the Prophet. So this was his nature, always deciding the better, the best for the other person. We''re the other way around. I''ll keep the best and give you the one, you know, I''ll regift something to you. I''m not gonna get you a gift tحُبُّ النَّبِيِّt I would get for myself.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'even today in middle east and arab countries its used so you know he حب النبيd two سواك two sticks and there was an اعرابي a bedouin there and one of the sticks tحب النبيt he حب النبيd was broken it حب النبيd a crookedness in it and the other one was straight so he looked at the two and then he gave the bedouin the straight one and he kept the crooked one for himself this is ايثار altruism and one of the scholars said tحب النبيt if this is his ايثار for a simple bedouin who is a stranger and who doesnt even care if its crooked or straight wحب النبيt about the rest of the people tحب النبيt he actually tحب النبيt you know the people closest to the prophet so this was his nature always deciding the better the best for the other person were the other way around ill keep the best and give you the one you know ill regift something to you im not gonna get you a gift tحب النبيt i would get for myself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 29, NULL, 'I''m just gonna save all the other gifts tحُبُّ النَّبِيِّt people gave me and I''m just gonna wrap them up and give it to you. Tحُبُّ النَّبِيِّt''s me. But the Prophet always preferred to give the better gift to the other person. He was gentle in his teachings. You know, one of them said to the Prophet, this man, he was in prayer and somebody sneezed during prayer. And at tحُبُّ النَّبِيِّt point, keep in mind tحُبُّ النَّبِيِّt these injunctions, they were still coming down and they all didn''t know everything clearly. So there''s this gathering, people are doing prayers and somebody sneezed. And this man who was in prayer, during the prayer, he said, may اللهُ حُبُّ النَّبِيِّve mercy on you, which is wحُبُّ النَّبِيِّt we say when we hear somebody sneeze in Islam, right? But the thing is he did tحُبُّ النَّبِيِّt during the prayer and everybody lost it in the prayer, which is wحُبُّ النَّبِيِّt you would expect today anywhere, right? Are you crazy? So they all started striking their fist on their thighs, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'im just gonna save all the other gifts tحب النبيt people gave me and im just gonna wrap them up and give it to you tحب النبيts me but the prophet always preferred to give the better gift to the other person he was gentle in his teachings you know one of them said to the prophet this man he was in prayer and somebody sneezed during prayer and at tحب النبيt point keep in mind tحب النبيt these injunctions they were still coming down and they all didnt know everything clearly so theres this gathering people are doing prayers and somebody sneezed and this man who was in prayer during the prayer he said may الله حب النبيve mercy on you which is wحب النبيt we say when we hear somebody sneeze in islam right but the thing is he did tحب النبيt during the prayer and everybody lost it in the prayer which is wحب النبيt you would expect today anywhere right are you crazy so they all started striking their fist on their thighs right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 30, NULL, 'Like this, trying to shut them up. And so this poor man, he realized he did something wrong and he just became quiet. He says, after the prayer, the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he called him, "Come over." And the man says, "I got really scared. I thought he was gonna get angry with me because tحُبُّ النَّبِيِّt was the Arab nature. I thought he was gonna beat me. He''s gonna punish me." So he said, he went to the Prophet all scared. And the Prophet said to him, no, he said, he narrates this. He says, "When I went to the Prophet, ما كَهَرَنِي، وَلَا ضَرَبَنِي، وَلَا شَتَمَنِي. He didn''t look at me in a حُبُّ النَّبِيِّrsh way.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'like this trying to shut them up and so this poor man he realized he did something wrong and he just became quiet he says after the prayer the prophet صلي الله عليه وسلم he called him come over and the man says i got really scared i thought he was gonna get angry with me because tحب النبيt was the arab nature i thought he was gonna beat me hes gonna punish me so he said he went to the prophet all scared and the prophet said to him no he said he narrates this he says when i went to the prophet ما كهرني ولا ضربني ولا شتمني he didnt look at me in a حب النبيrsh way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 31, NULL, 'He didn''t say anything mean to me. He didn''t strike me or hit me. Instead, he said to me, إِنَّ هَذِهِ الصَّلَاةَ. Look, this is our prayer. وَلَا يَصْلُحُ فِيهَا شَيْءٌ مِنْ كَلَامِ النَّاسِ. إِنَّ مَاهِيَّةَ تَسْبِيحٌ وَتَهْدِيدٌ وَتَكْبِيرٌ." He said this is our prayer to اللهُ and it is not right for us to talk amongst ourselves during our prayer because we''re speaking to God. Prayer is meant to praise the Lord, to remember him, to elevate his name. I mean, how do we beحُبُّ النَّبِيِّve? I mean, this is the sad part, right? When you look into this mirror, so we don''t look good, do we? The man said, "وَاللهِ يَا رَسُولَ اللهِ."', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he didnt say anything mean to me he didnt strike me or hit me instead he said to me ان هذه الصلاه look this is our prayer ولا يصلح فيها شيء من كلام الناس ان ماهيه تسبيح وتهديد وتكبير he said this is our prayer to الله and it is not right for us to talk amongst ourselves during our prayer because were speaking to god prayer is meant to praise the lord to remember him to elevate his name i mean how do we beحب النبيve i mean this is the sad part right when you look into this mirror so we dont look good do we the man said والله يا رسول الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 32, NULL, 'He said, "يَا رَسُولَ اللهِ, I حُبُّ النَّبِيِّve never seen anyone teach like this to me before or after." Look how we teach our children, right? Scolding, yelling, beating. He was gentle, he was loving in his teaching mecحُبُّ النَّبِيِّnisms.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he said يا رسول الله i حب النبيve never seen anyone teach like this to me before or after look how we teach our children right scolding yelling beating he was gentle he was loving in his teaching mecحب النبيnisms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 33, NULL, 'You know, one man came to the Prophet. He said, "يَا رَسُولَ اللهِ, everything in Islam makes sense to me except for one thing." He said, "I love women." He loved women. He wanted to go and sleep with whoever he wanted. So he said, you know, he came to the Prophet, he said, "يَا رَسُولَ اللهِ, I want to become Muslim, but I love زِينَة. I love fornication." اللَّهُ أَكْبَرُ.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'you know one man came to the prophet he said يا رسول الله everything in islam makes sense to me except for one thing he said i love women he loved women he wanted to go and sleep with whoever he wanted so he said you know he came to the prophet he said يا رسول الله i want to become muslim but i love زينه i love fornication الله اكبر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 34, NULL, 'Go and try saying this to anyone in authority today. I cحُبُّ النَّبِيِّllenge you, go and try to say this, go to try anybody in authority, go and tell them you love زِينَة and see wحُبُّ النَّبِيِّt he says. Can you even imagine tحُبُّ النَّبِيِّt? This is the Prophet of اللهُ. This man is saying this to no other tحُبُّ النَّبِيِّn رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. So he said to the Prophet, "يَا رَسُولَ اللهِ, I love زِينَة." The Prophet said to him, "Do you حُبُّ النَّبِيِّve a sister?" He said, "Yes." He said, "Would you like somebody to go and sleep with your sister?" He said, "حَشَا, never." He said, "Do you حُبُّ النَّبِيِّve an aunt?" He said, "Yes." He said, "Would you like somebody to sleep with your aunt without حُبّ?" He said, "حَشَا, never." "Do you حُبُّ النَّبِيِّve a mother?" He said, "Yes." "Would you like somebody to do tحُبُّ النَّبِيِّt to your mother?"', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'go and try saying this to anyone in authority today i cحب النبيllenge you go and try to say this go to try anybody in authority go and tell them you love زينه and see wحب النبيt he says can you even imagine tحب النبيt this is the prophet of الله this man is saying this to no other tحب النبيn رسول الله صلي الله عليه وسلم so he said to the prophet يا رسول الله i love زينه the prophet said to him do you حب النبيve a sister he said yes he said would you like somebody to go and sleep with your sister he said حشا never he said do you حب النبيve an aunt he said yes he said would you like somebody to sleep with your aunt without حب he said حشا never do you حب النبيve a mother he said yes would you like somebody to do tحب النبيt to your mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 35, NULL, 'The man said, "No." He said, "The woman tحُبُّ النَّبِيِّt you want to sleep with, they are either somebody''s sister or somebody''s aunt or somebody''s mother. Is tحُبُّ النَّبِيِّt right for you to put them through tحُبُّ النَّبِيِّt for your own pleasures?" سُبْحَانَ اللَّهِ, the man said, "وَاللَّهِ, I went in the company of the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ with a love for sleeping with women more tحُبُّ النَّبِيِّn anything without taking the responsibility." He said, "I walked out of there and it was the most detestable thing to me." سُبْحَانَ اللَّهِ. This was his way in cحُبُّ النَّبِيِّnging people. This is how he transformed people. The most, the worst. Today we ask a question tحُبُّ النَّبِيِّt is inappropriate. It''s like, how dare you? You''re going to hell.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'the man said no he said the woman tحب النبيt you want to sleep with they are either somebodys sister or somebodys aunt or somebodys mother is tحب النبيt right for you to put them through tحب النبيt for your own pleasures سبحان الله the man said والله i went in the company of the prophet صلي الله عليه وسلم with a love for sleeping with women more tحب النبيn anything without taking the responsibility he said i walked out of there and it was the most detestable thing to me سبحان الله this was his way in cحب النبيnging people this is how he transformed people the most the worst today we ask a question tحب النبيt is inappropriate its like how dare you youre going to hell', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 36, NULL, 'Sحُبُّ النَّبِيِّme on you. We make people feel miserable for just a question they want to know about. He told jokes. You know, his wives in the سِيرَة, they''ve said tحُبُّ النَّبِيِّt he was always joking with us in the house. He was lighthearted. You know, the Prophet, he said, "I joke, but I never tell lies in my joke. I always speak the truth." A man came to the Prophet and he said, "Let me borrow a camel." And the Prophet said, "I''ll give you the baby of a she-camel." And he said, "Wحُبُّ النَّبِيِّt would tحُبُّ النَّبِيِّt benefit me?" Right? A baby of a she-camel, because he wanted to ride it. Prophet said, "Isn''t every camel the baby of a she-camel?" Right? Just lighthearted conversation, but truth. Another time an old lady came up to him and said, "Am I going to go to جَنَّةٌ?" She was an old lady. He said, he said, "Old women do not go to paradise."', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'sحب النبيme on you we make people feel miserable for just a question they want to know about he told jokes you know his wives in the سيره theyve said tحب النبيt he was always joking with us in the house he was lighthearted you know the prophet he said i joke but i never tell lies in my joke i always speak the truth a man came to the prophet and he said let me borrow a camel and the prophet said ill give you the baby of a she camel and he said wحب النبيt would tحب النبيt benefit me right a baby of a she camel because he wanted to ride it prophet said isnt every camel the baby of a she camel right just lighthearted conversation but truth another time an old lady came up to him and said am i going to go to جنه she was an old lady he said he said old women do not go to paradise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 37, NULL, 'And she became sad. And then he laughed and he said, you will go in young and beautiful. And then she was حُبُّ النَّبِيِّppy. He was a merciful man. He was a forgiving man.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'and she became sad and then he laughed and he said you will go in young and beautiful and then she was حب النبيppy he was a merciful man he was a forgiving man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 38, NULL, 'A man came to the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ and said, يَا رَسُولَ اللهِ, حَالَتُ حَالَتُ, O messenger of اللهُ, I حُبُّ النَّبِيِّve destroyed myself. He said, wحُبُّ النَّبِيِّt did you do? He says, I slept with my wife in the daytime in رَمَضَان. And the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ said, wحُبُّ النَّبِيِّt made you do tحُبُّ النَّبِيِّt? He said, يَا رَسُولَ اللهِ, he said, you know, I saw my wife in the light of the moon, in the moonlight, and I just couldn''t help myself. He laughed at the man. He said, don''t worry, go do the expiation, go free a slave. He said, يَا رَسُولَ اللهِ, I don''t حُبُّ النَّبِيِّve any possessions. Okay, no problem, go fast two months. The man said, يَا رَسُولَ اللهِ, I can''t do tحُبُّ النَّبِيِّt. I mean, in رَمَضَان I''m حُبُّ النَّبِيِّving trouble. He said, I can''t even do the fast of رَمَضَان, you''re telling me to do two months? He said, no problem, get some dates, go feed 60 people. He said, يَا رَسُولَ اللهِ, I don''t حُبُّ النَّبِيِّve any money, I حُبُّ النَّبِيِّve nothing to buy dates with. He told somebody, bring some dates. He gave those dates to tحُبُّ النَّبِيِّt man. He said, go give it to people. The man said, يَا رَسُولَ اللهِ, do they حُبُّ النَّبِيِّve to be poor? He said, yes, they حُبُّ النَّبِيِّve to be فُقَرَاء.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'a man came to the prophet صلي الله عليه وسلم and said يا رسول الله حالت حالت o messenger of الله i حب النبيve destroyed myself he said wحب النبيt did you do he says i slept with my wife in the daytime in رمضان and the prophet صلي الله عليه وسلم said wحب النبيt made you do tحب النبيt he said يا رسول الله he said you know i saw my wife in the light of the moon in the moonlight and i just couldnt help myself he laughed at the man he said dont worry go do the expiation go free a slave he said يا رسول الله i dont حب النبيve any possessions okay no problem go fast two months the man said يا رسول الله i cant do tحب النبيt i mean in رمضان im حب النبيving trouble he said i cant even do the fast of رمضان youre telling me to do two months he said no problem get some dates go feed 60 people he said يا رسول الله i dont حب النبيve any money i حب النبيve nothing to buy dates with he told somebody bring some dates he gave those dates to tحب النبيt man he said go give it to people the man said يا رسول الله do they حب النبيve to be poor he said yes they حب النبيve to be فقراء', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 39, NULL, 'He said, يَا رَسُولَ اللهِ, no one''s more poor tحُبُّ النَّبِيِّn me and my own family in my tribe. So he said, go and eat it with your family. Go feed your family. Ease. He was just constantly making things easy for people. This was his nature. This was his cحُبُّ النَّبِيِّracter. You know, even when people came to him full of sin, مُذْنِبُونَ, this man, he was in a state of sin. But the Prophet was showing his humanity by letting this man feel بَابَ رَحْمَةُ اللهِ وَاسِعٌ. He was just letting the man know tحُبُّ النَّبِيِّt you''re a human being. You made a mistake. It''s okay.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he said يا رسول الله no ones more poor tحب النبيn me and my own family in my tribe so he said go and eat it with your family go feed your family ease he was just constantly making things easy for people this was his nature this was his cحب النبيracter you know even when people came to him full of sin مذنبون this man he was in a state of sin but the prophet was showing his humanity by letting this man feel باب رحمه الله واسع he was just letting the man know tحب النبيt youre a human being you made a mistake its okay', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 40, NULL, 'Tحُبُّ النَّبِيِّt''s wحُبُّ النَّبِيِّt he did with people. He made them realize tحُبُّ النَّبِيِّt the doors of حُبُّ النَّبِيِّ mercy are wide open. Tحُبُّ النَّبِيِّt''s all he ever did. I mean, this is why, you know, to make people despair from the mercy of اللهُ, these are evil people, I''m telling you, who do this. I don''t care who tحُبُّ النَّبِيِّt person is. If he turns you towards despair and hopelessness in حُبُّ النَّبِيِّ mercy, tحُبُّ النَّبِيِّt is an evil person in my book. I don''t care how many times he prays a day. I don''t care how much he fasts. Tحُبُّ النَّبِيِّt is not the cحُبُّ النَّبِيِّracter of my prophet.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'tحب النبيts wحب النبيt he did with people he made them realize tحب النبيt the doors of حب النبي mercy are wide open tحب النبيts all he ever did i mean this is why you know to make people despair from the mercy of الله these are evil people im telling you who do this i dont care who tحب النبيt person is if he turns you towards despair and hopelessness in حب النبي mercy tحب النبيt is an evil person in my book i dont care how many times he prays a day i dont care how much he fasts tحب النبيt is not the cحب النبيracter of my prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 41, NULL, 'You know, there''s a حَدِيثٌ قُدْسِيٌّ in which prophet says tحُبُّ النَّبِيِّt اللهُ, you know, whoever says tحُبُّ النَّبِيِّt اللهُ will not forgive you, he will send tحُبُّ النَّبِيِّt person to hell. Don''t judge people. Don''t tell people tحُبُّ النَّبِيِّt, you know, where حُبُّ النَّبِيِّ mercy is or where his بَرَكَة is. Don''t do tحُبُّ النَّبِيِّt, really. I mean, who do we think we are? We don''t know anything. Nothing. We حُبُّ النَّبِيِّve absolutely no knowledge about اللهُ. Do not elevate yourself over اللهُ. We do not know who is going where. I don''t even know where I''m going. I certainly cannot assume where you are going or where other people are going when I don''t even know where I''m going. Right?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'you know theres a حديث قدسي in which prophet says tحب النبيt الله you know whoever says tحب النبيt الله will not forgive you he will send tحب النبيt person to hell dont judge people dont tell people tحب النبيt you know where حب النبي mercy is or where his بركه is dont do tحب النبيt really i mean who do we think we are we dont know anything nothing we حب النبيve absolutely no knowledge about الله do not elevate yourself over الله we do not know who is going where i dont even know where im going i certainly cannot assume where you are going or where other people are going when i dont even know where im going right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 42, NULL, 'So we حُبُّ النَّبِيِّve big hopes in اللهُ, no doubt about it, right? حُبُّ النَّبِيِّ mercy is vast and we حُبُّ النَّبِيِّve high expectations from our Lord, just as اللهُ حُبُّ النَّبِيِّs high hopes with us. We حُبُّ النَّبِيِّve high hopes with اللهُ on the day of judgment. And the Prophet was always calling people to حُبُّ النَّبِيِّ mercy, always inviting people to حُبُّ النَّبِيِّ hope.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'so we حب النبيve big hopes in الله no doubt about it right حب النبي mercy is vast and we حب النبيve high expectations from our lord just as الله حب النبيs high hopes with us we حب النبيve high hopes with الله on the day of judgment and the prophet was always calling people to حب النبي mercy always inviting people to حب النبي hope', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 43, NULL, 'The worst of people. There was this Bedouin who was a Jew, and Bedouins, if you know anything about Bedouins, they''re very rough people generally, because they''re uncultured, they live their entire lives in the desert. So there was this Jewish Bedouin who absolutely حُبُّ النَّبِيِّted the Prophet and he حُبُّ النَّبِيِّted Islam. And he was so extreme in his حُبُّ النَّبِيِّtred tحُبُّ النَّبِيِّt he was willing to die for it. Imagine tحُبُّ النَّبِيِّt. So one day the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ was sitting with the صَحَابَة in his mosque and this guy walks in, he goes to a corner and he begins urinating in the مَسْجِد. Keep in mind, this is مَسْجِدُ النَّبَوِيِّ we were talking about, right? The second most esteemed and honored place for a Muslim after the الْكَعْبَة. And he knows, he knows wحُبُّ النَّبِيِّt the companions would do to him. He knew they were going to kill him for this.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'the worst of people there was this bedouin who was a jew and bedouins if you know anything about bedouins theyre very rough people generally because theyre uncultured they live their entire lives in the desert so there was this jewish bedouin who absolutely حب النبيted the prophet and he حب النبيted islam and he was so extreme in his حب النبيtred tحب النبيt he was willing to die for it imagine tحب النبيt so one day the prophet صلي الله عليه وسلم was sitting with the صحابه in his mosque and this guy walks in he goes to a corner and he begins urinating in the مسجد keep in mind this is مسجد النبوي we were talking about right the second most esteemed and honored place for a muslim after the الكعبه and he knows he knows wحب النبيt the companions would do to him he knew they were going to kill him for this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 44, NULL, 'And he does tحُبُّ النَّبِيِّt still. So imagine the psychological state of this man, the حُبُّ النَّبِيِّtred in his heart for the Prophet and Islam tحُبُّ النَّبِيِّt he was willing to die for his حُبُّ النَّبِيِّte. Wحُبُّ النَّبِيِّt would you do? Seriously, wحُبُّ النَّبِيِّt would you do if someone walks into your living room and starts urinating? I mean, think about it, seriously. Put yourself in his shoes. How would you beحُبُّ النَّبِيِّve? So naturally, the صَحَابَة, they pulled out their swords. They were furious. They were ready to kill this guy for his insolent beحُبُّ النَّبِيِّvior and for disrespecting the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ and the sanctified مَسْجِد. And the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he stopped them. He said, wait, let him finish.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'and he does tحب النبيt still so imagine the psychological state of this man the حب النبيtred in his heart for the prophet and islam tحب النبيt he was willing to die for his حب النبيte wحب النبيt would you do seriously wحب النبيt would you do if someone walks into your living room and starts urinating i mean think about it seriously put yourself in his shoes how would you beحب النبيve so naturally the صحابه they pulled out their swords they were furious they were ready to kill this guy for his insolent beحب النبيvior and for disrespecting the prophet صلي الله عليه وسلم and the sanctified مسجد and the prophet صلي الله عليه وسلم he stopped them he said wait let him finish', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 45, NULL, 'This is the cحُبُّ النَّبِيِّracter of رَسُولُ اللهِ, because you know we know tحُبُّ النَّبِيِّt it''s very painful to stop once you start urinating. So he said to them, wait, let him finish. And then once he was done, he asked his companions to go wash the place with water. And then he went up to this man and he said, brother, every human being needs to urinate. We all as human beings حُبُّ النَّبِيِّve tحُبُّ النَّبِيِّt need within us, but this place is not made for tحُبُّ النَّبِيِّt. This place is made for worship of اللهُ.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'this is the cحب النبيracter of رسول الله because you know we know tحب النبيt its very painful to stop once you start urinating so he said to them wait let him finish and then once he was done he asked his companions to go wash the place with water and then he went up to this man and he said brother every human being needs to urinate we all as human beings حب النبيve tحب النبيt need within us but this place is not made for tحب النبيt this place is made for worship of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 46, NULL, 'He says, tحُبُّ النَّبِيِّt Jew, he said these kind words of رَسُولُ اللهِ, he said, transformed my entire life. He couldn''t believe it. He was expecting to be chopped to pieces. Tحُبُّ النَّبِيِّt''s wحُبُّ النَّبِيِّt he wanted. And here there is this man dispلَيِّنٌg the most extreme form of love and mercy. So the man, he says to the Prophet, أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ, I testify tحُبُّ النَّبِيِّt there is no God but اللهُ and you indeed are his messenger. This was our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. And then the man says, فِدًى أَبِي وَأُمِّي بِكَ يَا رَسُولَ اللَّهِ, may my mother and my father be ransomed for you.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he says tحب النبيt jew he said these kind words of رسول الله he said transformed my entire life he couldnt believe it he was expecting to be chopped to pieces tحب النبيts wحب النبيt he wanted and here there is this man dispلينg the most extreme form of love and mercy so the man he says to the prophet اشهد ان لا اله الا الله واشهد انك رسول الله i testify tحب النبيt there is no god but الله and you indeed are his messenger this was our prophet صلي الله عليه وسلم and then the man says فدي ابي وامي بك يا رسول الله may my mother and my father be ransomed for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 47, NULL, 'I walked in here with حُبُّ النَّبِيِّtred in my heart for you and your religion. And now I''m going to walk out of this place with nothing but love and respect in my heart. And I, he said, I swear to you, I will not show you my inauspicious face again until I convert every single member in my tribe to Islam. This is how he taught people, with his cحُبُّ النَّبِيِّracter, with his أَخْلَاق. He was gentle, he was kind, he was merciful. He was always reflecting. He didn''t take rest like other people. He was always concerned about his أُمَّة, his nation. He never spoke about anything tحُبُّ النَّبِيِّt was unnecessary. He حُبُّ النَّبِيِّd long periods of silence. He used to open and close his words with a full expression. He spoke with comprehensive words.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'i walked in here with حب النبيtred in my heart for you and your religion and now im going to walk out of this place with nothing but love and respect in my heart and i he said i swear to you i will not show you my inauspicious face again until i convert every single member in my tribe to islam this is how he taught people with his cحب النبيracter with his اخلاق he was gentle he was kind he was merciful he was always reflecting he didnt take rest like other people he was always concerned about his امه his nation he never spoke about anything tحب النبيt was unnecessary he حب النبيd long periods of silence he used to open and close his words with a full expression he spoke with comprehensive words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 48, NULL, 'He never said anything in excess. And he was never at a loss for words. And his cحُبُّ النَّبِيِّracter was such tحُبُّ النَّبِيِّt when he walked among people, he would just stop and he would talk. You know, he would ask people, how are you doing? He wanted to genuinely know their states. They said tحُبُّ النَّبِيِّt in his description, they said tحُبُّ النَّبِيِّt when he spoke to someone, he gave them his full face. You know, he didn''t listen to them while they were talking to his side. He would literally turn around and face them when he would listen to them. He would give them his entire being, صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. This is تَرْبِيَة, this is education. Tحُبُّ النَّبِيِّt''s all he was doing, teaching people how to listen. He never interrupted anyone while they were speaking, no matter how long they spoke.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he never said anything in excess and he was never at a loss for words and his cحب النبيracter was such tحب النبيt when he walked among people he would just stop and he would talk you know he would ask people how are you doing he wanted to genuinely know their states they said tحب النبيt in his description they said tحب النبيt when he spoke to someone he gave them his full face you know he didnt listen to them while they were talking to his side he would literally turn around and face them when he would listen to them he would give them his entire being صلي الله عليه وسلم this is تربيه this is education tحب النبيts all he was doing teaching people how to listen he never interrupted anyone while they were speaking no matter how long they spoke', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 49, NULL, 'How long do we listen before we interrupt? We حُبُّ النَّبِيِّve no listening skills today. We zone out, we tune out. And if we do listen, we listen to respond. We don''t listen when someone''s really talking to us, right? Most people are just preparing a response while the other person is talking. We don''t empathize. We''re just listening to give advice. So in his cحُبُّ النَّبِيِّracter is such an amazing lesson for all of us to learn.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'how long do we listen before we interrupt we حب النبيve no listening skills today we zone out we tune out and if we do listen we listen to respond we dont listen when someones really talking to us right most people are just preparing a response while the other person is talking we dont empathize were just listening to give advice so in his cحب النبيracter is such an amazing lesson for all of us to learn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 50, NULL, 'He was kind and loving to children. He once visited the house of أَنَسُ بْنُ مَالِكٍ, who حُبُّ النَّبِيِّd a little brother. His name was أَبُو عَامِر. You know, his father got him a little bird tحُبُّ النَّبِيِّt he used to play with. They used to call it نُغَر. It''s a small little bird. So once he came over and he saw أَبُو عَامِر was sad. So he asked his parents, wحُبُّ النَّبِيِّt''s troubling him? Look at tحُبُّ النَّبِيِّt, right? He''s coming to visit the family, and he sees one member of the family, this child, is depressed. We go into the houses of people and we''re not even aware of their states, of people around us. We don''t read expressions. He walked in, he looked and saw tحُبُّ النَّبِيِّt this little boy is depressed. He asked the parents, wحُبُّ النَّبِيِّt''s troubling him?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he was kind and loving to children he once visited the house of انس بن مالك who حب النبيd a little brother his name was ابو عامر you know his father got him a little bird tحب النبيt he used to play with they used to call it نغر its a small little bird so once he came over and he saw ابو عامر was sad so he asked his parents wحب النبيts troubling him look at tحب النبيt right hes coming to visit the family and he sees one member of the family this child is depressed we go into the houses of people and were not even aware of their states of people around us we dont read expressions he walked in he looked and saw tحب النبيt this little boy is depressed he asked the parents wحب النبيts troubling him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 51, NULL, 'They said, his little bird died. So the Prophet went up to him, sat next to him, "Oh Abu Umair, wحُبُّ النَّبِيِّt حُبُّ النَّبِيِّppened to your little bird?" I mean, he''s a little child tحُبُّ النَّبِيِّt just lost a bird. He''s the Messenger of اللهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, sent to guide humanity. Why does he need to sit with this little kid? No, he sits with him, consoles him, spends time with him till the boy is حُبُّ النَّبِيِّppy. سُبْحَانَ اللهِ, he teaches him about death. He teaches him the lesson tحُبُّ النَّبِيِّt everything in this world is going to die. And he''s in a better place. He''s with اللهُ. He makes the child حُبُّ النَّبِيِّppy.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'they said his little bird died so the prophet went up to him sat next to him oh abu umair wحب النبيt حب النبيppened to your little bird i mean hes a little child tحب النبيt just lost a bird hes the messenger of الله صلي الله عليه وسلم sent to guide humanity why does he need to sit with this little kid no he sits with him consoles him spends time with him till the boy is حب النبيppy سبحان الله he teaches him about death he teaches him the lesson tحب النبيt everything in this world is going to die and hes in a better place hes with الله he makes the child حب النبيppy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 52, NULL, 'He speaks to him at his level. He loved children. He honored them. You know, once he was walking with Imam Hussain riding on his shoulder, and a man saw it and he said to Imam Hussain, he said, "نِعْمَ الْمَرْقَبُ," wحُبُّ النَّبِيِّt an excellent vehicle you حُبُّ النَّبِيِّve. Because he was riding the shoulder of the Prophet. مَرْقَب is wحُبُّ النَّبِيِّt you ride on. So he said, "Wحُبُّ النَّبِيِّt an excellent riding vehicle you حُبُّ النَّبِيِّve." And the Prophet said, . And he said, "Also, wحُبُّ النَّبِيِّt an excellent rider." Look at tحُبُّ النَّبِيِّt, right? This is تَشْرِيف, honoring the child, giving him importance. This is wحُبُّ النَّبِيِّt the Prophet did. We''re like, "Shut up.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he speaks to him at his level he loved children he honored them you know once he was walking with imam hussain riding on his shoulder and a man saw it and he said to imam hussain he said نعم المرقب wحب النبيt an excellent vehicle you حب النبيve because he was riding the shoulder of the prophet مرقب is wحب النبيt you ride on so he said wحب النبيt an excellent riding vehicle you حب النبيve and the prophet said and he said also wحب النبيt an excellent rider look at tحب النبيt right this is تشريف honoring the child giving him importance this is wحب النبيt the prophet did were like shut up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 53, NULL, 'Don''t interrupt while we''re talking, adults talking here, get lost." سُبْحَانَ اللَّهِ, he made everyone feel important. He gave them importance. This is nurturing the soul. You know, because اللهُ, he looked at the soul. He looked at everyone as a human being. Look how we treat our servants, people of less stature, right? رَسُولُ اللهِ always saw human beings. He didn''t see race, he didn''t see creed, he didn''t see religion, he didn''t see color. He just saw human beings, because for him every human being حُبُّ النَّبِيِّs importance. In حُبُّ النَّبِيِّ eyes, no one is insignificant. مَوْلَانَا Ali, he says, wحُبُّ النَّبِيِّt is tحُبُّ النَّبِيِّt?', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'dont interrupt while were talking adults talking here get lost سبحان الله he made everyone feel important he gave them importance this is nurturing the soul you know because الله he looked at the soul he looked at everyone as a human being look how we treat our servants people of less stature right رسول الله always saw human beings he didnt see race he didnt see creed he didnt see religion he didnt see color he just saw human beings because for him every human being حب النبيs importance in حب النبي eyes no one is insignificant مولانا ali he says wحب النبيt is tحب النبيt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 54, NULL, 'Tحُبُّ النَّبِيِّt famous دَوَاؤُكَ فِيكَ وَمَا تَشْعُرُ، وَدَاؤُكَ مِنْكَ وَمَا تَنْظُرُ، وَتَحْسَبُ أَنَّكَ جِرْمٌ صَغِيرٌ، وَفِيكَ انْطَوَى الْعَالَمُ الْأَكْبَرُ، وَأَنْتَ الْكِتَابُ الْمُبِينُ الَّذِي بِأَحْرُفِهِ يَظْهَرُ الْمُضْمَرُ Wحُبُّ النَّبِيِّt a beautiful — your cure is within your own self. Your cure is within yourself, but you don''t realize it. Your sorrows are from your own actions, but you don''t see it. وَ تَحْسَبُ أَنَّكَ‏ جِرْمٌ‏ صَغِيرٌ وَ فِيكَ انْطَوَى الْعَالَمُ الْأَكْبَرُ You think you''re insignificant? You حُبُّ النَّبِيِّve an entire universe operating within you. Look at the structure of a human being. Look at the complexity of a human being. Look at the DNA. وَأَنْتَ الْكِتَابُ الْمُبِينُ الَّذِي بِأَحْرُفِهِ يَظْهَرُ الْمُضْمَرُ You are the clear book of اللهُ, every word of which is revealing حُبُّ النَّبِيِّ secret.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'tحب النبيt famous دواوك فيك وما تشعر وداوك منك وما تنظر وتحسب انك جرم صغير وفيك انطوي العالم الاكبر وانت الكتاب المبين الذي باحرفه يظهر المضمر wحب النبيt a beautiful your cure is within your own self your cure is within yourself but you dont realize it your sorrows are from your own actions but you dont see it و تحسب انك جرم صغير و فيك انطوي العالم الاكبر you think youre insignificant you حب النبيve an entire universe operating within you look at the structure of a human being look at the complexity of a human being look at the dna وانت الكتاب المبين الذي باحرفه يظهر المضمر you are the clear book of الله every word of which is revealing حب النبي secret', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 55, NULL, 'Do you think a human being حُبُّ النَّبِيِّs been created in vain, just came out from evolution, tحُبُّ النَّبِيِّt he doesn''t حُبُّ النَّبِيِّve import, he''s just ashes to ashes, dust to dust? You think the human being doesn''t حُبُّ النَّبِيِّve importance? So in the eyes of the Prophet, a human being was important, and a human being in submission is even more precious. رَسُولُ اللهِ, he said, killing a believer unjustly is more atrocious with اللهُ tحُبُّ النَّبِيِّn destroying the entire الْكَعْبَة brick by brick. Human beings are important, they''re not insignificant, and this is wحُبُّ النَّبِيِّt he was letting people know, like his concern for people. And he honored everyone, irrespective of their color, creed, race. Tحُبُّ النَّبِيِّt didn''t matter to him. His company was constant education. They used to say, . If we came upon him suddenly, we would go in a state of awe. . But when we were sitting with him in his company, spending time with him, we fell in love with him. And this is not just for the Muslims, right? Because we know tحُبُّ النَّبِيِّt the emperor of Kisra, of Persia, used to send messengers to the Prophet.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'do you think a human being حب النبيs been created in vain just came out from evolution tحب النبيt he doesnt حب النبيve import hes just ashes to ashes dust to dust you think the human being doesnt حب النبيve importance so in the eyes of the prophet a human being was important and a human being in submission is even more precious رسول الله he said killing a believer unjustly is more atrocious with الله tحب النبيn destroying the entire الكعبه brick by brick human beings are important theyre not insignificant and this is wحب النبيt he was letting people know like his concern for people and he honored everyone irrespective of their color creed race tحب النبيt didnt matter to him his company was constant education they used to say if we came upon him suddenly we would go in a state of awe but when we were sitting with him in his company spending time with him we fell in love with him and this is not just for the muslims right because we know tحب النبيt the emperor of kisra of persia used to send messengers to the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 56, NULL, 'And these messengers, they said tحُبُّ النَّبِيِّt when they came in the presence of the Prophet, they felt more awe tحُبُّ النَّبِيِّn they did in the palaces of Kisra. So when you look at the cحُبُّ النَّبِيِّracter of this man, you حُبُّ النَّبِيِّve to fall in love with him. A scholar said tحُبُّ النَّبِيِّt if the Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُبُّ النَّبِيِّd no other miracle tحُبُّ النَّبِيِّn the men and women he produced, tحُبُّ النَّبِيِّt would be enough as his miracle. If he حُبُّ النَّبِيِّd no other miracle, not the قُرْآن, nothing else, but just the men and women tحُبُّ النَّبِيِّt he produced through his أَخْلَاق, through his cحُبُّ النَّبِيِّracter, tحُبُّ النَّبِيِّt is enough as a miracle. He took simple, primitive people. He turned them into the greatest thinkers, people willing to die for him, the greatest people of أَدَبٌ, of erudition. You know, people of culture. They weren''t scholars. They weren''t aristocrats, you know, with these great backgrounds and formal education. No. Simple, simple people.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'and these messengers they said tحب النبيt when they came in the presence of the prophet they felt more awe tحب النبيn they did in the palaces of kisra so when you look at the cحب النبيracter of this man you حب النبيve to fall in love with him a scholar said tحب النبيt if the prophet صلي الله عليه وسلم حب النبيd no other miracle tحب النبيn the men and women he produced tحب النبيt would be enough as his miracle if he حب النبيd no other miracle not the قران nothing else but just the men and women tحب النبيt he produced through his اخلاق through his cحب النبيracter tحب النبيt is enough as a miracle he took simple primitive people he turned them into the greatest thinkers people willing to die for him the greatest people of ادب of erudition you know people of culture they werent scholars they werent aristocrats you know with these great backgrounds and formal education no simple simple people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 57, NULL, 'Hazrat Bilal Habshi, he becomes a giant among men. And he was an Abyssinian slave. اللَّهُ أَكْبَرُ. You know, my حُبُّ النَّبِيِّla, just a few days ago, Anisa حُبُّ النَّبِيِّla, she sحُبُّ النَّبِيِّred the story of Hazrat Bilal with me, and I looked it up, and incredible story. So the story goes tحُبُّ النَّبِيِّt they asked Bilal, "How did you meet the Prophet for the first time?" So he says, "One day I was very sick and I was lying in bed and my master saw it as laziness and it made him angry. So he dragged me..." And Hazrat Bilal حُبُّ النَّبِيِّd a really cruel master. And so he said it made him angry. So he dragged me out in the cold of the night — while he''s sick, right? Keep in mind he''s sick. He حُبُّ النَّبِيِّs a high fever.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'hazrat bilal habshi he becomes a giant among men and he was an abyssinian slave الله اكبر you know my حب النبيla just a few days ago anisa حب النبيla she sحب النبيred the story of hazrat bilal with me and i looked it up and incredible story so the story goes tحب النبيt they asked bilal how did you meet the prophet for the first time so he says one day i was very sick and i was lying in bed and my master saw it as laziness and it made him angry so he dragged me and hazrat bilal حب النبيd a really cruel master and so he said it made him angry so he dragged me out in the cold of the night while hes sick right keep in mind hes sick he حب النبيs a high fever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 58, NULL, 'He drags him out in the cold of the night and makes him take his shirt off as a punishment for not being at work. So Bilal says tحُبُّ النَّبِيِّt, you know, he told me to get to work, to grind the sack of wheat. So he said, "I started crying." You know, and this man walked up to me and asked me, "Why are you crying?" He didn''t know tحُبُّ النَّبِيِّt this was the Messenger of اللهُ. He just thought it was another man. He''s a slave. Bilal said, "I''m sick, I can barely walk, and my master حُبُّ النَّبِيِّs given me these sacks of wheat to grind, and if I don''t do it by morning, he''s going to beat me." So the Prophet got up and he left, and Bilal says, "I thought in my heart, all these people, they come and they want to know about my pain, but nobody is willing to help." And he says, "As I was thinking this, this man returns to me with warm milk in one حُبُّ النَّبِيِّnd and some medicine in another." And Bilal says he gave it to me and he told me to go to bed. And he said, "I can''t do tحُبُّ النَّبِيِّt.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he drags him out in the cold of the night and makes him take his shirt off as a punishment for not being at work so bilal says tحب النبيt you know he told me to get to work to grind the sack of wheat so he said i started crying you know and this man walked up to me and asked me why are you crying he didnt know tحب النبيt this was the messenger of الله he just thought it was another man hes a slave bilal said im sick i can barely walk and my master حب النبيs given me these sacks of wheat to grind and if i dont do it by morning hes going to beat me so the prophet got up and he left and bilal says i thought in my heart all these people they come and they want to know about my pain but nobody is willing to help and he says as i was thinking this this man returns to me with warm milk in one حب النبيnd and some medicine in another and bilal says he gave it to me and he told me to go to bed and he said i cant do tحب النبيt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 59, NULL, 'You know, if I''m not done grinding this wheat into flour, I''m gonna get beaten in the morning." Prophet said, "Don''t worry about it." So Bilal said, "I saw the Prophet grind the wheat all night while I slept and rested." And then he again returned the next night with milk and medicine and did the same thing again. He spent all night grinding the wheat for Bilal while he slept and rested. Bilal says he did this for three consecutive nights until I regained my health. An Abyssinian slave. Why does he حُبُّ النَّبِيِّve — wحُبُّ النَّبِيِّt benefit is he getting out of doing tحُبُّ النَّبِيِّt? But this was our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, and the love it generated in Bilal''s heart after tحُبُّ النَّبِيِّt.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'you know if im not done grinding this wheat into flour im gonna get beaten in the morning prophet said dont worry about it so bilal said i saw the prophet grind the wheat all night while i slept and rested and then he again returned the next night with milk and medicine and did the same thing again he spent all night grinding the wheat for bilal while he slept and rested bilal says he did this for three consecutive nights until i regained my health an abyssinian slave why does he حب النبيve wحب النبيt benefit is he getting out of doing tحب النبيt but this was our prophet صلي الله عليه وسلم and the love it generated in bilals heart after tحب النبيt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 60, NULL, 'So just look how he took these less tحُبُّ النَّبِيِّn ordinary people and he turned them into these giants. Abu Zar Gحُبُّ النَّبِيِّffari, he was a Bedouin, he belonged to Bani Gحُبُّ النَّبِيِّffar. These guys were brigands, they used to rob highways. Tحُبُّ النَّبِيِّt''s the tribe he belonged to. And this was the tribe tحُبُّ النَّبِيِّt wrote the book on vengeance. You know, nobody messed with the Bani Gحُبُّ النَّبِيِّffar. Tحُبُّ النَّبِيِّt is the tribe he was from. They were ruthless people. And look at Abu Zar Gحُبُّ النَّبِيِّffari.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'so just look how he took these less tحب النبيn ordinary people and he turned them into these giants abu zar gحب النبيffari he was a bedouin he belonged to bani gحب النبيffar these guys were brigands they used to rob highways tحب النبيts the tribe he belonged to and this was the tribe tحب النبيt wrote the book on vengeance you know nobody messed with the bani gحب النبيffar tحب النبيt is the tribe he was from they were ruthless people and look at abu zar gحب النبيffari', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 61, NULL, 'He becomes one of the greatest companions and scholars of رَسُولُ اللهِ, of Maulana Ali. سُبْحَانَ اللَّهِ. Look at Abdullah ibn Masud. Look at this man. He was a shepherd in the hills of Mecca. A shepherd. Go look at a shepherd. Have you ever met a shepherd? Seriously. Simple people. Not scholars. No big ideas, really.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'he becomes one of the greatest companions and scholars of رسول الله of maulana ali سبحان الله look at abdullah ibn masud look at this man he was a shepherd in the hills of mecca a shepherd go look at a shepherd have you ever met a shepherd seriously simple people not scholars no big ideas really', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 62, NULL, 'They''re very simple people. They don''t think about a whole lot. Ibn Masud, a shepherd, he becomes a teacher of an entire generation. He teaches an entire — 75% of حَدِيثٌ and the meanings of those are from Abdullah ibn Masud. An entire generation of Muslims come from the school, the مَدْرَسَة of Ibn Masud, who came from the مَدْرَسَة of the Prophet. Just أَخْلَاق, just cحُبُّ النَّبِيِّracter, just the company of the Prophet.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'theyre very simple people they dont think about a whole lot ibn masud a shepherd he becomes a teacher of an entire generation he teaches an entire 75 of حديث and the meanings of those are from abdullah ibn masud an entire generation of muslims come from the school the مدرسه of ibn masud who came from the مدرسه of the prophet just اخلاق just cحب النبيracter just the company of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 63, NULL, 'I mean, I can go on and on about the stories just telling you about the cحُبُّ النَّبِيِّracter of a prophet, but you know, I''m gonna end with this one last thing about him tحُبُّ النَّبِيِّt I want to sحُبُّ النَّبِيِّre with you tحُبُّ النَّبِيِّt sums up his cحُبُّ النَّبِيِّracter, for me at least, of how he was prophesized in earlier books. The advent of the Prophet, tحُبُّ النَّبِيِّt he was going to come, was mentioned in previous, all previous religious books. But so I want to sحُبُّ النَّبِيِّre tحُبُّ النَّبِيِّt, how he was described, but I''m not going to translate it for you for the want of time. But you know, there is this — in these previous books, اللهُ describes all of his qualities by which he will be recognized, or by which we can, you know, he was telling the Christians, the Jews, how you can recognize him. And he said, so it goes like something like...', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'i mean i can go on and on about the stories just telling you about the cحب النبيracter of a prophet but you know im gonna end with this one last thing about him tحب النبيt i want to sحب النبيre with you tحب النبيt sums up his cحب النبيracter for me at least of how he was prophesized in earlier books the advent of the prophet tحب النبيt he was going to come was mentioned in previous all previous religious books but so i want to sحب النبيre tحب النبيt how he was described but im not going to translate it for you for the want of time but you know there is this in these previous books الله describes all of his qualities by which he will be recognized or by which we can you know he was telling the christians the jews how you can recognize him and he said so it goes like something like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 64, NULL, 'So those of you who knows Arabic, they can probably follow tحُبُّ النَّبِيِّt. You know, I''m gonna raise a man from amongst you. ... وَالْحِكْمَةَ مَنْطِقُهُ، وَالسِّتْرُ وَالْوَفَاءُ طَبِيعَتُهُ، وَالْعَفْوُ وَالْمَعْرُوفُ خُلُقُهُ، وَالْحَقُّ شَرِيعَتُهُ، وَالْعَدْلُ سِيرَتُهُ، وَالْهُدَى إِمَامُهُ، وَالْإِسْلَامُ مِلَّتُهُ، وَأَحْمَدُ اسْمُهُ، هَدَى بِهِ بَعْدَ الضَّلَالَةِ، وَعَلَّمَ بِهِ بَعْدَ الْجَهَالَةِ، وَرَفَعَ بِهِ بَعْدَ الْخَمَالَةِ، وَعَرَّفَ بِهِ بَعْدَ النَّكِرَةِ، وَأَكْثَرَ بِهِ بَعْدَ الْقِلَّةِ، وَأَغْنَى بِهِ بَعْدَ الْعَيْلَةِ، وَجَمَعَ بِهِ بَعْدَ الْفُرْقَةِ، وَأَلَّفَ بِهِ بَيْنَ أُمَمٍ مُتَفَرِّقَةٍ، وَقُلُوبٍ مُخْتَلِفَةٍ، وَأَهْوَاءٍ مُتَشَتِّتَةٍ Beautiful, beautiful wordings. I mean, we could just, it''s gonna take so much time to even explain this, but just describing these incredible qualities of the Prophet. But after he revealed all of these beautiful cحُبُّ النَّبِيِّracteristics,', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'so those of you who knows arabic they can probably follow tحب النبيt you know im gonna raise a man from amongst you والحكمه منطقه والستر والوفاء طبيعته والعفو والمعروف خلقه والحق شريعته والعدل سيرته والهدي امامه والاسلام ملته واحمد اسمه هدي به بعد الضلاله وعلم به بعد الجهاله ورفع به بعد الخماله وعرف به بعد النكره واكثر به بعد القله واغني به بعد العيله وجمع به بعد الفرقه والف به بين امم متفرقه وقلوب مختلفه واهواء متشتته beautiful beautiful wordings i mean we could just its gonna take so much time to even explain this but just describing these incredible qualities of the prophet but after he revealed all of these beautiful cحب النبيracteristics', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 65, NULL, 'and the qualities of the messenger, who''s going to be sent for humanity so tحُبُّ النَّبِيِّt nations could identify him. After mentioning all this, in the end he says, he identifies the most prominent cحُبُّ النَّبِيِّracter of this man. It says, you will see tحُبُّ النَّبِيِّt this man will walk with such humility, the greatest man in the world, the beloved of اللهُ, the leader of all messengers, tحُبُّ النَّبِيِّt you will see him walk with such humility tحُبُّ النَّبِيِّt if he walked on dry leaves, you would not hear them crack under his feet. To me, this sums up the cحُبُّ النَّبِيِّracter of my Prophet. This humility, the sense of أَبُو ضِيَاء before اللهُ. Seeing people as the creation of اللهُ. May اللهُ strengthen us all, our children, our generation, you know, with the cحُبُّ النَّبِيِّracter of this incredible Prophet. He is such a school. We حُبُّ النَّبِيِّve so much to learn from him. You know, today is his birthday. Today is the day we were blessed with his presence.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'and the qualities of the messenger whos going to be sent for humanity so tحب النبيt nations could identify him after mentioning all this in the end he says he identifies the most prominent cحب النبيracter of this man it says you will see tحب النبيt this man will walk with such humility the greatest man in the world the beloved of الله the leader of all messengers tحب النبيt you will see him walk with such humility tحب النبيt if he walked on dry leaves you would not hear them crack under his feet to me this sums up the cحب النبيracter of my prophet this humility the sense of ابو ضياء before الله seeing people as the creation of الله may الله strengthen us all our children our generation you know with the cحب النبيracter of this incredible prophet he is such a school we حب النبيve so much to learn from him you know today is his birthday today is the day we were blessed with his presence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 66, NULL, 'This day is not so tحُبُّ النَّبِيِّt we just talk about all of this and forget about it the next day. This 12th رَبِيعُ الأَوَّل is not to be celebrated on one day. It is meant to be celebrated every single day of our lives. And the way we celebrate our messenger is by exemplifying his cحُبُّ النَّبِيِّracter, by cultivating his cحُبُّ النَّبِيِّracter within our own self. By constantly thinking, how would my Prophet interact here? By knowing about him, by learning about him, by studying his interactions. How did he deal with this situation? Wحُبُّ النَّبِيِّt did he do? Wحُبُّ النَّبِيِّt did he say in this situation? Tحُبُّ النَّبِيِّt''s celebrating the Prophet. This day, this 12th رَبِّ الْأَبَلْ is supposed to be celebrated every single day of our life.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'this day is not so tحب النبيt we just talk about all of this and forget about it the next day this 12th ربيع الاول is not to be celebrated on one day it is meant to be celebrated every single day of our lives and the way we celebrate our messenger is by exemplifying his cحب النبيracter by cultivating his cحب النبيracter within our own self by constantly thinking how would my prophet interact here by knowing about him by learning about him by studying his interactions how did he deal with this situation wحب النبيt did he do wحب النبيt did he say in this situation tحب النبيts celebrating the prophet this day this 12th رب الابل is supposed to be celebrated every single day of our life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'character of the prophet', 'Character Of The Prophet', 67, NULL, 'It''s not just, you know, we say all this good stuff about him and then just go on with our lives as it was. Tحُبُّ النَّبِيِّt''s not celebrating. We can celebrate the rest of the world like this, not our Prophet. We should celebrate him every single day of our lives by remembering him, by knowing about him, by learning about him. ...........................', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'its not just you know we say all this good stuff about him and then just go on with our lives as it was tحب النبيts not celebrating we can celebrate the rest of the world like this not our prophet we should celebrate him every single day of our lives by remembering him by knowing about him by learning about him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ، الْحَمْدُ لِلَّهِ خَالِقِ الْوُجُودِ مِنَ الْعَدَمِ، وَجَاعِلِ النُّورِ مِنَ الظُّلَمِ، وَمُخْرِجِ الصَّبْرِ مِنَ الْأَلَمِ، وَمُلْكِ التَّوْبَةِ عَلَى النَّدَمِ، فَنَشْكُرُهُ عَلَى الْمَصَائِبِ كَمَا نَشْكُرُهُ عَلَى النِّعَمِ، وَنُصَلِّي عَلَى رَسُولِهِ الْأَكْرَمِ، لِلشَّرَفِ الْأَشَمِّ، وَالنُّورِ الْأَتَمِّ، وَالْكِتَابِ الْمُحْكَمِ، وَكَمَالِ النَّابِغِينَ وَالْخَاتَمِ، سَيِّدِ وَلَدِ آدَمَ، الَّذِي بَشَّرَ بِهِ قِسُّ بْنُ مَرْيَمَ، وَدَعَا لَهُ بِأَسَاطِيحِهِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ، حِينَ كَانَ يَرْفَعُ قَوَاعِدَ بَيْتِ اللَّهِ الْمُحَرَّمِ، فَصَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ، وَعَلَى أَصْحَابِهِ خَيْرِ الْأُمَمِ، الَّذِينَ بَارَكَ اللَّهُ بِهِمْ كَافَّةَ النَّاسِ الْعَرَبِ مِنْهُمْ وَالْعَجَمِ، وَصَلَّى اللَّهُ عَلَى أَمِيرِ الْمُؤْمِنِينَ الْأَنْزَعِ الْبَطِينِ وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ، غَالِبٍ عَلَى كُلِّ غَالِبٍ، وَمَطْلُوبِ كُلِّ طَالِبٍ. الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا. الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا. الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ، وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ. وَنَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ، أَرْسَلَهُ اللَّهُ تَعَالَى بِالْهُدَىٰ وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَىٰ بِاللَّهِ شَهِيدًا. اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ. اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا. اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ عَيْنٍ لَا تَدْمَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ. فَأَمَّا بَعْدُ، قَالَ اللَّهُ سُبْحَانَهُ وَتَعَالَىٰ فِي كِتَابِهِ الْكَرِيمِ، بَعْدَ أَنْ قَالَ أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ: رَبِّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي، يَفْقَهُوا قَوْلِي. اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِـلَا إِلَٰهَ إِلَّا اللَّهُ، وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ، آمِينَ يَا رَبَّ الْعَالَمِينَ. السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ، الْحَمْدُ لِلَّهِ خَالِقِ الْوُجُودِ مِنَ الْعَدَمِ، وَجَاعِلِ النُّورِ مِنَ الظُّلَمِ، وَمُخْرِجِ الصَّبْرِ مِنَ الْأَلَمِ، وَمُلْكِ التَّوْبَةِ عَلَى النَّدَمِ، فَنَشْكُرُهُ عَلَى الْمَصَائِبِ كَمَا نَشْكُرُهُ عَلَى النِّعَمِ، وَنُصَلِّي عَلَى رَسُولِهِ الْأَكْرَمِ، لِلشَّرَفِ الْأَشَمِّ، وَالنُّورِ الْأَتَمِّ، وَالْكِتَابِ الْمُحْكَمِ، وَكَمَالِ النَّابِغِينَ وَالْخَاتَمِ، سَيِّدِ وَلَدِ آدَمَ، الَّذِي بَشَّرَ بِهِ قِسُّ بْنُ مَرْيَمَ، وَدَعَا لَهُ بِأَسَاطِيحِهِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ، حِينَ كَانَ يَرْفَعُ قَوَاعِدَ بَيْتِ اللَّهِ الْمُحَرَّمِ، فَصَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ، وَعَلَى أَصْحَابِهِ خَيْرِ الْأُمَمِ، الَّذِينَ بَارَكَ اللَّهُ بِهِمْ كَافَّةَ النَّاسِ الْعَرَبِ مِنْهُمْ وَالْعَجَمِ، وَصَلَّى اللَّهُ عَلَى أَمِيرِ الْمُؤْمِنِينَ الْأَنْزَعِ الْبَطِينِ وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ، غَالِبٍ عَلَى كُلِّ غَالِبٍ، وَمَطْلُوبِ كُلِّ طَالِبٍ الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ، وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ وَنَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ، أَرْسَلَهُ اللَّهُ تَعَالَى بِالْهُدَىٰ وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَىٰ بِاللَّهِ شَهِيدًا اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ عَيْنٍ لَا تَدْمَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ فَأَمَّا بَعْدُ، قَالَ اللَّهُ سُبْحَانَهُ وَتَعَالَىٰ فِي كِتَابِهِ الْكَرِيمِ، بَعْدَ أَنْ قَالَ أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي، يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِـلَا إِلَٰهَ إِلَّا اللَّهُ، وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ، آمِينَ يَا رَبَّ الْعَالَمِينَ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'love of the prophet a model for success', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله خالق الوجود من العدم وجاعل النور من الظلم ومخرج الصبر من الالم وملك التوبه علي الندم فنشكره علي المصايب كما نشكره علي النعم ونصلي علي رسوله الاكرم للشرف الاشم والنور الاتم والكتاب المحكم وكمال النابغين والخاتم سيد ولد ادم الذي بشر به قس بن مريم ودعا له باساطيحه ابراهيم عليه السلام حين كان يرفع قواعد بيت الله المحرم فصلي الله عليه وعلي اله وسلم وعلي اصحابه خير الامم الذين بارك الله بهم كافه الناس العرب منهم والعجم وصلي الله علي امير المومنين الانزع البطين وقايد الغر المحجلين غالب علي كل غالب ومطلوب كل طالب الحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه ونعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع فاما بعد قال الله سبحانه وتعالي في كتابه الكريم بعد ان قال اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين السلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله خالق الوجود من العدم وجاعل النور من الظلم ومخرج الصبر من الالم وملك التوبه علي الندم فنشكره علي المصايب كما نشكره علي النعم ونصلي علي رسوله الاكرم للشرف الاشم والنور الاتم والكتاب المحكم وكمال النابغين والخاتم سيد ولد ادم الذي بشر به قس بن مريم ودعا له باساطيحه ابراهيم عليه السلام حين كان يرفع قواعد بيت الله المحرم فصلي الله عليه وعلي اله وسلم وعلي اصحابه خير الامم الذين بارك الله بهم كافه الناس العرب منهم والعجم وصلي الله علي امير المومنين الانزع البطين وقايد الغر المحجلين غالب علي كل غالب ومطلوب كل طالب الحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه ونعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع فاما بعد قال الله سبحانه وتعالي في كتابه الكريم بعد ان قال اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين السلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 1, NULL, 'So as I mentioned today, I just wanted to end these sessions, الْحَمْدُ لِلَّهِ, for the opportunity to be able to talk about our Prophet. And, you know, thank you all for joining and taking the time out. I know we have such busy schedules, but may اللَّه reward you for making this a priority. Today''s session, like I said, is more geared towards my kids in the session. I have my nephews, my nieces, and then I''m sure there are many other young adults in the group that I don''t know of. But I hope that this session will help you in some way and make things easy for you.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so as i mentioned today i just wanted to end these sessions الحمد لله for the opportunity to be able to talk about our prophet and you know thank you all for joining and taking the time out i know we have such busy schedules but may الله reward you for making this a priority todays session like i said is more geared towards my kids in the session i have my nephews my nieces and then im sure there are many other young adults in the group that i dont know of but i hope that this session will help you in some way and make things easy for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 2, NULL, 'So I wanted to end this with a model of success. The dictionary defines success as the accomplishment of an aim or a purpose. So if we are all going on a bus and I invite you young boys and girls in this group to join me on that drive. And let''s say we drove by this beautiful mansion, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so i wanted to end this with a model of success the dictionary defines success as the accomplishment of an aim or a purpose so if we are all going on a bus and i invite you young boys and girls in this group to join me on that drive and lets say we drove by this beautiful mansion right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 3, NULL, 'A stunningly beautiful house on top of a hill with this magnificent sports car outside and an incredible backyard with an Olympic size swimming pool in it. And if I asked you guys, do you think the guy living in this mansion is successful? Overwhelmingly, I think your answer is going to be the yeah, right? So let''s say we continue driving and a little further we see a man, a homeless man living in a cardboard box on the street. And the clothes that he''s wearing appears to be like a couple years old. Now, if I asked you, is this man successful? What would you say? I''m pretty sure your answer will be no.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'a stunningly beautiful house on top of a hill with this magnificent sports car outside and an incredible backyard with an olympic size swimming pool in it and if i asked you guys do you think the guy living in this mansion is successful overwhelmingly i think your answer is going to be the yeah right so lets say we continue driving and a little further we see a man a homeless man living in a cardboard box on the street and the clothes that hes wearing appears to be like a couple years old now if i asked you is this man successful what would you say im pretty sure your answer will be no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 4, NULL, 'And that''s the problem. The problem is in the way we think about success and the way in which we think about failure. Now, when we turn to the قُرْآن, we find that one of the most beautiful, one of the most captivating, magnificent palaces that were ever built was the castle of فِرْعَوْنُ.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'and thats the problem the problem is in the way we think about success and the way in which we think about failure now when we turn to the قران we find that one of the most beautiful one of the most captivating magnificent palaces that were ever built was the castle of فرعون', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 5, NULL, 'It was one of the most amazing palaces ever built. Was فِرْعَوْنُ successful in the eyes of اللَّه? No, he wasn''t. According to the قُرْآن, he was amongst the worst of losers, the royal losers. What was the second kind of person we met on our trip? That homeless man, right? Was إِبْرَاهِيم kicked out of his house? Yes. Did مُوسَى have to flee from his city and live a poor life in a foreign land? Sure. But were they both failures? No. Not according to the قُرْآن. According to the قُرْآن, they were both extremely successful people. So when I see this world through the lens of قُرْآن, my perspective changes. The قُرْآن is teaching me that a homeless man is successful. And an incredibly wealthy man, an incredibly powerful man is a complete failure in the eyes of اللَّه.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'it was one of the most amazing palaces ever built was فرعون successful in the eyes of الله no he wasnt according to the قران he was amongst the worst of losers the royal losers what was the second kind of person we met on our trip that homeless man right was ابراهيم kicked out of his house yes did موسي have to flee from his city and live a poor life in a foreign land sure but were they both failures no not according to the قران according to the قران they were both extremely successful people so when i see this world through the lens of قران my perspective changes the قران is teaching me that a homeless man is successful and an incredibly wealthy man an incredibly powerful man is a complete failure in the eyes of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 6, NULL, 'This means success in the eyes of اللَّه has nothing to do with fame. It has nothing to do with power, wealth. It has nothing to do with how beautiful you look or how many likes you get on Facebook. In the same way, failure from اللَّه''s perspective has nothing to do with poverty or destitution. So then what is success? There are several words for success that are used in the قُرْآن. The most commonly used are فَوْز and فَلَاحٌ. Those are the two words that you must have come across quite often if you recite the قُرْآن. The word فَوْز, it means victory. Like when you win a competition or generally when there is some kind of prize involved, the word فَوْز is used. ‏تِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَرُ خَلِدِينَ فِيهَا ۚ وَذَلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ ‎. Whoever obeys اللَّه and His Messenger is going to enter paradise that has rivers flowing under it. They will live there forever.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'this means success in the eyes of الله has nothing to do with fame it has nothing to do with power wealth it has nothing to do with how beautiful you look or how many likes you get on facebook in the same way failure from اللهs perspective has nothing to do with poverty or destitution so then what is success there are several words for success that are used in the قران the most commonly used are فوز and فلاح those are the two words that you must have come across quite often if you recite the قران the word فوز it means victory like when you win a competition or generally when there is some kind of prize involved the word فوز is used تلك حدود الله ومن يطع الله ورسوله يدخله جنت تجري من تحتها الانهر خلدين فيها وذلك الفوز العظيم whoever obeys الله and his messenger is going to enter paradise that has rivers flowing under it they will live there forever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 7, NULL, 'That is a great victory. So it creates this image, the word فَوْز, it creates this image like a prize, right? Paradise is being given as a prize at the end of the journey. But فَلَاح is a much more powerful word in Arabic. It is actually an agricultural term. The word means to till the ground, to plow the land, to cultivate it. What do you do when you till the land? Like a farmer, when he tills the land, what is he trying to do? He unfolds and he reveals its intrinsic properties of growth. When you till the land, you break open the surface of the earth and you activate its power of productivity. That''s imamate of فَلَاح.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'that is a great victory so it creates this image the word فوز it creates this image like a prize right paradise is being given as a prize at the end of the journey but فلاح is a much more powerful word in arabic it is actually an agricultural term the word means to till the ground to plow the land to cultivate it what do you do when you till the land like a farmer when he tills the land what is he trying to do he unfolds and he reveals its intrinsic properties of growth when you till the land you break open the surface of the earth and you activate its power of productivity thats imamate of فلاح', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 8, NULL, 'When a farmer works for months on his farm tilling the land, cultivating it, laying the seed, watering it, protecting it from insects over and over again, month after month, what happens eventually? He gets a harvest, which is many times more, exponentially more than his original investment. That is فَلَاح. That''s the concept of فَلَاح. That is success. To receive a return on your investment that is beyond measure.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'when a farmer works for months on his farm tilling the land cultivating it laying the seed watering it protecting it from insects over and over again month after month what happens eventually he gets a harvest which is many times more exponentially more than his original investment that is فلاح thats the concept of فلاح that is success to receive a return on your investment that is beyond measure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 9, NULL, 'Now one of the motifs of قُرْآن is the use of oaths. Right? اللَّه swears by things in the قُرْآن. We see this in many verses in which he does that. And the purpose behind these, and this is a very complex subject, I''m just going to sort of browse over it, but it''s very interesting why اللَّه takes oaths. But to summarize, the purpose is that to grab our attention. That''s the first purpose. And second, to emphasize the point that he''s about to make. And always, you know, oath is taken of sanctified things, right? We take oaths of sanctified things, things that are important. If I said, you know, I swear to you by this mosquito in my room, or I swear to you by the stain on my carpet, or this ripped t-shirt, you know, it''s not going to generate serious confidence in you, is it? About what I''m about to say. But if I swear by things that are valuable to me, right? I swear by my daughter, I swear by the life of my son, then it increases confidence and it adds value to the reason and purpose of my taking that oath. Now, what if اللَّه is the one taking the oath, right?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'now one of the motifs of قران is the use of oaths right الله swears by things in the قران we see this in many verses in which he does that and the purpose behind these and this is a very complex subject im just going to sort of browse over it but its very interesting why الله takes oaths but to summarize the purpose is that to grab our attention thats the first purpose and second to emphasize the point that hes about to make and always you know oath is taken of sanctified things right we take oaths of sanctified things things that are important if i said you know i swear to you by this mosquito in my room or i swear to you by the stain on my carpet or this ripped t shirt you know its not going to generate serious confidence in you is it about what im about to say but if i swear by things that are valuable to me right i swear by my daughter i swear by the life of my son then it increases confidence and it adds value to the reason and purpose of my taking that oath now what if الله is the one taking the oath right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 10, NULL, 'We understand its importance in the context of human beings, but now what if اللَّه is the one taking the oath? How would that grab your attention? And how much trust and importance would you place on what he''s about to say? And what if اللَّه swears not by one object, but multiple objects, multiple sanctified objects? How would that affect you? You see my point? So اللَّه takes some oaths in سُورَةُ الشَّمْسِ over some objects that are really important for human life. Keep in mind the importance of an oath as you hear this. اللَّه says, وَٱلشَّمْسِ وَضُحَىٰهَا, I swear by the sun and its brilliance. First oath, وَٱلْقَمَرِ إِذَا تَلَىٰهَا, and by the moon as it follows. Second oath, وَٱلنَّهَارِ إِذَا جَلَّىٰهَا, and by the day as it brightens things.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'we understand its importance in the context of human beings but now what if الله is the one taking the oath how would that grab your attention and how much trust and importance would you place on what hes about to say and what if الله swears not by one object but multiple objects multiple sanctified objects how would that affect you you see my point so الله takes some oaths in سوره الشمس over some objects that are really important for human life keep in mind the importance of an oath as you hear this الله says والشمس وضحاها i swear by the sun and its brilliance first oath والقمر اذا تلاها and by the moon as it follows second oath والنهار اذا جلاها and by the day as it brightens things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 11, NULL, 'Third oath, وَاللَّيْلِ إِذَا يَغْشَاهَا, and by the night as it conceals things. Fourth, وَٱلسَّمَآءِ وَمَا بَنَىٰهَا, and the heavens and the one who built it. Fifth, and by the earth and the one who spread it. Sixth, and by the soul and the one who perfected it. Seventh, اللَّهُ سُبْحَانَهُ وَتَعَالَى takes seven oaths using 14 objects, right? The sun and its brilliance, the moon and its following the sun, the day and its luminance, the night and its concealment of things. The heavens and the one who built it, the earth and the one who spread it, the soul and the one who perfected it. Seven oaths using 14 objects of oath before coming to his point. So whatever he''s about to say, how important and valuable do you think it is going to be? And what is it that he wants us to know? He has revealed what is wrong and what is right.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'third oath والليل اذا يغشاها and by the night as it conceals things fourth والسماء وما بناها and the heavens and the one who built it fifth and by the earth and the one who spread it sixth and by the soul and the one who perfected it seventh الله سبحانه وتعالي takes seven oaths using 14 objects right the sun and its brilliance the moon and its following the sun the day and its luminance the night and its concealment of things the heavens and the one who built it the earth and the one who spread it the soul and the one who perfected it seven oaths using 14 objects of oath before coming to his point so whatever hes about to say how important and valuable do you think it is going to be and what is it that he wants us to know he has revealed what is wrong and what is right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 12, NULL, 'So he makes this declarative statement, and then he comes to the point. See that word? Indeed, the one who purified himself succeeded. That same word is used, exponential returns on investment. And the one who corrupted himself has failed. So successful is he who purified his soul during his lifetime, and the one who corrupted his soul is the ultimate failure.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so he makes this declarative statement and then he comes to the point see that word indeed the one who purified himself succeeded that same word is used exponential returns on investment and the one who corrupted himself has failed so successful is he who purified his soul during his lifetime and the one who corrupted his soul is the ultimate failure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 13, NULL, 'So with that definition of success, I wanted to share with you these 10 qualities that were identified by a neuropsychologist who studied successful people over a period of several years. And he found certain qualities that were common in them. Now the principles of success, right? If they''re good for this world, this دُنْيَا, then they should also be good for the spiritual success to me, because that''s what principle means to me, universal truths. So I''ve been trying to follow some of these and I''ve seen some really tangible improvements in my life. So I thought I''d share these with you, hoping and praying that they''ll help you as well.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so with that definition of success i wanted to share with you these 10 qualities that were identified by a neuropsychologist who studied successful people over a period of several years and he found certain qualities that were common in them now the principles of success right if theyre good for this world this دنيا then they should also be good for the spiritual success to me because thats what principle means to me universal truths so ive been trying to follow some of these and ive seen some really tangible improvements in my life so i thought id share these with you hoping and praying that theyll help you as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 14, NULL, 'Again, this is just نَصِيحَة, it is just a suggestion, take it or leave it. But at least give it a shot is what I would say because, you know, I''ve learned not to reject ideas without trying them first. Anyway, so these qualities that he mentions, the first quality of success he says is that successful people have a strong sense of purpose. In order to succeed, you have to have a strong sense of purpose. What is our purpose as Muslims? Our purpose is our Lord. He is our ultimate purpose. It is the recognition and our willing submission to our Creator. ‏وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ ‎. We have not created jinn and man except for recognizing اللهُ سُبْحَانَهُ وَتَعَالَى as the only one worthy of our devotion and worship. لَآ إِلَهَ إِلَّا ٱللَّهُ. That''s our purpose. And what greater sense of purpose than to know that our goal is اللَّه?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'again this is just نصيحه it is just a suggestion take it or leave it but at least give it a shot is what i would say because you know ive learned not to reject ideas without trying them first anyway so these qualities that he mentions the first quality of success he says is that successful people have a strong sense of purpose in order to succeed you have to have a strong sense of purpose what is our purpose as muslims our purpose is our lord he is our ultimate purpose it is the recognition and our willing submission to our creator وما خلقت الجن والانس الا ليعبدون we have not created jinn and man except for recognizing الله سبحانه وتعالي as the only one worthy of our devotion and worship لا اله الا الله thats our purpose and what greater sense of purpose than to know that our goal is الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 15, NULL, 'What greater purpose than to emulate the beautiful character of our Prophet? And the essence of his character was humility. That is the key to success in الْإِسْلَام. Humility in our dealings with the Creator and humility in our dealings with his creation.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'what greater purpose than to emulate the beautiful character of our prophet and the essence of his character was humility that is the key to success in الاسلام humility in our dealings with the creator and humility in our dealings with his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 16, NULL, 'The second most identifiable character, he said, is that successful people seek out role models or mentors. And these mentors instill in them a sense of possibility. This is the reason why رَسُولُ اللهِ was given the stories of previous prophets, you know, those prophets that came before him, to give him تَثْبِيت, to make his heart firm. So that he would know that he would have success just as the prophets before him had success despite all their tribulations. So role model, having a right role model is extremely important for success. Look who we follow today, right? Look at our role models today. Hollywood and Bollywood stars, singers, actors.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'the second most identifiable character he said is that successful people seek out role models or mentors and these mentors instill in them a sense of possibility this is the reason why رسول الله was given the stories of previous prophets you know those prophets that came before him to give him تثبيت to make his heart firm so that he would know that he would have success just as the prophets before him had success despite all their tribulations so role model having a right role model is extremely important for success look who we follow today right look at our role models today hollywood and bollywood stars singers actors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 17, NULL, 'Our culture is filled with these icons. These false idols that are set up for people to imitate. Not great people, not people of high أَخْلَاق, not people of great character. Actors, musicians, مُشَاوِزٍ, people of the lowest level of human society in history. If you study history, Roman history, Greek history, any history in the old time, you''ll see that the lowest people in any society have been actors and musicians, the jesters in the courts. There''s nothing noble about these professions. And yet, in today''s society, they are exalted, they are worshipped, and they''re put up on this pedestal for us to follow. You have the best example to follow in the character of your Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. What impresses you about these people? Seriously, what impresses you about these actors that makes you wanna imitate them, be like them? What is it?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'our culture is filled with these icons these false idols that are set up for people to imitate not great people not people of high اخلاق not people of great character actors musicians مشاوز people of the lowest level of human society in history if you study history roman history greek history any history in the old time youll see that the lowest people in any society have been actors and musicians the jesters in the courts theres nothing noble about these professions and yet in todays society they are exalted they are worshipped and theyre put up on this pedestal for us to follow you have the best example to follow in the character of your prophet صلي الله عليه وسلم what impresses you about these people seriously what impresses you about these actors that makes you wanna imitate them be like them what is it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 18, NULL, 'Because they display these beautiful human qualities on a screen, on a movie, of love, of courage, of charity, of generosity, of patience, resilience in the face of adversity. Is that what attracts you about them? They were acting, just acting. They could be wretched in their real lives, and many of them are. My prophet was not an actor. My prophet was not pretending to have these beautiful qualities that capture the heart and mind. He was living them daily. He was the embodiment of every truth that has ever come to mankind, and in following him we are elevated.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'because they display these beautiful human qualities on a screen on a movie of love of courage of charity of generosity of patience resilience in the face of adversity is that what attracts you about them they were acting just acting they could be wretched in their real lives and many of them are my prophet was not an actor my prophet was not pretending to have these beautiful qualities that capture the heart and mind he was living them daily he was the embodiment of every truth that has ever come to mankind and in following him we are elevated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 19, NULL, 'You know, today the world is going insane over wanting to be like someone, right? They want to be like, because to them being is being like, when you don''t have an essence of your own. You know, like all these people out there imitating pop stars because they don''t have a personality of their own. They''re empty people. So they take the shells of other people, because being for them is being like.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'you know today the world is going insane over wanting to be like someone right they want to be like because to them being is being like when you dont have an essence of your own you know like all these people out there imitating pop stars because they dont have a personality of their own theyre empty people so they take the shells of other people because being for them is being like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 20, NULL, 'They have no reality of their own. So Michael Jackson wears one glove, they start wearing one glove. If Stallone starts wearing Ray-Ban glasses, they start wearing Ray-Ban glasses. And this is a disease. You know, we as Muslims, read the history. We as Muslims used to be trendsetters. People used to imitate us. But look how we''ve fallen. So you want a role model to follow? I''ll give you a role model. His name is Muhammad Mustafa صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ. Follow him.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'they have no reality of their own so michael jackson wears one glove they start wearing one glove if stallone starts wearing ray ban glasses they start wearing ray ban glasses and this is a disease you know we as muslims read the history we as muslims used to be trendsetters people used to imitate us but look how weve fallen so you want a role model to follow ill give you a role model his name is muhammad mustafa صلي الله عليه واله وسلم follow him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 21, NULL, 'عَلِيُّ بْنُ أَبِي طَالِبٍ, another role model. Not an actor, not a pretender, not just acting to be courageous. So really take some time to think about who you want to follow and why. I say this with real seriousness. I mean, you guys are our future. You are the future of our religion. And we have high hopes from you. Seriously, we have high hopes from you. I have high hopes from you. So be the light in these dark times for those around you. Be a role model for your friends by adopting the character of your Prophet, and you will find success in this life and the next. إِن شَآءَ ٱللَّهُ.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'علي بن ابي طالب another role model not an actor not a pretender not just acting to be courageous so really take some time to think about who you want to follow and why i say this with real seriousness i mean you guys are our future you are the future of our religion and we have high hopes from you seriously we have high hopes from you i have high hopes from you so be the light in these dark times for those around you be a role model for your friends by adopting the character of your prophet and you will find success in this life and the next ان شاء الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 22, NULL, 'The third quality they say is the strength of visualizing goals. No one had more clarity of his goal than our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. You know, visualizing ourselves in the presence of اللَّه. Visualizing ourselves in the presence of the Prophet, of مَولَانَا عَلِي, of the أَئِمَّة. You know, visualizing that they are greeting us with happiness and pride and not with disappointment. You guys have seen that Lord of the Rings, right? There''s that scene in that movie where that king falls in battle, I forget his name, and he''s about to die. And his daughter is crying next to him. I remember he says to his daughter, don''t be sad. In that scene, he says to his daughter as he''s dying, don''t be sad. I go to my fathers, in whose mighty company I shall now not feel ashamed. What a powerful statement that is, right? I go to my fathers, in whose company I shall not feel ashamed.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'the third quality they say is the strength of visualizing goals no one had more clarity of his goal than our prophet صلي الله عليه وسلم you know visualizing ourselves in the presence of الله visualizing ourselves in the presence of the prophet of مولانا علي of the ايمه you know visualizing that they are greeting us with happiness and pride and not with disappointment you guys have seen that lord of the rings right theres that scene in that movie where that king falls in battle i forget his name and hes about to die and his daughter is crying next to him i remember he says to his daughter dont be sad in that scene he says to his daughter as hes dying dont be sad i go to my fathers in whose mighty company i shall now not feel ashamed what a powerful statement that is right i go to my fathers in whose company i shall not feel ashamed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 23, NULL, 'سُبْحَانَ اللَّهِ. When I die, when I leave this world, that''s what I want to be able to say to my daughter. That''s my vision. That I''m going in the company of my prophet. I''m going in the company of مَولَانَا عَلِي, the Imams, and I''m not ashamed. I don''t feel ashamed. That is what we want, إِن شَآءَ ٱللَّهُ. So our vision is the vision of success. We are people of success. And this religion is a دِينٌ of success. It is not a دِينٌ of failure. And our prophet was the most successful human being that ever lived on the face of this earth.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'سبحان الله when i die when i leave this world thats what i want to be able to say to my daughter thats my vision that im going in the company of my prophet im going in the company of مولانا علي the imams and im not ashamed i dont feel ashamed that is what we want ان شاء الله so our vision is the vision of success we are people of success and this religion is a دين of success it is not a دين of failure and our prophet was the most successful human being that ever lived on the face of this earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 24, NULL, 'The fourth, he said, is a positive sensitive orientation. That we dwell on past successes and not on past failures. That we never give up hope. That we never stop striving no matter what challenges confront us. And this is why اللَّه reminds us. Remember your past successes, when you were weak and اللَّه gave you victory in the battle of بَدْر. And so we have to remember that اللَّه will give us victory in the end if we keep trying and if we don''t give up. You know, I''ll tell you something about setting goals. You know how everybody tells you, when you hear this, dream big, reach for the sun, the moon, the stars. Don''t. If you want my sincere advice, don''t reach for the sun. Think small.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'the fourth he said is a positive sensitive orientation that we dwell on past successes and not on past failures that we never give up hope that we never stop striving no matter what challenges confront us and this is why الله reminds us remember your past successes when you were weak and الله gave you victory in the battle of بدر and so we have to remember that الله will give us victory in the end if we keep trying and if we dont give up you know ill tell you something about setting goals you know how everybody tells you when you hear this dream big reach for the sun the moon the stars dont if you want my sincere advice dont reach for the sun think small', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 25, NULL, 'Don''t think big. Reach for the light bulb on your ceiling. That''s an awesome goal. Because what happens is you get so excited and you take on this enormous burden, this entire weight of the الْإِسْلَامic practices in one day, and then you collapse under its weight. Like going into a gym and trying to bench press 300 pounds on your first day. That''s crazy. So my advice to you, find small, manageable goals. That''s what works for me. If you''re not praying at all today, start with one single prayer. If you''re praying once a day, try adding another one onto it. Take on one quality of the Prophet you want to adopt and work on it for a while before you pick up another. And then celebrate your success, seriously.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'dont think big reach for the light bulb on your ceiling thats an awesome goal because what happens is you get so excited and you take on this enormous burden this entire weight of the الاسلامic practices in one day and then you collapse under its weight like going into a gym and trying to bench press 300 pounds on your first day thats crazy so my advice to you find small manageable goals thats what works for me if youre not praying at all today start with one single prayer if youre praying once a day try adding another one onto it take on one quality of the prophet you want to adopt and work on it for a while before you pick up another and then celebrate your success seriously', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 26, NULL, 'Enjoy your success. Feel great about doing that one extra prayer today instead of beating yourself up about not doing three. Seriously, I promise it''ll work wonders for you. And I might get into a lot of trouble for saying this, but the things I do for you guys. You know, once the Prophet was at a place and he wanted to set up a fire, he asked his companions to spread out and bring water. No, actually, he told them to spread out and bring twigs and branches that they could find. I think it''s in الدَّارِمِي as well. So they all went out and they picked up these small little things and they piled it on the ground. And soon a huge pile was formed. And he turned to his companions and he said, look, this is how good deeds accumulate. And this is also how bad deeds accumulate. سُبْحَانَ اللَّهِ.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'enjoy your success feel great about doing that one extra prayer today instead of beating yourself up about not doing three seriously i promise itll work wonders for you and i might get into a lot of trouble for saying this but the things i do for you guys you know once the prophet was at a place and he wanted to set up a fire he asked his companions to spread out and bring water no actually he told them to spread out and bring twigs and branches that they could find i think its in الدارمي as well so they all went out and they picked up these small little things and they piled it on the ground and soon a huge pile was formed and he turned to his companions and he said look this is how good deeds accumulate and this is also how bad deeds accumulate سبحان الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 27, NULL, 'So work on collecting these tiny twigs, tiny branches of good deeds, of good character. One more prayer, one more fast, understanding one more verse of the قُرْآن, one more act of courage, one more act of generosity, of temperance, one more small act of patience, not losing it, one more realization of gratitude, right? And before you know it, you''ll have this huge pile of good deeds in your collection, إِن شَآءَ ٱللَّهُ. So that''s another goal, that positive sensory orientation and a focus on it is important. The fifth he says is self-assurance. To know and believe that you can succeed. Do not feel weak, do not grieve, for you are great if you are believers, if you are believers. So have the confidence and assurance that you will succeed in the end. We have an everlasting life of joy and happiness ahead of us, إِن كُنتُم مُّؤْمِنِينَ, if you are believers. So study your religion, learn about it, because knowledge builds certainty.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so work on collecting these tiny twigs tiny branches of good deeds of good character one more prayer one more fast understanding one more verse of the قران one more act of courage one more act of generosity of temperance one more small act of patience not losing it one more realization of gratitude right and before you know it youll have this huge pile of good deeds in your collection ان شاء الله so thats another goal that positive sensory orientation and a focus on it is important the fifth he says is self assurance to know and believe that you can succeed do not feel weak do not grieve for you are great if you are believers if you are believers so have the confidence and assurance that you will succeed in the end we have an everlasting life of joy and happiness ahead of us ان كنتم مومنين if you are believers so study your religion learn about it because knowledge builds certainty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 28, NULL, 'Knowledge builds confidence. It builds self-assurance. Get your knowledge from your own studies, not from what the media tells you. Not from what your friends are tweeting about. Take it from the source, from the قُرْآن. The next he says is that successful people, they plan and organize. So start your day with a spiritual plan. What are you going to do today? How will you manifest the truth today? Or how will you conceal it? Are you going to follow رَسُولُ اللهِ today? Or will you follow إِبْلِيس?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'knowledge builds confidence it builds self assurance get your knowledge from your own studies not from what the media tells you not from what your friends are tweeting about take it from the source from the قران the next he says is that successful people they plan and organize so start your day with a spiritual plan what are you going to do today how will you manifest the truth today or how will you conceal it are you going to follow رسول الله today or will you follow ابليس', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 29, NULL, 'What will you prioritize today? Is it going to be your صَلَاةٌ or is it going to be fun and entertainment? And once you''ve established that, work everything around it. No, رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, he did not spend his day in seclusion on the مُصَلًّى with the تَسْبِيح in his hand all day long. No, he was out there enjoying the gift of life. But he knew what his priorities were. So successful people know how to prioritize. They break down their goals into workable, achievable parts. So we have to look at the most important things in our lives and we have to take it, our صَلَاةٌ, our أَخْلَاق, our عِبَادَة. We have to learn to prioritize our day around these things and not the other way. That if I have time, I will do صَلَاةٌ.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'what will you prioritize today is it going to be your صلاه or is it going to be fun and entertainment and once youve established that work everything around it no رسول الله صلي الله عليه وسلم he did not spend his day in seclusion on the مصلي with the تسبيح in his hand all day long no he was out there enjoying the gift of life but he knew what his priorities were so successful people know how to prioritize they break down their goals into workable achievable parts so we have to look at the most important things in our lives and we have to take it our صلاه our اخلاق our عباده we have to learn to prioritize our day around these things and not the other way that if i have time i will do صلاه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 30, NULL, 'No, I will do my صَلَاةٌ and if I have time, I will do something else. Our دِينُ الإِسْلَامِ, our debt of submission has to come first and foremost. So get the essentials in. Seriously, I know people arguing over ingredients in their toothpaste and not concerned about their daily prayers. They get caught up in this, these trivial matters. There''s this show these days going on, right? A friend of mine, right? He watched, we were watching this show and I got up for prayers and I went and I came back. He was still watching the show and he says, wow, you know, my faith is renewed. And all this. And I said, what kind of, you know, fresh إِيمَان is this that you see me getting up for prayers and it doesn''t move you to pray? But yeah, just taking all that nice feeling about, oh, how beautiful الْإِسْلَام is, but then not getting up to pray.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'no i will do my صلاه and if i have time i will do something else our دين الاسلام our debt of submission has to come first and foremost so get the essentials in seriously i know people arguing over ingredients in their toothpaste and not concerned about their daily prayers they get caught up in this these trivial matters theres this show these days going on right a friend of mine right he watched we were watching this show and i got up for prayers and i went and i came back he was still watching the show and he says wow you know my faith is renewed and all this and i said what kind of you know fresh ايمان is this that you see me getting up for prayers and it doesnt move you to pray but yeah just taking all that nice feeling about oh how beautiful الاسلام is but then not getting up to pray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 31, NULL, 'What kind of إِيمَان is that? Because the last I checked, إِيمَان is work. الْإِسْلَام is hard work. And they get caught up in these, you know, even like in these discussions, you get caught up in these trivial matters. Get the essentials in before you worry about the trivial things. Because this was the disease of that Talmudic rabbinical mind, which asked what kind of cow? What color of cow? Fat or thin? Right? In سُورَةُ الْبَقَرَةِ? And they say that the devil is in the details, right? Even in today''s culture, we say that.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'what kind of ايمان is that because the last i checked ايمان is work الاسلام is hard work and they get caught up in these you know even like in these discussions you get caught up in these trivial matters get the essentials in before you worry about the trivial things because this was the disease of that talmudic rabbinical mind which asked what kind of cow what color of cow fat or thin right in سوره البقره and they say that the devil is in the details right even in todays culture we say that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 32, NULL, 'These are narrow-minded, simpleton people that spend their lives in trivial pursuits, in matters of no concern. We have greater things to prioritize, like صَلَاةٌ, like fasting, like زَكَاة. Our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ was a universal man. He raised us above these trivialities and he put us into the most important matters. يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ. The day that nothing will benefit them, not wealth or anything except the one who comes with a sound heart, قَلْبٍ سَلِيمٍ. And so worry about where your heart is in your prayer, not where the feet is, not what color topi you''re wearing. Where''s the heart? Is it with God or is it with Amazon going over your shopping cart? Or is it with Netflix wondering what''s going to happen in the next episode?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'these are narrow minded simpleton people that spend their lives in trivial pursuits in matters of no concern we have greater things to prioritize like صلاه like fasting like زكاه our prophet صلي الله عليه وسلم was a universal man he raised us above these trivialities and he put us into the most important matters يوم لا ينفع مال ولا بنون الا من اتي الله بقلب سليم the day that nothing will benefit them not wealth or anything except the one who comes with a sound heart قلب سليم and so worry about where your heart is in your prayer not where the feet is not what color topi youre wearing wheres the heart is it with god or is it with amazon going over your shopping cart or is it with netflix wondering whats going to happen in the next episode', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 33, NULL, 'You know, the other day somebody was telling me that people get upset with this person if she wishes them جُمُعَة مُبَارَك. Amazing, right? They don''t get upset when they lie, when they cheat, when they gossip, betray people''s trust. No. They get upset when someone wishes them يَوْمُ الْجُمُعَةِ. Oh, you know, this is a bit... this is an innovation. I mean, seriously, you''re going to get offended and upset for somebody wishing you the blessings of Friday. And that''s the big priority instead of worrying about the prayer of Friday. Seriously, we''ve just gone mad. You know, is it السَّلَامُ عَلَيْكُمْ or is it السَّلَامُ عَلَيْكُمْ? Oh my God.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'you know the other day somebody was telling me that people get upset with this person if she wishes them جمعه مبارك amazing right they dont get upset when they lie when they cheat when they gossip betray peoples trust no they get upset when someone wishes them يوم الجمعه oh you know this is a bit this is an innovation i mean seriously youre going to get offended and upset for somebody wishing you the blessings of friday and thats the big priority instead of worrying about the prayer of friday seriously weve just gone mad you know is it السلام عليكم or is it السلام عليكم oh my god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 34, NULL, 'Seriously, you know, should I put a space after the الْحُبّ before I put the سَلَامٌ in? I''ll tell you what you can put there. It''s just, oh my God, I can''t tell you how. So, we have to learn to prioritize. The only reason, you know, these big corporations are so successful is because they know how to plan and how to organize. They plan way ahead of time. We can''t even plan for tomorrow, right? The only thing some of us have become good at is just planning what we''re going to eat for the next meal.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'seriously you know should i put a space after the الحب before i put the سلام in ill tell you what you can put there its just oh my god i cant tell you how so we have to learn to prioritize the only reason you know these big corporations are so successful is because they know how to plan and how to organize they plan way ahead of time we cant even plan for tomorrow right the only thing some of us have become good at is just planning what were going to eat for the next meal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 35, NULL, 'The next one he says is the ability to acquire the necessary skills needed to succeed. And that means you have to identify where your weaknesses are. And one of our greatest weakness is that we read the قُرْآن, but we don''t understand it. I think that to me personally, I think that''s one of the biggest problem.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'the next one he says is the ability to acquire the necessary skills needed to succeed and that means you have to identify where your weaknesses are and one of our greatest weakness is that we read the قران but we dont understand it i think that to me personally i think thats one of the biggest problem', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 36, NULL, 'How is it that as Muslims, we have not examined the قُرْآن? People taking pride over, you know, my son, my daughter is six months old and she completed like five قُرْآن. Like that''s the biggest thing today with the recitation of قُرْآن. What about the understanding of قُرْآن? What about understanding the meaning behind قُرْآن? You know, so many of us have this romantic attachment to the قُرْآن. Oh, what a great book. But we''ve never understood it. We read it like a parrot, but we never take the time to understand it. What''s the point? This is a book of guidance. How do you get guidance from a book you don''t even understand?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'how is it that as muslims we have not examined the قران people taking pride over you know my son my daughter is six months old and she completed like five قران like thats the biggest thing today with the recitation of قران what about the understanding of قران what about understanding the meaning behind قران you know so many of us have this romantic attachment to the قران oh what a great book but weve never understood it we read it like a parrot but we never take the time to understand it whats the point this is a book of guidance how do you get guidance from a book you dont even understand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 37, NULL, 'Right? We''re like people in this amazing restaurant looking at this menu written in Chinese. How are we going to order? When are we gonna be bothered to taste the beauty of قُرْآن? And this is why this romantic attachment to الْإِسْلَام is such a flimsy attachment. It''s an attachment that leads to extremism. It''s an attachment that leads to blind passion, right? And passion, once you get passionate about something, then everybody knows passion is something that is incompatible with the intellect, right? Like that story of that sparrow on top of Prophet سُلَيْمَان''s place of worship. So for those of you who don''t know that, there was this sparrow. He was trying to convince a female sparrow that he was a worthy mate. And she wasn''t paying any attention to him.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'right were like people in this amazing restaurant looking at this menu written in chinese how are we going to order when are we gonna be bothered to taste the beauty of قران and this is why this romantic attachment to الاسلام is such a flimsy attachment its an attachment that leads to extremism its an attachment that leads to blind passion right and passion once you get passionate about something then everybody knows passion is something that is incompatible with the intellect right like that story of that sparrow on top of prophet سليمانs place of worship so for those of you who dont know that there was this sparrow he was trying to convince a female sparrow that he was a worthy mate and she wasnt paying any attention to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 38, NULL, 'And this is a story, right? He said, "You know, if I wanted, I''d turn this dome right over on the head of سُلَيْمَان for you." And سُلَيْمَان عَلَيْهِ السَّلَامُ knew the interpretation of birds, so he called him down. And so he comes down, you know, all shaking, his little sparrow heart beating in his little sparrow chest, and Sulaiman says, "What made you say that ridiculous remark?" And the sparrow says, "O Prophet of اللَّه, don''t you know that lovers are never taken to account for what they say in the presence of their beloved?" In other words, I was in a state of passion. You can''t take me to account for that. And this is the reality around us, right? We get so these passionate displays of things and we have absolutely no idea what we''re doing, what we''re reading. It''s just amazing.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'and this is a story right he said you know if i wanted id turn this dome right over on the head of سليمان for you and سليمان عليه السلام knew the interpretation of birds so he called him down and so he comes down you know all shaking his little sparrow heart beating in his little sparrow chest and sulaiman says what made you say that ridiculous remark and the sparrow says o prophet of الله dont you know that lovers are never taken to account for what they say in the presence of their beloved in other words i was in a state of passion you cant take me to account for that and this is the reality around us right we get so these passionate displays of things and we have absolutely no idea what were doing what were reading its just amazing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 39, NULL, 'So build your skillset, study the قُرْآن, understand the قُرْآن, study the meanings of the دُعَاء, study the meanings of these supplications you say in your prayers, right? There are resources available. I mean, I did it. I learned the whole قُرْآن without, like most of it, I started off with my own self just by learning, you know, Google. And then I went to teachers and I had, you know, found the proper resources and did that. So can you. But do it slowly. Don''t have to do the whole thing in one day, gradually. And don''t worry how long it takes. Who cares? You have your whole lives ahead of you, مَا شَآءَ ٱللَّهُ.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so build your skillset study the قران understand the قران study the meanings of the دعاء study the meanings of these supplications you say in your prayers right there are resources available i mean i did it i learned the whole قران without like most of it i started off with my own self just by learning you know google and then i went to teachers and i had you know found the proper resources and did that so can you but do it slowly dont have to do the whole thing in one day gradually and dont worry how long it takes who cares you have your whole lives ahead of you ما شاء الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 40, NULL, 'So all I''m saying is get started. Start collecting these small twigs, but do it consistently and before you know it, you will be reciting with comprehension and gaining something from it. The next quality is that they are patient people, he said. They have . Be patient and enjoining others to patience. I''ll tell you, there are two lessons as far as I''m concerned that we have to learn. Because all of the tribulations coming to us are based on two things as far as I''m concerned. One is كِبْرٌ, arrogance and pride, and the other is lack of patience. Arrogance and the lack of patience. Until we get rid of this كِبْرٌ, this sense of superiority from our hearts and recognize that it is humility, تَوَادَّ, that elevates us in the eyes of اللَّه. Not arrogance and pride.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so all im saying is get started start collecting these small twigs but do it consistently and before you know it you will be reciting with comprehension and gaining something from it the next quality is that they are patient people he said they have be patient and enjoining others to patience ill tell you there are two lessons as far as im concerned that we have to learn because all of the tribulations coming to us are based on two things as far as im concerned one is كبر arrogance and pride and the other is lack of patience arrogance and the lack of patience until we get rid of this كبر this sense of superiority from our hearts and recognize that it is humility تواد that elevates us in the eyes of الله not arrogance and pride', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 41, NULL, 'Unless we do that, we are never going to be successful as individuals. We''re never going to be successful as a community. And we have to learn to be patient. This disease of just no patience at all, instant gratification, it''s destroying our spirituality. الْإِسْلَام is nothing if not delayed gratification. Our gratification is in the أَخَرَ, not in this دُنْيَا. And we have to learn to persevere. ‏وَأَن لَّيْسَ لِلْإِنسَنِ إِلَّا مَا سَعَىٰ ‎. No one has except what they endeavor for, what they persevere for. ‏وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ ‎. Indeed, you will see the efforts of your endeavor. On the Day of Judgment, اللَّه says, ‏إِنَّ هَذَا كَانَ لَكُمْ جَزَآءًۭ وَكَانَ سَعْيُكُم مَّشْكُورًا ‎. This is the reward for you and your efforts have been shown gratitude by اللَّهُ سُبْحَانَهُ وَتَعَالَى. We want اللَّه''s appreciation.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'unless we do that we are never going to be successful as individuals were never going to be successful as a community and we have to learn to be patient this disease of just no patience at all instant gratification its destroying our spirituality الاسلام is nothing if not delayed gratification our gratification is in the اخر not in this دنيا and we have to learn to persevere وان ليس للانسن الا ما سعي no one has except what they endeavor for what they persevere for وان سعيه سوف يري indeed you will see the efforts of your endeavor on the day of judgment الله says ان هذا كان لكم جزاء وكان سعيكم مشكورا this is the reward for you and your efforts have been shown gratitude by الله سبحانه وتعالي we want اللهs appreciation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 42, NULL, 'We don''t want this world''s praise. What good is that? How long is it going to last? And if we follow the teachings of the قُرْآن and if we follow the سُنَّة of our prophet, we can have both. Look at our prophet. 1400 years later, people are willing to die for his name. سُبْحَانَ اللَّهِ, that''s سَيْزَا. That''s glory, that''s fame, that''s respect. ‏وَمَنْ أَرَادَ ٱلْآخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌۭ فَأُو۟لَٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًۭا ‎, whoever desires the hereafter strives for it, right? Putting in the required work, he is a believer. كَانَ سَعْيُهُم مَّشْكُورًۭا, his efforts will be appreciated, they will be thanked and rewarded by God. So that''s the other one, you know, work on removing arrogance from your hearts and developing patience cause you guys, you don''t even let anybody say anything to you before you just explode.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'we dont want this worlds praise what good is that how long is it going to last and if we follow the teachings of the قران and if we follow the سنه of our prophet we can have both look at our prophet 1400 years later people are willing to die for his name سبحان الله thats سيزا thats glory thats fame thats respect ومن اراد الاخره وسعي لها سعيها وهو مومن فاوليك كان سعيهم مشكورا whoever desires the hereafter strives for it right putting in the required work he is a believer كان سعيهم مشكورا his efforts will be appreciated they will be thanked and rewarded by god so thats the other one you know work on removing arrogance from your hearts and developing patience cause you guys you dont even let anybody say anything to you before you just explode', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 43, NULL, 'So just take a chill pill, right? Relax. Then the last thing he said is the ability to love what one is doing. You have to love what you''re doing. They love اللَّه and اللَّه loves them. They''re pleased with اللَّه and اللَّه is pleased with them. And none of us truly believe until we love اللَّه and his messenger more than we love our own selves. And so working for اللَّهُ سُبْحَانَهُ وَتَعَالَى and his messenger صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ should be the most beloved thing to us. So this is the last quality, you have to love what you are doing. This is not a forced religion. Ours is not a forced religion. There is no compulsion in religion.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so just take a chill pill right relax then the last thing he said is the ability to love what one is doing you have to love what youre doing they love الله and الله loves them theyre pleased with الله and الله is pleased with them and none of us truly believe until we love الله and his messenger more than we love our own selves and so working for الله سبحانه وتعالي and his messenger صلي الله عليه وسلم should be the most beloved thing to us so this is the last quality you have to love what you are doing this is not a forced religion ours is not a forced religion there is no compulsion in religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 44, NULL, 'There is no force in religion. Ours is a religion of love. It is a religion of willing submission, not forced submission. And this is why I said earlier that this religion begins with a choice. I mean, you have to decide if الْإِسْلَام is for you or not. And if it is, then you have to make a conscious choice to accept it and then enjoy it. You have to love your الْإِسْلَام. If you''re doing it, if you''re following الْإِسْلَام with a resentment and a frustration or out of fear of getting burned in hellfire, there''s something very wrong with your understanding of this beautiful religion, I swear. I can honestly tell you, I love my الْإِسْلَام and I''m not a hermit. I''m as much out there living and enjoying life as the next person. I love hiking.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'there is no force in religion ours is a religion of love it is a religion of willing submission not forced submission and this is why i said earlier that this religion begins with a choice i mean you have to decide if الاسلام is for you or not and if it is then you have to make a conscious choice to accept it and then enjoy it you have to love your الاسلام if youre doing it if youre following الاسلام with a resentment and a frustration or out of fear of getting burned in hellfire theres something very wrong with your understanding of this beautiful religion i swear i can honestly tell you i love my الاسلام and im not a hermit im as much out there living and enjoying life as the next person i love hiking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 45, NULL, 'I keep going on trips all year long. But I try to prioritize my essentials. Every day I try to work on my character, adopt something good, leave something bad. And I fail more often than I succeed. Honestly, I fail more often than I succeed. So what? I try to celebrate what I did succeed in. And I try harder to work on what I failed at the next day. And thank God, I have friends who keep reminding me when I struggle. Those are the kinds of people you want in your life. People who lift you up when you''re down. Not those who want you to stay small.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'i keep going on trips all year long but i try to prioritize my essentials every day i try to work on my character adopt something good leave something bad and i fail more often than i succeed honestly i fail more often than i succeed so what i try to celebrate what i did succeed in and i try harder to work on what i failed at the next day and thank god i have friends who keep reminding me when i struggle those are the kinds of people you want in your life people who lift you up when youre down not those who want you to stay small', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 46, NULL, 'There are many people who want you to stay small. There''s Marianne Williamson, right? I''ve talked about her before also. Love her. In her book, she has this quote which is just incredible. There''s a book, Return to Love, that she wrote, and she says in that, our deepest fear is not that we are inadequate. Our deepest fear is that we are powerful beyond measure. It is our light, not our darkness, that frightens us most. We ask ourselves, who am I to be brilliant? Who am I to be gorgeous, talented or fabulous? Actually, who are you not to be? You are a child of God.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'there are many people who want you to stay small theres marianne williamson right ive talked about her before also love her in her book she has this quote which is just incredible theres a book return to love that she wrote and she says in that our deepest fear is not that we are inadequate our deepest fear is that we are powerful beyond measure it is our light not our darkness that frightens us most we ask ourselves who am i to be brilliant who am i to be gorgeous talented or fabulous actually who are you not to be you are a child of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 47, NULL, 'Your playing small does not serve the world. There''s nothing enlightened about shrinking so that other people won''t feel insecure around you. We were born to make manifest the glory of God that is within us. It''s not just in some of us. It''s in everyone. And as we let our own light shine, we unconsciously give other people the permission to do the same. As we are liberated from our own fear, our presence automatically liberates others. What a beautiful description of what a, like, I love this quote from this lady. So yeah, that is our, you know, don''t stay small, you are. You know, you are manifesting the glory of اللَّهُ سُبْحَانَهُ وَتَعَالَى, this خَلِيفَة on this earth. Don''t sell yourself short. So these are the qualities that he mentioned about success.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'your playing small does not serve the world theres nothing enlightened about shrinking so that other people wont feel insecure around you we were born to make manifest the glory of god that is within us its not just in some of us its in everyone and as we let our own light shine we unconsciously give other people the permission to do the same as we are liberated from our own fear our presence automatically liberates others what a beautiful description of what a like i love this quote from this lady so yeah that is our you know dont stay small you are you know you are manifesting the glory of الله سبحانه وتعالي this خليفه on this earth dont sell yourself short so these are the qualities that he mentioned about success', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 48, NULL, 'And you know, it all begins with waking up from our state of acedia, the spiritual laziness that I talked about earlier, because الْإِسْلَام is work. Anything that is valuable, beneficial, worth pursuing in your life. Tell me one thing that does not require work. Why would الْإِسْلَام be any different? But we are in the state of غَفْلَة, this heedlessness, like drowned in it. There''s a verse in the قُرْآن. اللَّه says, we have prepared for the hellfire multitudes from the jinn and human beings. And he says, what has made you know, and I''m saying this, that what has made these people eligible for hellfire, he describes that. He says, لَهُمْ قُلُوبٌۭ لَّا يَفْقَهُونَ بِهَا, they have hearts and they have intellects but they do not use them. They don''t use their intellects to reflect on what''s really good for them. وَلَهُمْ أَعْيُنٌۭ لَّا يُبْصِرُونَ بِهَا, they have eyes but they don''t see the true realities with it. وَلَهُمْ آذَانٌ, they have ears, but they don''t listen to the words of guidance. Then he says, these people are like dumb beasts. They are like cattle and sheep. But then اللَّه says, he says no. And this no here is rhetorical. In Arabic, بَلْ is used to clarify something.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'and you know it all begins with waking up from our state of acedia the spiritual laziness that i talked about earlier because الاسلام is work anything that is valuable beneficial worth pursuing in your life tell me one thing that does not require work why would الاسلام be any different but we are in the state of غفله this heedlessness like drowned in it theres a verse in the قران الله says we have prepared for the hellfire multitudes from the jinn and human beings and he says what has made you know and im saying this that what has made these people eligible for hellfire he describes that he says لهم قلوب لا يفقهون بها they have hearts and they have intellects but they do not use them they dont use their intellects to reflect on whats really good for them ولهم اعين لا يبصرون بها they have eyes but they dont see the true realities with it ولهم اذان they have ears but they dont listen to the words of guidance then he says these people are like dumb beasts they are like cattle and sheep but then الله says he says no and this no here is rhetorical in arabic بل is used to clarify something', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 49, NULL, 'So if you made a mistake or said something that was not clear enough, you use the word بَلْ to re-emphasize. So اللَّه is saying these heedless people are like animals. But let me clarify further. They are much worse than animals. Why? Because they are in a state of heedlessness. Now if you look at the animal kingdom, you will not find animals in a state of heedlessness. Animals, no matter what they are doing, they are always in a state of awareness. If you watch a dog eat or a rabbit eat, right? Rabbits, right? They''re constantly moving their ears around.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'so if you made a mistake or said something that was not clear enough you use the word بل to re emphasize so الله is saying these heedless people are like animals but let me clarify further they are much worse than animals why because they are in a state of heedlessness now if you look at the animal kingdom you will not find animals in a state of heedlessness animals no matter what they are doing they are always in a state of awareness if you watch a dog eat or a rabbit eat right rabbits right theyre constantly moving their ears around', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 50, NULL, 'Why? Because they''re worried. They''re constantly worried about these external threats, external dangers. Watch a mouse come out of its hole. It doesn''t just saunter out of its hole. It comes out slow. It moves its head around, right? Checks out the surroundings. To me, that is تَقْوَى. Seriously, you wanna learn تَقْوَى? Watch a mouse come out of its hole. That''s God consciousness.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'why because theyre worried theyre constantly worried about these external threats external dangers watch a mouse come out of its hole it doesnt just saunter out of its hole it comes out slow it moves its head around right checks out the surroundings to me that is تقوي seriously you wanna learn تقوي watch a mouse come out of its hole thats god consciousness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 51, NULL, 'That''s how we need to be, that level of awareness of God. We can learn a lot from animals, right? That''s why اللَّه uses them as metaphors in the قُرْآن. Look at the lizard. Ever seen a lizard come out of its hole? It''s constantly looking back and forth, right? Right and left. The Arabs say more bewildered than a lizard. Because if you look at a lizard, it''s just constantly moving its head because it, like, it''s bewildered. But what is it really doing? It''s checking. Is there danger out there?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'thats how we need to be that level of awareness of god we can learn a lot from animals right thats why الله uses them as metaphors in the قران look at the lizard ever seen a lizard come out of its hole its constantly looking back and forth right right and left the arabs say more bewildered than a lizard because if you look at a lizard its just constantly moving its head because it like its bewildered but what is it really doing its checking is there danger out there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 52, NULL, 'It''s thinking. Animals are constantly aware of danger. Why? Because if they''re not constantly aware, their existence is threatened. They realize that if they are in a state of heedlessness, they are endangering themselves. And this is why اللَّه says these people are like animals. In fact, they are more astray than animals because animals are not in a state of heedlessness about the danger that is threatening them. But we human beings, constant state of heedlessness about our spiritual survival. We don''t care. Seriously. Animals, if they sense fire, they run. What do we do?', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'its thinking animals are constantly aware of danger why because if theyre not constantly aware their existence is threatened they realize that if they are in a state of heedlessness they are endangering themselves and this is why الله says these people are like animals in fact they are more astray than animals because animals are not in a state of heedlessness about the danger that is threatening them but we human beings constant state of heedlessness about our spiritual survival we dont care seriously animals if they sense fire they run what do we do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 53, NULL, 'We call each other up. Hey, there''s this huge fire there. Let''s go check it out. Right? Taking selfies in front of the fire. I''m not making this up, right? This happens or not. Because it''s all fun. It''s all entertaining. Everything. We''re drowned in fun and entertainment. Everything is a joke.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'we call each other up hey theres this huge fire there lets go check it out right taking selfies in front of the fire im not making this up right this happens or not because its all fun its all entertaining everything were drowned in fun and entertainment everything is a joke', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 54, NULL, 'Everything is a fun. The world is fun. The أَخَّرَ is fun. And we''re not realizing that we are dying spiritually. We are dying. People, your oppression is only harming you. It''s killing you. We have to change. I mean, how much selfishness can go on? I want you kids to grow up in a world that facilitates your humanity. I want a world for you that doesn''t destroy your humanity or take it away from you. I want a world that does not deprive you of this quality, right? It''s your birthright. It''s your birthright to become a human being, to not operate at the level of animals. It''s your birthright to become real people. Not to become junk people that spend their lives in these trivialized malls buying all this junk crap to fill their junk life. When are we going to wake up? When are we going to respond to the call of اللَّه and His messenger? يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ. O you who believe, answer اللَّه and His messenger when they call you to the path that will give you life. إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ, when they call you to that which gives you life, that will make you feel alive. When are we going to answer that call? When are we going to respond to that call of اللَّه and His messenger to something that will bring us to life? And the implication in that آيَةٌ is that as long as we do not respond to that call, we''re dead people. Literally, we are dead people. Our hearts are dead. Our lives are dead.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'everything is a fun the world is fun the اخر is fun and were not realizing that we are dying spiritually we are dying people your oppression is only harming you its killing you we have to change i mean how much selfishness can go on i want you kids to grow up in a world that facilitates your humanity i want a world for you that doesnt destroy your humanity or take it away from you i want a world that does not deprive you of this quality right its your birthright its your birthright to become a human being to not operate at the level of animals its your birthright to become real people not to become junk people that spend their lives in these trivialized malls buying all this junk crap to fill their junk life when are we going to wake up when are we going to respond to the call of الله and his messenger يا ايها الذين امنوا استجيبوا لله وللرسول اذا دعاكم لما يحييكم o you who believe answer الله and his messenger when they call you to the path that will give you life اذا دعاكم لما يحييكم when they call you to that which gives you life that will make you feel alive when are we going to answer that call when are we going to respond to that call of الله and his messenger to something that will bring us to life and the implication in that ايه is that as long as we do not respond to that call were dead people literally we are dead people our hearts are dead our lives are dead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 55, NULL, 'Our society is a society of death. We live in a society that celebrates the death of the spirit in giving life, in giving life to the lowest pursuits of humanity. This is the death of the soul because the soul can only be brought back to life by recognizing what it was created for. For recognizing what its purpose is and then setting out and striving to achieve that goal. Recognizing that we will have shortcomings. That we will make mistakes. That those mistakes are part of our humanity. That اللَّهُ سُبْحَانَهُ وَتَعَالَى knows those mistakes. So he will forgive us when we turn to him. That is why we were created. We were created to respond to our أَبُو ضِيَاء, our servitude to اللَّه سُبْحَانَهُ وَتَعَالَى. And the only way, the only way a slave feels its وُدِّيَ, its servanthood, is in its abject nature, that if we do wrong we desire the atonement so that we can reconnect with our true nature. This is why we were given the gift of وُدُّهُ. This is why we were given the gift of صَلَاةٌ. What beautiful gifts.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'our society is a society of death we live in a society that celebrates the death of the spirit in giving life in giving life to the lowest pursuits of humanity this is the death of the soul because the soul can only be brought back to life by recognizing what it was created for for recognizing what its purpose is and then setting out and striving to achieve that goal recognizing that we will have shortcomings that we will make mistakes that those mistakes are part of our humanity that الله سبحانه وتعالي knows those mistakes so he will forgive us when we turn to him that is why we were created we were created to respond to our ابو ضياء our servitude to الله سبحانه وتعالي and the only way the only way a slave feels its ودي its servanthood is in its abject nature that if we do wrong we desire the atonement so that we can reconnect with our true nature this is why we were given the gift of وده this is why we were given the gift of صلاه what beautiful gifts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 56, NULL, 'What a beautiful gift to purify ourselves five times a day and stand before our Lord desiring atonement for our sins and for strength for our future actions. What a gift. We are just wasting away the preciousness of our lives. I mean, you have one short life to do something, to do something great, to be great people, one short span. Look what people are doing to relieve the stress around them, to just to relieve this, this empty meaningless life, just to taste this one moment, to have an adrenaline rush, to feel alive. That''s all they''re trying to do. They''re trying to feel alive because they''re dead. They are dead people. And by jumping off a bridge with a rubber string attached to them and seeing this pavement, this cement pavement, come towards them, heading right for it, suddenly this person feels for one moment that he''s actually alive, and then he wants to repeat that experience because he wants to feel alive. That is not the life human beings were created for. It''s not through adrenaline rushes. It''s not through the rush of drugs penetrating your brain. It''s not through the rush of cocaine.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'what a beautiful gift to purify ourselves five times a day and stand before our lord desiring atonement for our sins and for strength for our future actions what a gift we are just wasting away the preciousness of our lives i mean you have one short life to do something to do something great to be great people one short span look what people are doing to relieve the stress around them to just to relieve this this empty meaningless life just to taste this one moment to have an adrenaline rush to feel alive thats all theyre trying to do theyre trying to feel alive because theyre dead they are dead people and by jumping off a bridge with a rubber string attached to them and seeing this pavement this cement pavement come towards them heading right for it suddenly this person feels for one moment that hes actually alive and then he wants to repeat that experience because he wants to feel alive that is not the life human beings were created for its not through adrenaline rushes its not through the rush of drugs penetrating your brain its not through the rush of cocaine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 57, NULL, 'It''s not through alcohol numbing your mind. It''s not through the rush of jumping out of an airplane or skydiving. Those are not the things that will make you feel alive. The only thing that will make you feel alive is becoming a slave of the الحُبُّ, by becoming slaves of the ever living who never dies. And this is our challenge. This is the challenge of human beings and this is what we have to wake up to. I''m going to end this today''s session with the حَدِيث from our Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. And you know, and this is, this whole conversation, everything I''ve said so far is for you guys, you kids, you young adults, which I keep saying because, you know, the elders already know all of this. But this I thought was something which might really help you. I hope and pray that it helps you.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'its not through alcohol numbing your mind its not through the rush of jumping out of an airplane or skydiving those are not the things that will make you feel alive the only thing that will make you feel alive is becoming a slave of the الحب by becoming slaves of the ever living who never dies and this is our challenge this is the challenge of human beings and this is what we have to wake up to im going to end this todays session with the حديث from our prophet صلي الله عليه وسلم and you know and this is this whole conversation everything ive said so far is for you guys you kids you young adults which i keep saying because you know the elders already know all of this but this i thought was something which might really help you i hope and pray that it helps you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 58, NULL, 'There''s a حَدِيث of our Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, he said, الْإِسْلَام began as a stranger and there shall come a time when it becomes estranged again, just the way it began. الْإِسْلَام began as a stranger and towards the end of the time it will become a stranger again. Strange here does not mean weird. Strange does not mean something out of this world. It means that the society we live in, the society that you live in, is going to find الْإِسْلَام and its followers strange. Why? Because الْإِسْلَام began at a time when people were chasing and worshipping their desires, their appetites. They were worshipping multiple gods. Might was right. The rich were honored and the poor were abased. Evil was strong and good was weak. That''s how الْإِسْلَام began.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'theres a حديث of our prophet صلي الله عليه وسلم he said الاسلام began as a stranger and there shall come a time when it becomes estranged again just the way it began الاسلام began as a stranger and towards the end of the time it will become a stranger again strange here does not mean weird strange does not mean something out of this world it means that the society we live in the society that you live in is going to find الاسلام and its followers strange why because الاسلام began at a time when people were chasing and worshipping their desires their appetites they were worshipping multiple gods might was right the rich were honored and the poor were abased evil was strong and good was weak thats how الاسلام began', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 59, NULL, 'Today, we see that we''ve come full circle. The world is once again worshipping their desires. The world is once again in submission to the gods of money, god of fame, the god of power, the god of stature, the god of looks, of pride, vanity. Might is once again right, evil is once again ruling the world, and righteousness is once again weak and on its knees. بَدَأَ الإِسْلَامُ غَرِيبًا وَسَيَعُودُ غَرِيبًا كَمَا بَدَأَ. الْإِسْلَام began as a stranger, and towards the end of time, it will become a stranger again. But then he said, طُوبَى لِلْغُرَبَاءِ. There is immense good tidings for the estranged. When you are strange, you act in ways that are very different from what everybody else around you is doing. That''s what makes you strange. When you wake up in the night to worship اللَّه, when the world around you is sound asleep, you are strange.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'today we see that weve come full circle the world is once again worshipping their desires the world is once again in submission to the gods of money god of fame the god of power the god of stature the god of looks of pride vanity might is once again right evil is once again ruling the world and righteousness is once again weak and on its knees بدا الاسلام غريبا وسيعود غريبا كما بدا الاسلام began as a stranger and towards the end of time it will become a stranger again but then he said طوبي للغرباء there is immense good tidings for the estranged when you are strange you act in ways that are very different from what everybody else around you is doing thats what makes you strange when you wake up in the night to worship الله when the world around you is sound asleep you are strange', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 60, NULL, 'When you speak about pleasing اللَّه and making him your objective in life, when the world is making fun of religion and mocking God, you are strange. When اللَّه and His Prophet is your sole objective, because اللَّه said, O Messenger of اللَّه, tell them that indeed اللَّه should be their ultimate objective. So when you have made اللَّه as your objective in a world that has the fulfillment of their desire as their primary objective, you are strange. When you dress modestly in a world that celebrates nudity, you are strange. When you refuse to smoke, to drink, to do drugs, when the rest of the world is celebrating and glorifying these things, you are strange. When you help a needy with your charity in a world that is hoarding wealth, you are strange. When you are saving yourself from marriage, when the entire world is celebrating fornication, you are strange. When you respect your parents, when you respect your elders, your teachers, when the entire world is finding it so cool to disrespect them, to make fun of them, you are strange. When you honor اللَّه''s gifts of food and drink, when you conserve natural resources while the world is busy wasting and destroying them, you are strange. When you stay humble in a world that celebrates arrogance, that celebrates pride, vanity, you are strange.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'when you speak about pleasing الله and making him your objective in life when the world is making fun of religion and mocking god you are strange when الله and his prophet is your sole objective because الله said o messenger of الله tell them that indeed الله should be their ultimate objective so when you have made الله as your objective in a world that has the fulfillment of their desire as their primary objective you are strange when you dress modestly in a world that celebrates nudity you are strange when you refuse to smoke to drink to do drugs when the rest of the world is celebrating and glorifying these things you are strange when you help a needy with your charity in a world that is hoarding wealth you are strange when you are saving yourself from marriage when the entire world is celebrating fornication you are strange when you respect your parents when you respect your elders your teachers when the entire world is finding it so cool to disrespect them to make fun of them you are strange when you honor اللهs gifts of food and drink when you conserve natural resources while the world is busy wasting and destroying them you are strange when you stay humble in a world that celebrates arrogance that celebrates pride vanity you are strange', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 61, NULL, 'When you take out time to recite and study and understand the قُرْآن, and you make time to learn about your prophet while the rest of this world is drowned in chasing the world or endless hours of mindless Netflix and Prime Video, you are strange. And my Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ said, طُوبَى لِلْغُرَبَاءِ. There is glad tidings, good tidings for the estranged. So my advice to you is better be a stranger in this temporary life than a stranger with اللَّه and His Messenger on the Day of Judgment. We do not want to be people on that day that says, يَا وَيْلَنَا مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا. Woe be unto us. Shame be unto us. Why have we been raised from our graves? I wish we were never raised from our graves. We don''t want to be that people. We don''t want to be the people who say, يَا وَيْلَنَا هَذَا يَوْمُ الدِّينِ. Woe to us! This is the day of judgment that we had been warned about and we never paid attention to it. We don''t want to be that people.', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'when you take out time to recite and study and understand the قران and you make time to learn about your prophet while the rest of this world is drowned in chasing the world or endless hours of mindless netflix and prime video you are strange and my prophet صلي الله عليه وسلم said طوبي للغرباء there is glad tidings good tidings for the estranged so my advice to you is better be a stranger in this temporary life than a stranger with الله and his messenger on the day of judgment we do not want to be people on that day that says يا ويلنا من بعثنا من مرقدنا woe be unto us shame be unto us why have we been raised from our graves i wish we were never raised from our graves we dont want to be that people we dont want to be the people who say يا ويلنا هذا يوم الدين woe to us this is the day of judgment that we had been warned about and we never paid attention to it we dont want to be that people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'chapter', 'a model for success', 'A Model For Success', 62, NULL, 'We don''t want to say to our Lord, فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ. Master, if you send us back in the world, we promise we will believe in everything that you said, and we will become righteous. No, we want to be people who are greeted and welcomed by اللَّه and His Prophet in the afterlife. We want to be people that they say, يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَرْضِيَّةً. Oh my beautiful and content soul, return to your master in a state that you are pleased with your Lord and he is pleased with you. Enter the company of my beloved slaves, enter my paradise. (الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ الْخَاتِمِ النَّبِيِّينَ سَيِّدِ الْمُرْسَلِينَ، مُصْطَفَاهُ وَوَاسِعِ الْبِشَارَاتِ الْوَاسِعِينَ)', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'we dont want to say to our lord فيقول رب لولا اخرتني الي اجل قريب master if you send us back in the world we promise we will believe in everything that you said and we will become righteous no we want to be people who are greeted and welcomed by الله and his prophet in the afterlife we want to be people that they say يا ايتها النفس المطمينه ارجعي الي ربك راضيه مرضيه oh my beautiful and content soul return to your master in a state that you are pleased with your lord and he is pleased with you enter the company of my beloved slaves enter my paradise الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد الخاتم النبيين سيد المرسلين مصطفاه وواسع البشارات الواسعين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'episode', NULL, 'Love Based Religion', 0, 1, 'Love Based Religion Loving Rasul Allah (SWS) is the cornerstone of faith, as true love for Allah is demonstrated by following His beloved Prophet. This love is a seed nurtured by knowledge, which grows into a passionate devotion that transforms one''s character. By recognizing the universe as signs pointing to the Creator, we find ultimate felicity not in worldly pursuits but in willing submission to Allah, a submission born from this profound love.', '', NULL, NULL, NULL, NULL, 'love of the prophet love based religion', 'love based religion loving rasul allah sws is the cornerstone of faith as true love for allah is demonstrated by following his beloved prophet this love is a seed nurtured by knowledge which grows into a passionate devotion that transforms ones character by recognizing the universe as signs pointing to the creator we find ultimate felicity not in worldly pursuits but in willing submission to allah a submission born from this profound love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'episode', NULL, 'Need For Messengers', 0, 2, 'Need For Messengers we look at the purpose of sending messengers, and their role in our spiritual awakening.', '', NULL, NULL, NULL, NULL, 'love of the prophet need for messengers', 'need for messengers we look at the purpose of sending messengers and their role in our spiritual awakening', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'episode', NULL, 'Islam As An Experience', 0, 3, 'Islam As An Experience We look at the experience of Islam by connecting with the prophet''s experience. We study his experience of revelation and ascension.', '', NULL, NULL, NULL, NULL, 'love of the prophet islam as an experience', 'islam as an experience we look at the experience of islam by connecting with the prophets experience we study his experience of revelation and ascension', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'episode', NULL, 'Character Of The Prophet', 0, 4, 'Character Of The Prophet we understand how the exemplary character of our prophet (Salallahu alayhi wa aalihee wa sallam) was a miracle for non-Arabs.', '', NULL, NULL, NULL, NULL, 'love of the prophet character of the prophet', 'character of the prophet we understand how the exemplary character of our prophet salallahu alayhi wa aalihee wa sallam was a miracle for non arabs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('love-of-the-prophet', 'episode', NULL, 'A Model For Success', 0, 5, 'A Model For Success This sermon redefines success and failure through an Islamic lens, contrasting worldly metrics with spiritual purification. It outlines ten key qualities for achieving true success, supported by Quranic principles and the lives of exemplary figures from Islamic history. The sermon also warns against the spiritual danger of heedlessness, urging a conscious return to a life of purpose. It concludes by embracing the ''strangeness'' of adhering to faith in a secular world,', '', NULL, NULL, NULL, NULL, 'love of the prophet a model for success', 'a model for success this sermon redefines success and failure through an islamic lens contrasting worldly metrics with spiritual purification it outlines ten key qualities for achieving true success supported by quranic principles and the lives of exemplary figures from islamic history the sermon also warns against the spiritual danger of heedlessness urging a conscious return to a life of purpose it concludes by embracing the strangeness of adhering to faith in a secular world', '');
